import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

func main() {
	// Define flags
	excludeExt := flag.String("exclude-ext", "", "Comma-separated file extensions to exclude (e.g., .log,.tmp)")
	excludeDir := flag.String("exclude-dir", "", "Comma-separated directory names to exclude")
	flag.Parse()

	args := flag.Args()
	if len(args) != 1 {
		fmt.Println("Usage: dirsize [--exclude-ext=.ext1,.ext2] [--exclude-dir=dir1,dir2] <directory>")
		os.Exit(1)
	}
	root := args[0]

	// Parse file extension exclusions, normalising to start with a dot
	extExcl := make(map[string]bool)
	if *excludeExt != "" {
		for _, ext := range strings.Split(*excludeExt, ",") {
			ext = strings.TrimSpace(ext)
			if ext != "" {
				if ext[0] != '.' {
					ext = "." + ext
				}
				extExcl[ext] = true
			}
		}
	}

	// Parse directory name exclusions
	dirExcl := make(map[string]bool)
	if *excludeDir != "" {
		for _, d := range strings.Split(*excludeDir, ",") {
			d = strings.TrimSpace(d)
			if d != "" {
				dirExcl[d] = true
			}
		}
	}

	var totalSize int64
	err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error accessing %s: %v\n", path, err)
			return nil
		}

		// If directory, skip entirely if its name is in the exclude list
		if info.IsDir() {
			if dirExcl[info.Name()] {
				return filepath.SkipDir
			}
			return nil
		}

		// Process only regular files
		if !info.Mode().IsRegular() {
			return nil
		}

		// Skip files with excluded extensions
		if len(extExcl) > 0 {
			if extExcl[filepath.Ext(info.Name())] {
				return nil
			}
		}

		totalSize += info.Size()
		return nil
	})

	if err != nil {
		fmt.Fprintf(os.Stderr, "Error walking directory: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Total size: %s\n", humanReadable(totalSize))
}

// humanReadable converts bytes to a human-readable string (e.g., 1.50 MB)
func humanReadable(size int64) string {
	const unit = 1024
	if size < unit {
		return fmt.Sprintf("%d bytes", size)
	}
	div, exp := int64(unit), 0
	for n := size / unit; n >= unit; n /= unit {
		div *= unit
		exp++
	}
	return fmt.Sprintf("%.2f %cB", float64(size)/float64(div), "KMGTPE"[exp])
}
