### 2. Service-Layer Code Changes

All changes are backward‑compatible. Missing headers are generated safely.

#### 2.1 Correlation ID Middleware
*File: `middleware/correlationId.ts`*

```typescript
import { v4 as uuidv4 } from 'uuid';
import { AsyncLocalStorage } from 'async_hooks';

const ctx = new AsyncLocalStorage<{ correlationId: string }>();

export function correlationIdMiddleware(req, res, next) {
    const header = req.headers['x-correlation-id'] ?? req.headers['x-correlation-id'];
    const correlationId = typeof header === 'string' && header.length > 0 ? header : uuidv4();

    ctx.run({ correlationId }, () => {
        res.setHeader('x-correlation-id', correlationId);
        next();
    });
}

export function getCorrelationId(): string {
    return ctx.getStore()?.correlationId ?? 'unknown';
}
```

#### 2.2 Payment Service – Idempotency & Retry Logic
*File: `services/paymentService.ts`*

```typescript
import { Pool, escape } from 'mysql2/promise';
import { getCorrelationId } from '../middleware/correlationId';
import { recordOutboxMessage } from './outboxService';
import { payWithProvider } from './providerGateway';
import { createHash } from 'crypto';
import retry from 'async-retry';

const pool = new Pool({ /* config */ });
const MAX_SYNC_RETRIES = 3;

/**
 * @param orderId          required
 * @param amount           in minor units
 * @param currency
 * @param idempotencyKey?  client-supplied or generated
 * @returns existing or new payment transaction
 */
export async function charge(
    orderId: string,
    amount: number,
    currency: string = 'USD',
    idempotencyKey?: string
) {
    const correlationId = getCorrelationId();

    // Backward compatibility: derive key from orderId if not provided
    const effectiveKey =
        idempotencyKey ??
        createHash('sha256').update(orderId).digest('hex');

    // 1. Idempotency guard with INSERT … ON DUPLICATE
    const conn = await pool.getConnection();
    try {
        await conn.beginTransaction();

        const [existing] = await conn.query(
            `SELECT status, provider_txn_id, provider_response
             FROM payment_transactions
             WHERE idempotency_key = ? FOR UPDATE`, [effectiveKey]
        );

        if (existing.length > 0) {
            const row = existing[0];
            // Terminal state – return stored result
            if (row.status === 'SUCCESS' || row.status === 'FAILED') {
                await conn.commit();
                return {
                    status: row.status,
                    providerTransactionId: row.provider_txn_id,
                    duplicate: true
                };
            }
            // Still processing – reject to avoid concurrent charge attempts
            if (row.status === 'PROCESSING' || row.status === 'PENDING') {
                await conn.commit();
                const err: any = new Error('Payment already being processed');
                err.statusCode = 409;
                err.correlationId = correlationId;
                throw err;
            }
        }

        // Insert as PENDING (PROCESSING will be set after lock acquired)
        await conn.query(
            `INSERT INTO payment_transactions
                (idempotency_key, order_id, amount, currency, status, correlation_id)
             VALUES (?, ?, ?, ?, 'PROCESSING', ?)`,
            [effectiveKey, orderId, amount, currency, correlationId]
        );

        await conn.commit();        // Release lock before provider call
    } finally {
        conn.release();
    }

    // 2. Charge provider with retry + provider‑level idempotency
    let lastError: any;
    try {
        const result = await retry(
            async (bail) => {
                try {
                    return await payWithProvider({
                        amount,
                        currency,
                        orderId,
                        idempotencyKey: effectiveKey,   // critical!
                        correlationId
                    });
                } catch (err: any) {
                    // Do NOT retry non‑transient errors (4xx, validation)
                    if (err.statusCode && err.statusCode < 500) {
                        bail(err);
                    }
                    throw err;   // transient → retry
                }
            },
            {
                retries: MAX_SYNC_RETRIES,
                minTimeout: 200,
                maxTimeout: 2000,
                factor: 2,
                onRetry: (err, attempt) => {
                    logger.warn(
                        `Payment retry ${attempt}/${MAX_SYNC_RETRIES} for key ${effectiveKey}`,
                        { correlationId, error: err.message }
                    );
                }
            }
        );

        // 3. Update to SUCCESS
        await updateTransactionStatus(effectiveKey, 'SUCCESS', {
            providerName: result.providerName,
            providerTxnId: result.transactionId,
            providerResponse: result.rawResponse
        });

        // 4. Outbox event
        await recordOutboxMessage(
            'payment.completed',
            effectiveKey,
            { orderId, status: 'SUCCESS', providerTxnId: result.transactionId },
            correlationId
        );

        return { status: 'SUCCESS', providerTransactionId: result.transactionId };
    } catch (err: any) {
        lastError = err;
        logger.error(`Payment failed for key ${effectiveKey}`, { correlationId, err });

        // If we bailed (non‑transient) or exhausted retries (transient)
        // we must decide whether to fail immediately or enqueue for async replay.
        if (err.statusCode && err.statusCode < 500) {
            // Permanent failure
            await updateTransactionStatus(effectiveKey, 'FAILED', {
                providerResponse: { error: err.message }
            });
            await recordOutboxMessage(
                'payment.failed',
                effectiveKey,
                { orderId, status: 'FAILED', reason: err.message },
                correlationId
            );
            const outErr: any = new Error(err.message);
            outErr.statusCode = err.statusCode || 402;
            outErr.correlationId = correlationId;
            throw outErr;
        }

        // Transient failure → keep as PROCESSING and produce replay event
        // (The client receives 202 Accepted with a status polling URL)
        await recordOutboxMessage(
            'payment.retry',
            effectiveKey,
            { orderId, amount, currency, attempts: MAX_SYNC_RETRIES },
            correlationId
        );

        const ackErr: any = new Error('Payment is being processed asynchronously');
        ackErr.statusCode = 202;
        ackErr.correlationId = correlationId;
        ackErr.retryAfter = 30;
        throw ackErr;
    }
}

async function updateTransactionStatus(
    key: string,
    status: string,
    extra: Record<string, any> = {}
) {
    const fields = Object.entries(extra).map(([col, val]) =>
        `${escape(col)} = ${escape(val)}`
    );
    await pool.query(
        `UPDATE payment_transactions
         SET status = ?, ${fields.join(', ')}
         WHERE idempotency_key = ? AND status = 'PROCESSING'`,
        [status, key]
    );
}
```

#### 2.3 Outbox Service (Kafka Producer)
*File: `services/outboxService.ts`*

```typescript
import { Pool } from 'mysql2/promise';

export async function recordOutboxMessage(
    topic: string,
    key: string | null,
    payload: object,
    correlationId: string
) {
    // Writes atomically inside the same DB transaction as the payment update.
    // A separate process (e.g., Debezium, or a cron poller) reads rows with
    // status='PENDING' and publishes to Kafka.
    const conn = await getConnection(); // re‑use existing connection if in txn
    await conn.query(
        `INSERT INTO outbox_messages (topic, message_key, payload, correlation_id)
         VALUES (?, ?, ?, ?)`,
        [topic, key, JSON.stringify(payload), correlationId]
    );
}
```

