class Solution:
    def get_subarray_count(self, arr, k):
        # Dictionary to store frequency of cumulative sums
        cum_sum_freq = {0: 1}
        cum_sum = 0
        count = 0

        for num in arr:
            cum_sum += num
            # Check if there is a subarray ending at current index with sum k
            if cum_sum - k in cum_sum_freq:
                count += cum_sum_freq[cum_sum - k]
            # Update the frequency of current cumulative sum
            cum_sum_freq[cum_sum] = cum_sum_freq.get(cum_sum, 0) + 1

        return count
