                    gameState.ship.alive = true;
                    gameState.ship.invincible = INVINCIBILITY_DURATION;
                }
            }

            // --- Ship invincibility countdown ---
            if (gameState.ship.invincible > 0) {
                gameState.ship.invincible -= delta;
            }

            // --- Shoot cooldown ---
            if (gameState.shootCooldown > 0) {
                gameState.shootCooldown -= delta;
            }

            // --- Ship input & movement (only when alive) ---
            const ship = gameState.ship;
            if (ship.alive) {
