                ship.thrusting = !!(keys['ArrowUp'] || keys['w'] || keys['W']);
                if (ship.thrusting) {
                    ship.vx += Math.cos(ship.angle) * SHIP_THRUST * delta;
                    ship.vy += Math.sin(ship.angle) * SHIP_THRUST * delta;
                }

                // Subtle friction
                const friction = Math.pow(SHIP_FRICTION, delta);
                ship.vx *= friction;
                ship.vy *= friction;

                // Speed cap
                const speed = Math.sqrt(ship.vx ** 2 + ship.vy ** 2);
                if (speed > SHIP_MAX_SPEED) {
                    const scale = SHIP_MAX_SPEED / speed;
                    ship.vx *= scale;
                    ship.vy *= scale;
                }

                // Move ship & wrap
                ship.x += ship.vx * delta;
                ship.y += ship.vy * delta;
                wrapPosition(ship);

                // --- Shooting ---
                if ((keys[' '] || keys['Space']) && gameState.shootCooldown <= 0 &&
                    gameState.bullets.length < MAX_BULLETS) {
                    // Spawn bullet at ship's tip
                    const tipX = ship.x + Math.cos(ship.angle) * SHIP_SIZE;
                    const tipY = ship.y + Math.sin(ship.angle) * SHIP_SIZE;
                    gameState.bullets.push({
                        x: tipX,
                        y: tipY,
                        vx: Math.cos(ship.angle) * BULLET_SPEED,
                        vy: Math.sin(ship.angle) * BULLET_SPEED,
                        lifetime: BULLET_LIFETIME,
                    });
                    gameState.shootCooldown = SHOOT_COOLDOWN;
                }
            }

            // --- Update bullets ---
            for (let i = gameState.bullets.length - 1; i >= 0; i--) {
                const b = gameState.bullets[i];
                b.x += b.vx * delta;
                b.y += b.vy * delta;
                b.lifetime -= delta;
                wrapPosition(b);
                if (b.lifetime <= 0) {
                    gameState.bullets.splice(i, 1);
                }
            }

            // --- Update asteroids ---
            for (const a of gameState.asteroids) {
                a.x += a.vx * delta;
                a.y += a.vy * delta;
                a.angle += a.rotationSpeed * delta;
                wrapPosition(a);
            }

            // --- Bullet-Asteroid collision detection ---
            const bulletsToRemove = new Set();
            const asteroidsToRemove = new Set();
            const newAsteroids = [];

            for (let i = 0; i < gameState.bullets.length; i++) {
                if (bulletsToRemove.has(i)) continue;
                const b = gameState.bullets[i];
                for (let j = 0; j < gameState.asteroids.length; j++) {
                    if (asteroidsToRemove.has(j)) continue;
                    const a = gameState.asteroids[j];
                    if (distance(b, a) < a.radius) {
                        // Hit! Mark both for removal
                        bulletsToRemove.add(i);
                        asteroidsToRemove.add(j);

                        // Add score
                        gameState.score += a.score;

                        // Create explosion particles
                        createExplosion(a.x, a.y, a.size);

                        // Split asteroid if not small
                        if (a.size === 'large') {
                            newAsteroids.push(createAsteroid('medium', a.x, a.y, a.vx, a.vy));
                            newAsteroids.push(createAsteroid('medium', a.x, a.y, a.vx, a.vy));
                        } else if (a.size === 'medium') {
                            newAsteroids.push(createAsteroid('small', a.x, a.y, a.vx, a.vy));
                            newAsteroids.push(createAsteroid('small', a.x, a.y, a.vx, a.vy));
                        }
                        // small asteroids just disappear

                        break; // one bullet can only hit one asteroid
                    }
                }
            }

            // Apply removals
            gameState.bullets = gameState.bullets.filter((_, i) => !bulletsToRemove.has(i));
            gameState.asteroids = gameState.asteroids.filter((_, j) => !asteroidsToRemove.has(j));
            gameState.asteroids.push(...newAsteroids);

            // --- Ship-Asteroid collision (only if ship alive & not invincible) ---
            if (ship.alive && ship.invincible <= 0) {
