                        gameState.lives--;

                        if (gameState.lives > 0) {
                            gameState.respawnTimer = RESPAWN_DELAY;
                        } else {
                            gameState.gameOver = true;
                            // Clear asteroids and bullets on game over for clean screen
                            // (We'll keep particles for the visual)
                        }
                        break; // only die once per frame
                    }
                }
            }

            // --- Level completion check ---
            if (!gameState.gameOver && gameState.asteroids.length === 0 && gameState.respawnTimer <= 0 && ship
                .alive) {
                // Advance to next level
                gameState.level++;
                // Clear remaining bullets
                gameState.bullets = [];
                // Spawn new set (more asteroids per level)
                const count = INITIAL_ASTEROID_COUNT + (gameState.level - 1);
                spawnLevelAsteroids(Math.min(count, 14)); // cap at 14 large asteroids
                // Reset ship position for safety
                ship.x = W / 2;
                ship.y = H / 2;
                ship.vx = 0;
                ship.vy = 0;
                ship.invincible = 60; // brief invincibility on new level
            }
        }

        // ──────────────────────────────────────────────
        //  8. RENDERING (draw everything to canvas)
        // ──────────────────────────────────────────────
        function render() {
            // Clear canvas
            ctx.fillStyle = '#000';
            ctx.fillRect(0, 0, W, H);

            // --- Draw starfield ---
            for (const star of gameState.stars) {
                ctx.fillStyle = `rgba(255, 255, 255, ${star.alpha})`;
                ctx.beginPath();
                ctx.arc(star.x, star.y, star.radius, 0, Math.PI * 2);
                ctx.fill();
            }

            // --- Draw particles ---
            for (const p of gameState.particles) {
                const alpha = Math.max(0, p.lifetime / p.maxLifetime);
                ctx.fillStyle = `rgba(255, 255, 255, ${alpha})`;
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                ctx.fill();
            }

            // --- Draw asteroids ---
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1.5;
            for (const a of gameState.asteroids) {
                ctx.beginPath();
                const verts = a.vertices;
                const firstV = verts[0];
                const fx = a.x + Math.cos(firstV.angle + a.angle) * firstV.dist;
                const fy = a.y + Math.sin(firstV.angle + a.angle) * firstV.dist;
                ctx.moveTo(fx, fy);
                for (let i = 1; i < verts.length; i++) {
                    const v = verts[i];
                    const vx = a.x + Math.cos(v.angle + a.angle) * v.dist;
                    const vy = a.y + Math.sin(v.angle + a.angle) * v.dist;
                    ctx.lineTo(vx, vy);
                }
                ctx.closePath();
                ctx.stroke();
            }

            // --- Draw bullets ---
            ctx.fillStyle = '#fff';
            for (const b of gameState.bullets) {
                ctx.beginPath();
                ctx.arc(b.x, b.y, 2.5, 0, Math.PI * 2);
                ctx.fill();
            }

            // --- Draw ship (if alive, with blinking during invincibility) ---
            const ship = gameState.ship;
            if (ship.alive) {
                // Blink every 6 frames when invincible
                const blinkOff = ship.invincible > 0 && Math.floor(ship.invincible / 6) % 2 === 0;
                if (!blinkOff) {
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 2;
                    const tipX = ship.x + Math.cos(ship.angle) * SHIP_SIZE;
                    const tipY = ship.y + Math.sin(ship.angle) * SHIP_SIZE;
                    const rearAngle1 = ship.angle + 2.5; // ~143° for sleek triangle
                    const rearAngle2 = ship.angle - 2.5;
                    const rearDist = SHIP_SIZE * 0.6;
                    const leftX = ship.x + Math.cos(rearAngle1) * rearDist;
                    const leftY = ship.y + Math.sin(rearAngle1) * rearDist;
                    const rightX = ship.x + Math.cos(rearAngle2) * rearDist;
                    const rightY = ship.y + Math.sin(rearAngle2) * rearDist;

                    ctx.beginPath();
                    ctx.moveTo(tipX, tipY);
                    ctx.lineTo(leftX, leftY);
                    ctx.lineTo(rightX, rightY);
                    ctx.closePath();
                    ctx.stroke();

                    // Draw thrust flame
                    if (ship.thrusting) {
                        const rearCenterX = ship.x - Math.cos(ship.angle) * SHIP_SIZE * 0.4;
                        const rearCenterY = ship.y - Math.sin(ship.angle) * SHIP_SIZE * 0.4;
                        const flameLen1 = randRange(6, 16);
                        const flameLen2 = randRange(4, 10);
                        const flameSpread = 0.35; // slight spread angle

                        ctx.strokeStyle = '#fff';
                        ctx.lineWidth = 1.5;
                        // Main flame
                        ctx.beginPath();
                        ctx.moveTo(rearCenterX, rearCenterY);
                        const end1X = rearCenterX - Math.cos(ship.angle) * flameLen1;
                        const end1Y = rearCenterY - Math.sin(ship.angle) * flameLen1;
                        ctx.lineTo(end1X, end1Y);
                        ctx.stroke();
                        // Side flickers
                        const flickerX = rearCenterX - Math.cos(ship.angle + flameSpread) * flameLen2;
                        const flickerY = rearCenterY - Math.sin(ship.angle + flameSpread) * flameLen2;
                        ctx.beginPath();
                        ctx.moveTo(rearCenterX, rearCenterY);
                        ctx.lineTo(flickerX, flickerY);
                        ctx.stroke();
                        const flickerX2 = rearCenterX - Math.cos(ship.angle - flameSpread) * flameLen2;
                        const flickerY2 = rearCenterY - Math.sin(ship.angle - flameSpread) * flameLen2;
                        ctx.beginPath();
                        ctx.moveTo(rearCenterX, rearCenterY);
                        ctx.lineTo(flickerX2, flickerY2);
                        ctx.stroke();
                    }
                }
            }

            // --- HUD: Score (top-left) ---
            ctx.fillStyle = '#fff';
            ctx.font = '18px "Courier New", monospace';
            ctx.textAlign = 'left';
            ctx.fillText(`SCORE: ${gameState.score}`, 20, 30);

            // --- HUD: Level (top-center) ---
            ctx.textAlign = 'center';
            ctx.fillText(`LEVEL ${gameState.level}`, W / 2, 30);

            // --- HUD: Lives (top-right, drawn as small ship icons) ---
            ctx.textAlign = 'right';
            const livesX = W - 20;
            const livesY = 22;
            // Draw small ship triangles for remaining lives
            for (let i = 0; i < gameState.lives; i++) {
                const lx = livesX - i * 24;
                const smallSize = 9;
                const tipX = lx + Math.cos(-Math.PI / 2) * smallSize;
                const tipY = livesY + Math.sin(-Math.PI / 2) * smallSize;
                const ra1 = -Math.PI / 2 + 2.5;
                const ra2 = -Math.PI / 2 - 2.5;
                const rd = smallSize * 0.6;
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 1.2;
                ctx.beginPath();
                ctx.moveTo(tipX, tipY);
                ctx.lineTo(lx + Math.cos(ra1) * rd, livesY + Math.sin(ra1) * rd);
                ctx.lineTo(lx + Math.cos(ra2) * rd, livesY + Math.sin(ra2) * rd);
                ctx.closePath();
                ctx.stroke();
