            // --- Game Over overlay ---
            if (gameState.gameOver) {
                ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
                ctx.fillRect(0, 0, W, H);
                ctx.fillStyle = '#fff';
                ctx.font = '42px "Courier New", monospace';
                ctx.textAlign = 'center';
                ctx.fillText('GAME OVER', W / 2, H / 2 - 25);
                ctx.font = '20px "Courier New", monospace';
                ctx.fillText(`Final Score: ${gameState.score}`, W / 2, H / 2 + 20);
                ctx.fillText('Press ENTER or R to restart', W / 2, H / 2 + 55);
            }
        }

        // ──────────────────────────────────────────────
        //  9. GAME RESET
        // ──────────────────────────────────────────────
        function resetGame() {
            gameState.ship.x = W / 2;
            gameState.ship.y = H / 2;
            gameState.ship.vx = 0;
            gameState.ship.vy = 0;
            gameState.ship.angle = -Math.PI / 2;
            gameState.ship.alive = true;
            gameState.ship.thrusting = false;
            gameState.ship.invincible = 0;
            gameState.asteroids = [];
            gameState.bullets = [];
            gameState.particles = [];
            gameState.score = 0;
            gameState.lives = INITIAL_LIVES;
            gameState.level = 1;
            gameState.gameOver = false;
            gameState.respawnTimer = 0;
            gameState.shootCooldown = 0;

            // Spawn initial asteroid field
            spawnLevelAsteroids(INITIAL_ASTEROID_COUNT);
        }

        // ──────────────────────────────────────────────
        //  10. GAME LOOP (requestAnimationFrame)
        // ──────────────────────────────────────────────
        let lastTime = 0;

        function gameLoop(timestamp) {
            // Calculate delta time normalized to 60fps
            if (!lastTime) lastTime = timestamp;
            let dt = (timestamp - lastTime) / 16.667;
            if (dt > 5) dt = 5; // cap to avoid spiral of death
            if (dt <= 0) dt = 0.016; // minimum
            lastTime = timestamp;

            update(dt);
            render();
            requestAnimationFrame(gameLoop);
        }

        // ──────────────────────────────────────────────
        //  11. INITIALIZATION
        // ──────────────────────────────────────────────
        function init() {
            resetGame();
            // Give the ship a brief moment of invincibility at the very start
            gameState.ship.invincible = 90;
            requestAnimationFrame(gameLoop);
        }

        // Start the game!
        init();

        console.log('🚀 Asteroids Clone ready!');
        console.log('   Controls: Arrow Keys or WASD to move, Space to shoot');
        console.log('   Destroy all asteroids to advance to the next level.');
    </script>
</body>
</html>
```
### Game Features

Here’s how the game works, what you can control, and the key systems that make it tick.

- **Core Mechanics & Controls:** You pilot a spaceship using the **Arrow Keys** (or **WASD**) to rotate and thrust. Press the **Spacebar** to fire bullets. The ship and bullets wrap around the screen edges, creating a continuous play area. Your goal is to destroy all asteroids to advance to the next level.

- **Asteroid Splitting & Scoring:** Large asteroids split into two medium ones when hit, and medium ones split into two small ones. Small asteroids are destroyed completely. Your score increases based on the asteroid's size: **20 points for large, 50 for medium, 100 for small**.

- **Lives, Respawn & Invincibility:** You start with **3 lives**, displayed as small ship icons in the top-right corner. When your ship is destroyed, it respawns in the center after a short delay with a flashing **brief invincibility period** that protects you from collisions.

- **Progressive Difficulty:** As you clear each level, the next one begins with **more asteroids** and **increased asteroid speed**. A brief invincibility is granted at the start of each new level to help you survive the initial wave.

- **Visual Feedback:** The game provides clear feedback through **particle explosions** when asteroids or your ship are destroyed, a flickering engine flame when thrusting, and a blinking effect during invincibility.

The three-way quicksort (Dijkstra’s Dutch National Flag algorithm) partitions the array into three regions—elements less than, equal to, and greater than the pivot—which makes it extremely efficient when many duplicate keys are present. In contrast, a standard (naïve) two-way quicksort can degrade to O(n²) performance and deep recursion (often leading to a stack overflow) on such data.

Below is a complete JavaScript implementation of both algorithms, together with a benchmark harness that compares their performance on arrays of size 10, 1 000, and 100 000 under three different data distributions: many duplicates, few duplicates, and all‑equal elements.

```javascript
// =====================
// Sorting Algorithms
// =====================

/**
 * Three-way quick sort (Dijkstra's Dutch National Flag)
 * Sorts the array in place. A random pivot is chosen to avoid
 * worst-case behaviour on already sorted arrays.
 */
function threeWayQuickSort(arr, lo = 0, hi = arr.length - 1) {
  if (lo >= hi) return;

  // Choose random pivot and move it to arr[lo]
  const randIdx = lo + Math.floor(Math.random() * (hi - lo + 1));
  [arr[lo], arr[randIdx]] = [arr[randIdx], arr[lo]];
  const pivot = arr[lo];

  let lt = lo;      // arr[lo .. lt-1] < pivot
  let gt = hi;      // arr[gt+1 .. hi] > pivot
  let i = lo;       // arr[lt .. i-1] == pivot

  while (i <= gt) {
    if (arr[i] < pivot) {
      [arr[lt], arr[i]] = [arr[i], arr[lt]];
      lt++;
      i++;
    } else if (arr[i] > pivot) {
      [arr[gt], arr[i]] = [arr[i], arr[gt]];
      gt--;
    } else {
      i++;
    }
  }

  threeWayQuickSort(arr, lo, lt - 1);
  threeWayQuickSort(arr, gt + 1, hi);
}

/**
 * Naïve quick sort (standard two-way partition, Lomuto scheme).
 * Also uses a random pivot to serve as a fair baseline for the
 * partitioning strategy alone.
 */
function naiveQuickSort(arr, lo = 0, hi = arr.length - 1) {
  if (lo >= hi) return;

  // Lomuto partition with random pivot moved to the end
  const randIdx = lo + Math.floor(Math.random() * (hi - lo + 1));
  [arr[randIdx], arr[hi]] = [arr[hi], arr[randIdx]];
  const pivot = arr[hi];

  let i = lo;
  for (let j = lo; j < hi; j++) {
    if (arr[j] <= pivot) {
      [arr[i], arr[j]] = [arr[j], arr[i]];
      i++;
    }
  }
  [arr[i], arr[hi]] = [arr[hi], arr[i]];

  const pivotIndex = i;
  naiveQuickSort(arr, lo, pivotIndex - 1);
  naiveQuickSort(arr, pivotIndex + 1, hi);
}

// =====================
// Helpers
// =====================

function isSorted(arr) {
  for (let i = 1; i < arr.length; i++) {
    if (arr[i] < arr[i - 1]) return false;
  }
  return true;
}

// Cross‑platform high‑resolution timestamp
const now = typeof performance !== 'undefined' && performance.now
  ? performance.now.bind(performance)
  : Date.now;

// =====================
// Data Generators
// =====================

function manyDuplicatesGen(size) {
  const rangeSize = Math.max(2, Math.floor(size / 10));
  return () => {
    const arr = new Array(size);
    for (let i = 0; i < size; i++) {
      arr[i] = Math.floor(Math.random() * rangeSize);
    }
    return arr;
  };
}

function fewDuplicatesGen(size) {
  const rangeSize = size * 2;
  return () => {
    const arr = new Array(size);
    for (let i = 0; i < size; i++) {
      arr[i] = Math.floor(Math.random() * rangeSize);
    }
    return arr;
  };
}

function allEqualGen(size) {
  return () => new Array(size).fill(42);
}

// =====================
// Benchmark Harness
// =====================

function benchmark(sortFn, arrGenerator, trials) {
  let totalTime = 0;
  let failures = 0;

  for (let t = 0; t < trials; t++) {
    const arr = arrGenerator();
    try {
      const start = now();
      sortFn(arr);
      const end = now();
      totalTime += (end - start);
      // Optional correctness check (uncomment for debugging):
      // if (!isSorted(arr)) throw new Error('Sort failed');
    } catch (e) {
      failures++;
    }
  }

  const successful = trials - failures;
  const avgTime = successful > 0 ? totalTime / successful : NaN;
  return { avgTime, failures };
}

// =====================
// Main Benchmark Runner
// =====================

function runBenchmarks() {
  console.log('Running correctness tests…');
  // Test on small arrays to keep things fast and avoid stack issues
  for (const size of [10, 100]) {
    const generators = [
      manyDuplicatesGen(size),
      fewDuplicatesGen(size),
      allEqualGen(size),
    ];
    for (const gen of generators) {
      const arr1 = gen();
      const arr2 = [...arr1];
      threeWayQuickSort(arr1);
      naiveQuickSort(arr2);
      if (!isSorted(arr1) || !isSorted(arr2)) {
        console.error(`Correctness failed at size ${size}`);
        return;
      }
    }
  }
  console.log('All correctness tests passed.\n');

  const sizes = [10, 1000, 100000];
  const dataGens = [
    { name: 'Many duplicates (range = size/10)', gen: manyDuplicatesGen },
    { name: 'Few duplicates (range = size*2)', gen: fewDuplicatesGen },
    { name: 'All equal', gen: allEqualGen },
  ];

  const algorithms = [
    { name: 'Three-way QuickSort', fn: threeWayQuickSort },
    { name: 'Naive QuickSort', fn: naiveQuickSort },
  ];

  // Number of trials per size – adjusted to get reliable averages
  const trialsBySize = { 10: 10000, 1000: 500, 100000: 20 };

  for (const size of sizes) {
    console.log(`\n========== Array size: ${size} ==========`);
    const trials = trialsBySize[size];

    for (const gen of dataGens) {
      console.log(`\n--- ${gen.name} ---`);
      const arrGen = gen.gen(size);

      const results = [];
      for (const alg of algorithms) {
        const sortFn = (arr) => alg.fn(arr);
        const { avgTime, failures } = benchmark(sortFn, arrGen, trials);
        results.push({
          Algorithm: alg.name,
          'Avg Time (ms)': avgTime.toFixed(4),
          'Failures (stack overflow)': failures,
        });
      }
      console.table(results);
    }
  }

  console.log('\nBenchmark complete.');
}

// Kick off everything
runBenchmarks();
```

---

### What to expect when you run the benchmark

- **Many duplicates / All equal**  
  The three‑way quicksort shines here. Because it groups all equal elements together and skips them in recursive calls, it runs in **O(n)** on all‑equal data and **O(n log n)** when there are many duplicates. The naïve implementation, however, creates extremely unbalanced partitions (all elements ≤ pivot go to the left), resulting in **O(n²)** time and **O(n)** recursion depth. For `n = 100 000` this almost always triggers a *Maximum call stack size exceeded* error (reported as failures in the table).

- **Few duplicates**  
  Both algorithms perform similarly. The naïve sort sometimes has a slight edge because its inner loop is simpler, but the difference is negligible. Neither suffers from the duplicate‑induced worst case.

- **Array size 10**  
  Both are so fast that the times are essentially 0 ms. The benchmark uses many trials (10 000) to confirm they both work correctly.

The table printed by `console.table()` will clearly show that three‑way quicksort is the safer and more efficient choice for real‑world data that frequently contains duplicates.

