// appointment.integration.test.ts
import { Pool } from 'pg';
import Redis from 'ioredis';
import { AppointmentService } from './appointment.service';
import { GenericContainer, StartedTestContainer } from 'testcontainers';

describe('AppointmentService Integration', () => {
  let pgContainer: StartedTestContainer;
  let redisContainer: StartedTestContainer;
  let pgPool: Pool;
  let redis: Redis;
  let service: AppointmentService;

  beforeAll(async () => {
    // Start PostgreSQL
    pgContainer = await new GenericContainer('postgres:14-alpine')
      .withEnvironment({ POSTGRES_PASSWORD: 'test', POSTGRES_DB: 'test' })
      .withExposedPorts(5432)
      .start();

    // Start Redis
    redisContainer = await new GenericContainer('redis:7-alpine')
      .withExposedPorts(6379)
      .start();

    const pgHost = pgContainer.getHost();
    const pgPort = pgContainer.getMappedPort(5432);
    pgPool = new Pool({
      host: pgHost,
      port: pgPort,
      user: 'postgres',
      password: 'test',
      database: 'test',
    });

    // Create schema
    await pgPool.query(`
      CREATE TABLE appointments (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        slot_id UUID NOT NULL,
        patient_id UUID NOT NULL,
        created_at TIMESTAMPTZ DEFAULT NOW()
      );
      ALTER TABLE appointments ADD CONSTRAINT appointments_slot_id_key UNIQUE (slot_id);
    `);

    const redisHost = redisContainer.getHost();
    const redisPort = redisContainer.getMappedPort(6379);
    redis = new Redis({ host: redisHost, port: redisPort });

    service = new AppointmentService(pgPool, redis);
  }, 60000);

  afterAll(async () => {
    await pgPool.end();
    await redis.quit();
    await pgContainer.stop();
    await redisContainer.stop();
  });

  it('should prevent double-booking under concurrent requests', async () => {
    const slotId = 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11';
    const patientA = '11111111-1111-1111-1111-111111111111';
    const patientB = '22222222-2222-2222-2222-222222222222';

    // Simulate 10 concurrent booking attempts for the same slot
    const attempts = [
      ...Array(5).fill(0).map(() => service.bookAppointment(slotId, patientA).catch(() => null)),
      ...Array(5).fill(0).map(() => service.bookAppointment(slotId, patientB).catch(() => null)),
    ];

    const results = await Promise.all(attempts);
    const successful = results.filter(r => r !== null);

    // Only one booking should succeed
    expect(successful.length).toBe(1);
    expect(successful[0]!.slotId).toBe(slotId);

    // Verify exactly one row in the database
    const { rows } = await pgPool.query('SELECT COUNT(*) FROM appointments WHERE slot_id = $1', [slotId]);
    expect(parseInt(rows[0].count, 10)).toBe(1);
  });

  it('should handle retry from the same patient after timeout', async () => {
    const slotId = 'b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11';
    const patientId = 'patient-retry';

    // First booking succeeds but we simulate no response (timeout)
    const firstResult = await service.bookAppointment(slotId, patientId);
    expect(firstResult).toBeDefined();

    // Retry (same patient, same slot)
    const retryResult = await service.bookAppointment(slotId, patientId);
    expect(retryResult.id).toBe(firstResult.id);
    expect(retryResult.patientId).toBe(patientId);

    // Database still has one row
    const { rows } = await pgPool.query('SELECT COUNT(*) FROM appointments WHERE slot_id = $1', [slotId]);
    expect(parseInt(rows[0].count, 10)).toBe(1);
  });
});
