Below is a practical demonstration of the **Builder design pattern** in C, applied to a game engine component—a configurable `GameCharacter`. The example first shows the verbose and error‑prone manual construction (**before**) and then a clean, fluent builder (**after**) that separates object construction from its representation.

---

## 1. Without the Builder Pattern (Before)

Manually creating a `GameCharacter` requires direct memory allocation, field‑by‑field assignment, and careful handling of dynamic sub‑objects (weapons, skills, etc.). This scatters construction logic, makes it hard to enforce defaults, and leads to repetitive code.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// ---------- Product: GameCharacter ----------
typedef struct {
    char name[64];
    int health;
    int mana;
    float strength;
    float agility;
    float intelligence;
    char *weapon;
    char *armor;
    char **skills;
    int num_skills;
} GameCharacter;

// ---------- Helper to print ----------
void print_character(const GameCharacter *c) {
    printf("Character: %s\n", c->name);
    printf("  Health: %d, Mana: %d\n", c->health, c->mana);
    printf("  Str: %.1f, Agi: %.1f, Int: %.1f\n",
           c->strength, c->agility, c->intelligence);
    printf("  Weapon: %s\n", c->weapon ? c->weapon : "None");
    printf("  Armor: %s\n", c->armor ? c->armor : "None");
    printf("  Skills: ");
    for (int i = 0; i < c->num_skills; ++i)
        printf("%s ", c->skills[i]);
    printf("\n\n");
}

// ---------- Before: manual construction ----------
void demo_without_builder() {
    // 1. Allocate raw memory
    GameCharacter *character = (GameCharacter*)malloc(sizeof(GameCharacter));
    if (!character) return;

    // 2. Set every field explicitly
    strcpy(character->name, "Aragorn");
    character->health = 100;
    character->mana = 50;
    character->strength = 80.0f;
    character->agility = 70.0f;
    character->intelligence = 60.0f;

    // 3. Handle optional strings – must strdup()
    character->weapon = strdup("Sword");
    character->armor  = strdup("Chainmail");

    // 4. Manually manage dynamic arrays (skills)
    character->num_skills = 3;
    character->skills = (char**)malloc(3 * sizeof(char*));
    character->skills[0] = strdup("Slash");
    character->skills[1] = strdup("Block");
    character->skills[2] = strdup("Charge");

    // Use the character
    print_character(character);

    // 5. Cleanup – every allocated block must be freed manually
    free(character->weapon);
    free(character->armor);
    for (int i = 0; i < character->num_skills; ++i)
        free(character->skills[i]);
    free(character->skills);
    free(character);
}
```

**Problems:**
- Construction is tangled with memory management.
- No mechanism to enforce mandatory fields or defaults.
- Adding a new attribute requires changing every creation site.
- Hard to create variations (e.g., a “Mage” preset) without code duplication.

---

## 2. With the Builder Pattern (After)

The **Builder** encapsulates construction. A `CharacterBuilder` struct holds temporary data and exposes **fluent setter functions** (returning the builder pointer) plus a `build()` method that validates, allocates, and returns a fully formed `GameCharacter`.

```c
// ---------- Builder ----------
typedef struct CharacterBuilder {
    // Data being built up
    char name[64];
    int health;
    int mana;
    float strength;
    float agility;
    float intelligence;
    char *weapon;
    char *armor;
    char **skills;
    int num_skills;
    int skills_cap;

    // Method pointers for a fluent interface
    struct CharacterBuilder* (*set_name)        (struct CharacterBuilder*, const char*);
    struct CharacterBuilder* (*set_health)      (struct CharacterBuilder*, int);
    struct CharacterBuilder* (*set_mana)        (struct CharacterBuilder*, int);
    struct CharacterBuilder* (*set_strength)    (struct CharacterBuilder*, float);
    struct CharacterBuilder* (*set_agility)     (struct CharacterBuilder*, float);
    struct CharacterBuilder* (*set_intelligence)(struct CharacterBuilder*, float);
    struct CharacterBuilder* (*set_weapon)      (struct CharacterBuilder*, const char*);
    struct CharacterBuilder* (*set_armor)       (struct CharacterBuilder*, const char*);
    struct CharacterBuilder* (*add_skill)       (struct CharacterBuilder*, const char*);
    GameCharacter*           (*build)           (struct CharacterBuilder*);
} CharacterBuilder;

// ---------- Builder method implementations ----------
static CharacterBuilder* set_name_impl(CharacterBuilder *self, const char *n) {
    strncpy(self->name, n, sizeof(self->name) - 1);
    self->name[sizeof(self->name) - 1] = '\0';
    return self;
}
static CharacterBuilder* set_health_impl(CharacterBuilder *self, int h) {
    self->health = h;
    return self;
}
static CharacterBuilder* set_mana_impl(CharacterBuilder *self, int m) {
    self->mana = m;
    return self;
}
static CharacterBuilder* set_strength_impl(CharacterBuilder *self, float s) {
    self->strength = s;
    return self;
}
static CharacterBuilder* set_agility_impl(CharacterBuilder *self, float a) {
    self->agility = a;
    return self;
}
static CharacterBuilder* set_intelligence_impl(CharacterBuilder *self, float i) {
    self->intelligence = i;
    return self;
}
static CharacterBuilder* set_weapon_impl(CharacterBuilder *self, const char *w) {
    free(self->weapon);                // replace previous if any
    self->weapon = strdup(w);
    return self;
}
static CharacterBuilder* set_armor_impl(CharacterBuilder *self, const char *a) {
    free(self->armor);
    self->armor = strdup(a);
    return self;
}
static CharacterBuilder* add_skill_impl(CharacterBuilder *self, const char *skill) {
    // Grow dynamic array if needed
    if (self->num_skills >= self->skills_cap) {
        self->skills_cap = self->skills_cap ? self->skills_cap * 2 : 4;
        self->skills = realloc(self->skills, self->skills_cap * sizeof(char*));
    }
    self->skills[self->num_skills++] = strdup(skill);
    return self;
}
static GameCharacter* build_impl(CharacterBuilder *self) {
    GameCharacter *c = (GameCharacter*)malloc(sizeof(GameCharacter));
    if (!c) return NULL;

    // Build final object from builder's data
    strcpy(c->name, self->name);
    c->health       = self->health;
    c->mana         = self->mana;
    c->strength     = self->strength;
    c->agility      = self->agility;
    c->intelligence = self->intelligence;
    c->weapon       = self->weapon ? strdup(self->weapon) : NULL;
    c->armor        = self->armor  ? strdup(self->armor)  : NULL;

    c->num_skills = self->num_skills;
    if (c->num_skills > 0) {
        c->skills = malloc(c->num_skills * sizeof(char*));
        for (int i = 0; i < c->num_skills; ++i)
            c->skills[i] = strdup(self->skills[i]);
    } else {
        c->skills = NULL;
    }
    return c;
}

// ---------- Builder constructor / destructor ----------
CharacterBuilder* character_builder_create() {
    CharacterBuilder *b = (CharacterBuilder*)malloc(sizeof(CharacterBuilder));
    if (!b) return NULL;

    // Default values
    b->name[0]      = '\0';
    b->health       = 100;
    b->mana         = 0;
    b->strength     = 10.0f;
    b->agility      = 10.0f;
    b->intelligence = 10.0f;
    b->weapon       = NULL;
    b->armor        = NULL;
    b->skills       = NULL;
    b->num_skills   = 0;
    b->skills_cap   = 0;

    // Wire up methods
    b->set_name         = set_name_impl;
    b->set_health       = set_health_impl;
    b->set_mana         = set_mana_impl;
    b->set_strength     = set_strength_impl;
    b->set_agility      = set_agility_impl;
    b->set_intelligence = set_intelligence_impl;
    b->set_weapon       = set_weapon_impl;
    b->set_armor        = set_armor_impl;
    b->add_skill        = add_skill_impl;
    b->build            = build_impl;

    return b;
}

void character_builder_destroy(CharacterBuilder *b) {
    if (!b) return;
    free(b->weapon);
    free(b->armor);
    for (int i = 0; i < b->num_skills; ++i)
        free(b->skills[i]);
    free(b->skills);
