            flex-direction: column;
            gap: 5px;
            min-width: 160px;
            flex: 1 1 auto;
        }
        .control-group label {
            font-size: 0.8rem;
            font-weight: 600;
            color: var(--text-secondary);
            text-transform: uppercase;
            letter-spacing: 0.4px;
        }
        .control-group input[type="text"],
        .control-group input[type="date"],
        .control-group select {
            padding: 9px 12px;
            border: 2px solid var(--border);
            border-radius: 8px;
            font-size: 0.9rem;
            transition: var(--transition);
            background: #fafbfc;
            width: 100%;
        }
        .control-group input:focus,
        .control-group select:focus {
            outline: none;
            border-color: var(--primary);
            box-shadow: 0 0 0 3px rgba(74, 108, 247, 0.1);
            background: #fff;
        }
        .search-group {
            flex: 2 1 250px;
            position: relative;
        }
        .search-group input {
            padding-right: 36px;
        }
        .search-clear {
            position: absolute;
            right: 10px;
            top: 50%;
            transform: translateY(-50%);
            background: none;
            border: none;
            cursor: pointer;
            font-size: 1.2rem;
            color: #999;
            padding: 4px;
            line-height: 1;
            display: none;
        }
        .search-clear.visible {
            display: block;
        }
        .search-clear:hover {
            color: #555;
        }
        .slider-wrapper {
            display: flex;
            align-items: center;
            gap: 10px;
        }
        .slider-wrapper input[type="range"] {
            flex: 1;
            accent-color: var(--primary);
        }
        .slider-value {
            font-weight: 700;
            color: var(--primary);
            min-width: 35px;
            text-align: center;
            font-size: 0.95rem;
        }
        .date-range-group {
            display: flex;
            gap: 8px;
            flex-wrap: wrap;
        }
        .date-range-group .control-group {
            flex: 1 1 130px;
            min-width: 120px;
        }

        /* Table Area */
        .table-card {
            background: var(--card-bg);
            border-radius: var(--radius);
            box-shadow: var(--shadow);
            overflow: hidden;
        }
        .table-wrapper {
            overflow-x: auto;
            -webkit-overflow-scrolling: touch;
        }
        table {
            width: 100%;
            border-collapse: collapse;
            font-size: 0.9rem;
            min-width: 650px;
        }
        thead th {
            background: #f8fafc;
            padding: 14px 16px;
            text-align: left;
            font-weight: 700;
            color: var(--text-secondary);
            border-bottom: 2px solid var(--border);
            cursor: pointer;
            user-select: none;
            white-space: nowrap;
            transition: var(--transition);
            position: relative;
        }
        thead th:hover {
            background: #eef2ff;
            color: var(--primary);
        }
        thead th .sort-arrow {
            margin-left: 4px;
            font-size: 0.75rem;
            opacity: 0.4;
            transition: var(--transition);
        }
        thead th.sorted .sort-arrow {
            opacity: 1;
            color: var(--primary);
        }
        thead th.sorted-asc .sort-arrow::after {
            content: ' ▲';
        }
        thead th.sorted-desc .sort-arrow::after {
            content: ' ▼';
        }
        thead th .sort-arrow::after {
            content: ' ⇅';
        }
        tbody td {
            padding: 12px 16px;
            border-bottom: 1px solid #f1f1f1;
            vertical-align: middle;
        }
        tbody tr {
            transition: var(--transition);
        }
        tbody tr:hover {
            background: var(--hover);
        }
        tbody tr:nth-child(even) {
            background: #fafbfd;
        }
        tbody tr:nth-child(even):hover {
            background: var(--hover);
        }
        .student-link,
        .subject-link {
            color: var(--primary);
            cursor: pointer;
            font-weight: 600;
            text-decoration: underline;
            text-decoration-color: transparent;
            transition: var(--transition);
            text-underline-offset: 3px;
        }
        .student-link:hover,
        .subject-link:hover {
            text-decoration-color: var(--primary);
            color: var(--primary-dark);
        }
        .grade-badge {
            display: inline-block;
            padding: 4px 10px;
            border-radius: 20px;
            font-weight: 700;
            font-size: 0.85rem;
            text-align: center;
            min-width: 42px;
        }
        .grade-high {
            background: #d1fae5;
            color: #065f46;
        }
        .grade-mid {
            background: #dbeafe;
            color: #1e40af;
        }
        .grade-low {
            background: #fef3c7;
            color: #92400e;
        }
        .grade-poor {
            background: #fee2e2;
            color: #991b1b;
        }
        .no-results {
            text-align: center;
            padding: 40px;
            color: #999;
            font-size: 1.1rem;
        }

        /* Pagination */
        .pagination-area {
            display: flex;
            flex-wrap: wrap;
            align-items: center;
            justify-content: space-between;
            gap: 16px;
            padding: 14px 20px;
            background: #fff;
            border-top: 1px solid var(--border);
            border-radius: 0 0 var(--radius) var(--radius);
        }
        .rows-selector {
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: 0.85rem;
            color: var(--text-secondary);
        }
        .rows-selector select {
            padding: 6px 10px;
            border: 2px solid var(--border);
            border-radius: 6px;
            font-size: 0.85rem;
            background: #fafbfc;
        }
        .pagination-buttons {
            display: flex;
            gap: 4px;
            flex-wrap: wrap;
        }
        .page-btn {
            padding: 7px 13px;
            border: 2px solid var(--border);
            background: #fff;
            border-radius: 6px;
            cursor: pointer;
            font-weight: 600;
            font-size: 0.85rem;
            transition: var(--transition);
            color: var(--text);
        }
        .page-btn:hover:not(:disabled) {
            background: var(--hover);
            border-color: var(--primary);
            color: var(--primary);
        }
        .page-btn.active {
            background: var(--primary);
            color: #fff;
            border-color: var(--primary);
        }
        .page-btn:disabled {
            opacity: 0.4;
            cursor: not-allowed;
        }
        .page-ellipsis {
            padding: 7px 6px;
            color: #999;
            font-weight: 600;
        }
        .results-info {
            font-size: 0.85rem;
            color: var(--text-secondary);
            font-weight: 500;
        }

        /* Modal */
        .modal-overlay {
            display: none;
            position: fixed;
            inset: 0;
            background: rgba(0, 0, 0, 0.55);
            z-index: 1000;
            justify-content: center;
            align-items: center;
            padding: 20px;
            backdrop-filter: blur(2px);
            -webkit-backdrop-filter: blur(2px);
        }
        .modal-overlay.active {
            display: flex;
        }
        .modal {
            background: #fff;
            border-radius: 14px;
            width: 100%;
            max-width: 750px;
            max-height: 90vh;
            overflow-y: auto;
            box-shadow: 0 20px 50px rgba(0, 0, 0, 0.25);
            animation: modalIn 0.25s ease;
        }
        @keyframes modalIn {
            from {
                opacity: 0;
                transform: translateY(30px) scale(0.96);
            }
            to {
                opacity: 1;
                transform: translateY(0) scale(1);
            }
        }
        .modal-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 18px 24px;
            border-bottom: 2px solid #f0f0f0;
            position: sticky;
            top: 0;
            background: #fff;
            border-radius: 14px 14px 0 0;
            z-index: 5;
        }
        .modal-header h2 {
            font-size: 1.25rem;
            color: var(--text);
        }
        .modal-close {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            border: none;
            background: #f3f4f6;
            cursor: pointer;
            font-size: 1.3rem;
            transition: var(--transition);
            display: flex;
            align-items: center;
            justify-content: center;
            color: #555;
        }
        .modal-close:hover {
            background: #e5e7eb;
            color: #000;
        }
        .modal-body {
            padding: 20px 24px 24px;
        }
        .stats-cards {
            display: flex;
            gap: 14px;
            flex-wrap: wrap;
            margin-bottom: 20px;
        }
        .stat-card {
            flex: 1 1 130px;
            background: #f8fafc;
            border-radius: 10px;
            padding: 16px;
            text-align: center;
            border: 2px solid #e8ecf1;
            min-width: 110px;
        }
        .stat-card .stat-value {
            font-size: 2rem;
            font-weight: 700;
            color: var(--primary);
        }
        .stat-card .stat-label {
            font-size: 0.8rem;
            color: var(--text-secondary);
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            margin-top: 2px;
        }
        .stat-card.best .stat-value {
            color: #10b981;
        }
        .stat-card.worst .stat-value {
            color: #ef4444;
        }
        .chart-container {
            position: relative;
            height: 320px;
            margin-bottom: 20px;
        }
        .chart-container canvas {
            width: 100% !important;
            height: 100% !important;
        }
        .modal-table-wrapper {
            overflow-x: auto;
            max-height: 250px;
            overflow-y: auto;
            border: 1px solid var(--border);
            border-radius: 8px;
        }
        .modal-table-wrapper table {
            min-width: 400px;
            font-size: 0.8rem;
        }
        .modal-table-wrapper thead th {
            position: sticky;
            top: 0;
            z-index: 2;
            background: #f8fafc;
            font-size: 0.8rem;
            padding: 10px 12px;
        }
        .modal-table-wrapper tbody td {
            padding: 8px 12px;
            font-size: 0.8rem;
        }

        /* Responsive */
        @media (max-width: 900px) {
            .controls-area {
                flex-direction: column;
                gap: 12px;
            }
            .control-group {
                flex: 1 1 auto;
                width: 100%;
                min-width: auto;
            }
            .date-range-group {
                flex-direction: column;
                gap: 8px;
                width: 100%;
            }
            .date-range-group .control-group {
                width: 100%;
            }
            .header {
                flex-direction: column;
                align-items: flex-start;
            }
            .pagination-area {
                flex-direction: column;
                align-items: stretch;
                text-align: center;
            }
            .pagination-buttons {
                justify-content: center;
            }
            .stats-cards {
                flex-direction: column;
            }
            .stat-card {
                flex: 1 1 auto;
            }
            .chart-container {
                height: 250px;
            }
            .modal {
                max-width: 95vw;
                max-height: 95vh;
            }
        }
        @media (max-width: 500px) {
            .header h1 {
                font-size: 1.2rem;
            }
            table {
                font-size: 0.78rem;
            }
            thead th,
            tbody td {
                padding: 8px 10px;
            }
            .btn {
                padding: 8px 14px;
                font-size: 0.8rem;
            }
            .chart-container {
                height: 200px;
            }
            .modal {
                border-radius: 10px;
            }
            .modal-body {
                padding: 14px;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <!-- Header -->
        <div class="header">
            <h1><span class="icon">📊</span> Student Grades Dashboard</h1>
            <div class="header-actions">
                <button class="btn btn-export" id="btnExport" title="Export filtered data as CSV">📥 Export CSV</button>
                <button class="btn btn-clear btn-sm" id="btnClearFilters">🔄 Clear All Filters</button>
            </div>
        </div>

        <!-- Controls -->
        <div class="controls-area" id="controlsArea">
            <div class="control-group search-group">
                <label for="searchInput">🔍 Search Student or Subject</label>
                <input type="text" id="searchInput" placeholder="Type a name or subject...">
                <button class="search-clear" id="searchClear" title="Clear search">×</button>
            </div>
            <div class="control-group">
                <label for="gradeSlider">📈 Minimum Grade: <strong id="gradeSliderLabel">0</strong></label>
                <div class="slider-wrapper">
                    <span>0</span>
                    <input type="range" id="gradeSlider" min="0" max="100" value="0" step="1">
                    <span>100</span>
                </div>
            </div>
            <div class="date-range-group">
                <div class="control-group">
                    <label for="dateStart">📅 From Date</label>
                    <input type="date" id="dateStart">
                </div>
                <div class="control-group">
                    <label for="dateEnd">📅 To Date</label>
                    <input type="date" id="dateEnd">
                </div>
            </div>
        </div>

        <!-- Table -->
        <div class="table-card">
            <div class="table-wrapper">
                <table id="gradesTable">
                    <thead>
                        <tr>
                            <th data-column="studentName" class="sorted sorted-asc">
                                Student Name <span class="sort-arrow"></span>
                            </th>
                            <th data-column="subjectName">
                                Subject <span class="sort-arrow"></span>
                            </th>
                            <th data-column="grade">
                                Grade <span class="sort-arrow"></span>
                            </th>
                            <th data-column="date">
                                Date <span class="sort-arrow"></span>
                            </th>
                        </tr>
                    </thead>
                    <tbody id="tableBody"></tbody>
                </table>
                <div class="no-results" id="noResults" style="display:none;">
                    😕 No records match your current filters. Try adjusting your search or filter criteria.
                </div>
            </div>
            <!-- Pagination -->
            <div class="pagination-area" id="paginationArea">
                <div class="rows-selector">
                    <span>Rows per page:</span>
                    <select id="rowsPerPage">
                        <option value="5">5</option>
                        <option value="8" selected>8</option>
                        <option value="10">10</option>
                        <option value="15">15</option>
                    </select>
                </div>
                <div class="results-info" id="resultsInfo"></div>
                <div class="pagination-buttons" id="paginationButtons"></div>
            </div>
        </div>
    </div>

    <!-- Modal -->
    <div class="modal-overlay" id="modalOverlay">
        <div class="modal" id="modal">
            <div class="modal-header">
                <h2 id="modalTitle">Detail View</h2>
                <button class="modal-close" id="modalClose" title="Close">✕</button>
            </div>
            <div class="modal-body" id="modalBody">
                <div class="stats-cards" id="statsCards"></div>
                <div class="chart-container">
                    <canvas id="detailChart"></canvas>
                </div>
                <h4 style="margin-bottom:8px;color:var(--text-secondary);">📋 Individual Grade Records</h4>
                <div class="modal-table-wrapper">
                    <table>
                        <thead><tr><th>Student</th><th>Subject</th><th>Grade</th><th>Date</th><th>Comment</th></tr></thead>
                        <tbody id="modalTableBody"></tbody>
                    </table>
                </div>
            </div>
        </div>
    </div>

    <script>
        (function() {
            // ─────────────────────────────────────
            // DATA GENERATION
            // ─────────────────────────────────────
            const students = [
                { id: 'S001', name: 'Alice Johnson', parentContact: 'alice.parent@email.com' },
                { id: 'S002', name: 'Bob Smith', parentContact: 'bob.parent@email.com' },
                { id: 'S003', name: 'Charlie Brown', parentContact: 'charlie.parent@email.com' },
                { id: 'S004', name: 'Diana Lee', parentContact: 'diana.parent@email.com' },
                { id: 'S005', name: 'Ethan Davis', parentContact: 'ethan.parent@email.com' },
                { id: 'S006', name: 'Fiona Chen', parentContact: 'fiona.parent@email.com' },
            ];

            const subjects = ['Mathematics', 'English', 'Science', 'History', 'Art'];

            const teacherComments = [
                'Excellent performance, keep it up!',
                'Good progress, but needs more practice.',
                'Outstanding work throughout the semester.',
                'Satisfactory performance.',
                'Needs significant improvement.',
                'Shows great potential.',
                'Consistent effort and good results.',
                'Struggles with some concepts but improving.',
                'A pleasure to teach, very engaged.',
                'Has made noticeable improvements recently.',
            ];

            function generateData() {
                const data = [];
                for (const student of students) {
                    for (const subject of subjects) {
                        const numGrades = Math.floor(Math.random() * 3) + 1;
                        for (let g = 0; g < numGrades; g++) {
                            const month = Math.floor(Math.random() * 5) + 1;
                            const day = Math.floor(Math.random() * 27) + 1;
                            const dateStr = `2024-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
                            const grade = Math.floor(Math.random() * 46) + 55;
                            data.push({
                                studentId: student.id,
                                studentName: student.name,
                                subjectName: subject,
                                grade: grade,
                                date: dateStr,
                                parentContact: student.parentContact,
                                teacherComments: teacherComments[Math.floor(Math.random() *
                                    teacherComments.length)],
                            });
                        }
                    }
                }
                data.sort((a, b) => a.date.localeCompare(b.date) || a.studentName.localeCompare(b.studentName));
                return data;
            }

            const allData = generateData();

            // ─────────────────────────────────────
            // STATE
            // ─────────────────────────────────────
            const state = {
                searchTerm: '',
                gradeThreshold: 0,
                dateStart: '',
                dateEnd: '',
                sortColumn: 'studentName',
                sortDirection: 'asc',
                currentPage: 1,
                rowsPerPage: 8,
            };

            // ─────────────────────────────────────
            // DOM REFERENCES
            // ─────────────────────────────────────
            const tableBody = document.getElementById('tableBody');
            const noResults = document.getElementById('noResults');
            const searchInput = document.getElementById('searchInput');
            const searchClear = document.getElementById('searchClear');
            const gradeSlider = document.getElementById('gradeSlider');
            const gradeSliderLabel = document.getElementById('gradeSliderLabel');
            const dateStart = document.getElementById('dateStart');
            const dateEnd = document.getElementById('dateEnd');
            const rowsPerPageSelect = document.getElementById('rowsPerPage');
            const paginationButtons = document.getElementById('paginationButtons');
            const resultsInfo = document.getElementById('resultsInfo');
            const btnExport = document.getElementById('btnExport');
            const btnClearFilters = document.getElementById('btnClearFilters');
            const modalOverlay = document.getElementById('modalOverlay');
            const modalClose = document.getElementById('modalClose');
            const modalTitle = document.getElementById('modalTitle');
            const statsCards = document.getElementById('statsCards');
            const modalTableBody = document.getElementById('modalTableBody');
            const detailChartCanvas = document.getElementById('detailChart');
            const tableHeaders = document.querySelectorAll('#gradesTable thead th');

            let modalChart = null;

            // ─────────────────────────────────────
            // UTILITY FUNCTIONS
            // ─────────────────────────────────────
            function formatDate(dateStr) {
                const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
                const [y, m, d] = dateStr.split('-');
                return `${months[parseInt(m)-1]} ${parseInt(d)}, ${y}`;
            }

            function getGradeClass(grade) {
                if (grade >= 90) return 'grade-high';
                if (grade >= 80) return 'grade-mid';
                if (grade >= 70) return 'grade-low';
                return 'grade-poor';
            }

            function escapeCSV(str) {
                if (!str) return '';
                str = String(str);
                if (str.includes(',') || str.includes('"') || str.includes('\n') || str.includes('\r')) {
                    return '"' + str.replace(/"/g, '""') + '"';
                }
                return str;
            }

            // ─────────────────────────────────────
            // DATA PROCESSING PIPELINE
            // ─────────────────────────────────────
            function getProcessedData() {
                let data = [...allData];

                // Search
                if (state.searchTerm.trim()) {
                    const term = state.searchTerm.toLowerCase().trim();
                    data = data.filter(row =>
                        row.studentName.toLowerCase().includes(term) ||
                        row.subjectName.toLowerCase().includes(term)
                    );
                }

                // Grade threshold
                if (state.gradeThreshold > 0) {
                    data = data.filter(row => row.grade >= state.gradeThreshold);
                }

                // Date range
                if (state.dateStart) {
                    data = data.filter(row => row.date >= state.dateStart);
                }
                if (state.dateEnd) {
                    data = data.filter(row => row.date <= state.dateEnd);
                }

                // Sort
                if (state.sortColumn) {
                    const col = state.sortColumn;
                    const dir = state.sortDirection === 'asc' ? 1 : -1;
                    data.sort((a, b) => {
                        let valA = a[col];
                        let valB = b[col];
                        if (typeof valA === 'string') valA = valA.toLowerCase();
                        if (typeof valB === 'string') valB = valB.toLowerCase();
                        if (valA < valB) return -1 * dir;
                        if (valA > valB) return 1 * dir;
                        return 0;
                    });
                }

                return data;
            }

            function getPaginatedData(data) {
                const start = (state.currentPage - 1) * state.rowsPerPage;
                return data.slice(start, start + state.rowsPerPage);
            }

            // ─────────────────────────────────────
            // RENDER TABLE
            // ─────────────────────────────────────
            function renderTable() {
                const processedData = getProcessedData();
                const totalResults = processedData.length;
                const totalPages = Math.max(1, Math.ceil(totalResults / state.rowsPerPage));

                // Clamp current page
                if (state.currentPage > totalPages) {
                    state.currentPage = totalPages;
                }
                const paginatedData = getPaginatedData(processedData);

                // Render table body
                if (paginatedData.length === 0) {
                    tableBody.innerHTML = '';
                    noResults.style.display = 'block';
                } else {
                    noResults.style.display = 'none';
                    tableBody.innerHTML = paginatedData.map(row => `
                        <tr>
                            <td><span class="student-link" data-student="${escapeHTML(row.studentName)}">${escapeHTML(row.studentName)}</span></td>
                            <td><span class="subject-link" data-subject="${escapeHTML(row.subjectName)}">${escapeHTML(row.subjectName)}</span></td>
                            <td><span class="grade-badge ${getGradeClass(row.grade)}">${row.grade}%</span></td>
                            <td>${formatDate(row.date)}</td>
                        </tr>
                    `).join('');
                }

                // Update results info
                const start = paginatedData.length > 0 ? (state.currentPage - 1) * state.rowsPerPage + 1 : 0;
                const end = Math.min(state.currentPage * state.rowsPerPage, totalResults);
                resultsInfo.textContent = totalResults > 0 ?
                    `Showing ${start}–${end} of ${totalResults} results` :
                    'No results found';

                // Render pagination
                renderPagination(totalPages);

                // Update search clear button
                if (state.searchTerm.trim()) {
                    searchClear.classList.add('visible');
                } else {
                    searchClear.classList.remove('visible');
                }
            }

            function escapeHTML(str) {
                const div = document.createElement('div');
                div.textContent = str;
                return div.innerHTML;
            }

            function renderPagination(totalPages) {
                const pages = getPageNumbers(state.currentPage, totalPages);
                let html = '';
                html +=
                    `<button class="page-btn" data-page="1" ${state.currentPage===1?'disabled':''} title="First">«</button>`;
                html +=
                    `<button class="page-btn" data-page="${Math.max(1, state.currentPage-1)}" ${state.currentPage===1?'disabled':''} title="Previous">‹</button>`;

                for (const p of pages) {
                    if (p === '...') {
                        html += `<span class="page-ellipsis">…</span>`;
                    } else {
                        html +=
                            `<button class="page-btn${p===state.currentPage?' active':''}" data-page="${p}">${p}</button>`;
                    }
                }

                html +=
                    `<button class="page-btn" data-page="${Math.min(totalPages, state.currentPage+1)}" ${state.currentPage===totalPages?'disabled':''} title="Next">›</button>`;
                html +=
                    `<button class="page-btn" data-page="${totalPages}" ${state.currentPage===totalPages?'disabled':''} title="Last">»</button>`;

                paginationButtons.innerHTML = html;

                // Add click listeners to page buttons
                paginationButtons.querySelectorAll('.page-btn').forEach(btn => {
                    btn.addEventListener('click', function() {
                        const page = parseInt(this.dataset.page);
                        if (!isNaN(page) && page >= 1 && page <= totalPages) {
                            state.currentPage = page;
                            renderTable();
                            scrollToTable();
                        }
                    });
                });
