```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title Decentralized Crowdfunding
 * @notice A gas-optimized smart contract for creating campaigns, pledging Ether,
 *         withdrawing funds when goals are met, and refunding if they are not.
 * @dev Optimized for low gas usage via struct packing, custom errors, calldata usage,
 *      and minimal storage operations. Reentrancy protection via Checks-Effects-Interactions.
 */
contract Crowdfunding {
    // ────────────────────── Custom Errors (gas-efficient) ──────────────────────
    error DeadlineMustBeInFuture();
    error GoalMustBeGreaterThanZero();
    error CampaignDoesNotExist();
    error CampaignEnded();
    error CampaignStillActive();
    error GoalNotMet();
    error GoalMet();
    error NoPledgeToRefund();
    error AlreadyWithdrawn();
    error NotCampaignCreator();
    error PledgeAmountMustBeGreaterThanZero();
    error DirectPaymentsNotAllowed();
    error TransferFailed();

    // ────────────────────── Structs & State Variables ──────────────────────────

    /**
     * @notice Represents a crowdfunding campaign.
     * @dev Packed storage layout to minimize slot usage:
     *      - `creator` (address, 20 bytes) + `withdrawn` (bool, 1 byte) share slot 0.
     *      - `goal` (uint256) in slot 1.
     *      - `deadline` (uint256) in slot 2.
     *      - `totalPledged` (uint256) in slot 3.
     *      - `details` (string) offset in slot 4, actual data elsewhere.
     */
    struct Campaign {
        address creator;      // Address that created the campaign
        bool withdrawn;       // Whether the funds have been withdrawn by creator
        uint256 goal;         // Funding goal in wei
        uint256 deadline;     // Unix timestamp after which pledges stop and state finalizes
        uint256 totalPledged; // Total wei pledged so far
        string details;       // IPFS hash or project description (use short strings to save gas)
    }

    /// @notice Auto-incrementing campaign ID counter (public for transparency)
    uint256 public campaignCounter;

    /// @notice campaignId => Campaign struct
    mapping(uint256 => Campaign) public campaigns;

    /// @notice campaignId => (contributor => pledged amount in wei)
    mapping(uint256 => mapping(address => uint256)) public pledges;

    // ────────────────────── Events ────────────────────────────────────────────
    event CampaignCreated(
        uint256 indexed campaignId,
        address indexed creator,
        uint256 goal,
        uint256 deadline,
        string details
    );

    event Pledged(
        uint256 indexed campaignId,
        address indexed contributor,
        uint256 amount
    );

    event Withdrawn(
        uint256 indexed campaignId,
        address indexed creator,
        uint256 amount
    );

    event Refunded(
        uint256 indexed campaignId,
        address indexed contributor,
        uint256 amount
    );

    // ────────────────────── External / Public Functions ────────────────────────

    /**
     * @notice Creates a new crowdfunding campaign.
     * @param goal Funding goal in wei (must be > 0).
     * @param deadline Unix timestamp of campaign end (must be in the future).
     * @param details Project description (ideally an IPFS hash to save gas).
     * @return campaignId The unique identifier of the new campaign.
     */
    function createCampaign(
        uint256 goal,
        uint256 deadline,
        string calldata details
    ) external returns (uint256 campaignId) {
        if (deadline <= block.timestamp) revert DeadlineMustBeInFuture();
        if (goal == 0) revert GoalMustBeGreaterThanZero();

        campaignId = campaignCounter;
        // `unchecked` saves a few gas because overflow is practically impossible here
        unchecked {
            campaignCounter++;
        }

        // Store struct with packed fields (address + bool share one slot)
        campaigns[campaignId] = Campaign({
            creator: msg.sender,
            withdrawn: false,
            goal: goal,
            deadline: deadline,
            totalPledged: 0,
            details: details
        });

        emit CampaignCreated(campaignId, msg.sender, goal, deadline, details);
    }

    /**
     * @notice Pledge Ether to a campaign. Can only be called before the campaign's deadline.
     * @param campaignId The unique ID of the campaign to support.
     */
    function pledge(uint256 campaignId) external payable {
        if (msg.value == 0) revert PledgeAmountMustBeGreaterThanZero();

        Campaign storage campaign = campaigns[campaignId];
        // Check campaign existence: a non-existent campaign has default `creator == address(0)`
        if (campaign.creator == address(0)) revert CampaignDoesNotExist();
        if (block.timestamp >= campaign.deadline) revert CampaignEnded();

        // Update state (Checks-Effects-Interactions pattern)
        campaign.totalPledged += msg.value;
        pledges[campaignId][msg.sender] += msg.value;

        emit Pledged(campaignId, msg.sender, msg.value);
    }

    /**
     * @notice Allows the campaign creator to withdraw all pledged funds if the goal
     *         was met by the deadline. Can only be called once.
     * @param campaignId The unique ID of the campaign.
     */
    function withdraw(uint256 campaignId) external {
        Campaign storage campaign = campaigns[campaignId];
        if (campaign.creator != msg.sender) revert NotCampaignCreator();
        // Deadline must have passed
        if (block.timestamp < campaign.deadline) revert CampaignStillActive();
        if (campaign.totalPledged < campaign.goal) revert GoalNotMet();
        if (campaign.withdrawn) revert AlreadyWithdrawn();

        // Effects
        uint256 amount = campaign.totalPledged;
        campaign.withdrawn = true;

        // Interaction: transfer Ether using low-level call (forward-compatible & safe)
        (bool success, ) = msg.sender.call{value: amount}("");
        if (!success) revert TransferFailed();

        emit Withdrawn(campaignId, msg.sender, amount);
    }

    /**
     * @notice Allows a contributor to claim a refund of their pledge if the campaign
     *         deadline has passed and the goal was NOT met.
     * @param campaignId The unique ID of the campaign.
     */
    function refund(uint256 campaignId) external {
        Campaign storage campaign = campaigns[campaignId];
        if (campaign.creator == address(0)) revert CampaignDoesNotExist();
        // Deadline must have passed
        if (block.timestamp < campaign.deadline) revert CampaignStillActive();
        if (campaign.totalPledged >= campaign.goal) revert GoalMet();

        uint256 amount = pledges[campaignId][msg.sender];
        if (amount == 0) revert NoPledgeToRefund();

        // Effects: zero out the pledge before sending Ether to prevent reentrancy
        pledges[campaignId][msg.sender] = 0;

        // Interaction
        (bool success, ) = msg.sender.call{value: amount}("");
        if (!success) revert TransferFailed();

        emit Refunded(campaignId, msg.sender, amount);
    }

    // ────────────────────── Ether Handling ────────────────────────────────────

    /**
     * @notice Rejects any Ether sent directly to the contract address,
     *         preventing accidental loss of funds.
     */
    receive() external payable {
        revert DirectPaymentsNotAllowed();
    }

    /**
     * @notice Fallback function to reject any accidental calls.
     */
    fallback() external payable {
        revert DirectPaymentsNotAllowed();
    }
}
