 struct Processor<'a> {
 chars: &'a [char],
 index: usize,
 cache: Vec<Option<char>>,
 stack: Vec<State>,
 transformations: Vec<Transformation>,
 }

 enum State {
 Initialize,
 Process,
 ApplyTransform(char),
 Validate(char),
 Finalize,
 }

 enum Transformation {
 ToUpper,
 ToLower,
 ToggleCase,
 }

 impl<'a> Processor<'a> {
 fn new(chars: &'a [char]) -> Self {
 Processor {
 chars,
 index: 0,
 cache: vec![None; chars.len()],
 stack: vec![State::Initialize],
 transformations: vec![Transformation::ToUpper, Transformation::ToLower, Transformation::ToggleCase],
 }
 }

 fn process(&mut self) -> String {
 let mut result = String::with_capacity(self.chars.len());
 while let Some(state) = self.stack.pop() {
 match state {
 State::Initialize => {
 self.stack.push(State::Process);
 }
 State::Process => {
 if self.index >= self.chars.len() {
 self.stack.push(State::Finalize);
 continue;
 }
 if let Some(c) = self.cache[self.index] {
 result.push(c);
 self.index += 1;
 self.stack.push(State::Process);
 } else {
 let current = self.chars[self.index];
 self.stack.push(State::ApplyTransform(current));
 }
 }
 State::ApplyTransform(c) => {
 let transformation = &self.transformations[self.index % self.transformations.len()];
 let new_char = match transformation {
 Transformation::ToUpper => Self::to_upper_ascii(c),
 Transformation::ToLower => Self::to_lower_ascii(c),
 Transformation::ToggleCase => Self::toggle_case(c),
 };
 self.cache[self.index] = Some(new_char);
 self.stack.push(State::Validate(new_char));
 }
