 if Self::is_vowel(c) {
 let transformed = Self::duplicate_char(c);
 result.push(transformed);
 self.cache[self.index] = Some(transformed);
 } else {
 result.push(c);
 }
 self.index += 1;
 self.stack.push(State::Process);
 }
 State::Finalize => {}
 }
 }
 result
 }

 fn to_upper_ascii(c: char) -> char {
 if c.is_ascii_lowercase() {
 (c as u8 - 32) as char
 } else {
 c
 }
 }

 fn to_lower_ascii(c: char) -> char {
 if c.is_ascii_uppercase() {
 (c as u8 + 32) as char
 } else {
 c
 }
 }

 fn toggle_case(c: char) -> char {
 if c.is_ascii_uppercase() {
 Self::to_lower_ascii(c)
 } else if c.is_ascii_lowercase() {
 Self::to_upper_ascii(c)
 } else {
 c
 }
 }

 fn is_vowel(c: char) -> bool {
 matches!(c, 'A' | 'E' | 'I' | 'O' | 'U' | 'a' | 'e' | 'i' | 'o' | 'u')
 }

 fn duplicate_char(c: char) -> char {
 c
 }
 }

