function countOccurrences(arr) {
  // Map to store the count and the index of the first occurrence for each number
  const freqMap = new Map();

  // Build the frequency map
  arr.forEach((num, index) => {
    if (freqMap.has(num)) {
      // Duplicate element: only increment the count (ignore for creating new entries)
      freqMap.get(num).count++;
    } else {
      // First occurrence: create entry and record its index
      freqMap.set(num, { count: 1, firstIndex: index });
    }
  });

  // Convert the map into an array of objects
  const elements = Array.from(freqMap, ([num, { count, firstIndex }]) => ({
    element: num,
    count,
    firstIndex
  }));

  // Sort by occurrence count descending; if tied, sort by first occurrence index ascending
  elements.sort((a, b) => b.count - a.count || a.firstIndex - b.firstIndex);

  // Limit to at most 10 objects and return only the required properties
  return elements.slice(0, 10).map(({ element, count }) => ({ element, count }));
}

// Example usage:
// const input = [1, 2, 3, 1, 2, 1, 4, 5, 6, 6, 6];
// console.log(countOccurrences(input));
```

### How the requirements are met:
- **Counts occurrences** – The map stores how many times each integer appears.
- **Ignores duplicate elements** – Duplicate values do not create new map entries; they simply increment the count.
- **Only considers the first occurrence** – The index of the first appearance is saved and used as a tie‑breaker when sorting.
- **Sorts descending by occurrence** – Primary sort is `b.count - a.count`.
- **Returns array of objects** – Each object contains `element` and `count`.
- **Output ≤ 10 objects** – The sorted array is sliced to the first 10 items.
- **Assumes integers 0–100** – Works for any numbers, so the stated input range is fully supported.

