    def __init__(self, config, url):
        BaseSiteAdapter.__init__(self, config, url)
        self.story.setMetadata('siteabbrev', 'webnovel')
        self.csrf_token = None

        # Extract story/book ID from the URL
        m = re.match(r'https?://www\.webnovel\.com/book/(?P<id>\d+)', url)
        if m:
            self.story.setMetadata('storyId', m.group('id'))

    @staticmethod
    def getSiteDomain():
        return 'www.webnovel.com'

    @classmethod
    def getSiteAbbrev(cls):
        return 'webnovel'

    @staticmethod
    def getSiteURLPattern():
        return r'https?://www\.webnovel\.com/book/(?P<id>\d+)(?:/(?P<slug>[^/]*))?.*'

    # --------------------------------------------------------------------------
    # Main entry points
    # --------------------------------------------------------------------------
    def doExtractChapterUrlsAndMetadata(self):
        """Extract story metadata and build the list of chapter URLs."""
        # 1. Fetch the main story page
        response = self.get_request(self.url)
        soup = self.make_soup(response.content)

        # 2. Obtain CSRF token and metadata from the HTML
        self._extract_csrf(soup, response.content)
        self._extract_metadata(soup)

        # 3. Ensure we have a story ID (fallback to page content)
        if not self.story.getMetadata('storyId'):
            m = re.search(r'bookId\s*=\s*(\d+)', response.text)
            if m:
                self.story.setMetadata('storyId', m.group(1))
            else:
                raise exceptions.FailedToDownload(
                    "Could not find story/book ID on the page."
                )

        # 4. Fetch all chapters via the JSON API
        chapters = self._fetch_chapter_list()

        # 5. Add each chapter to the story with a constructed identifier URL
        for ch in chapters:
            title = (
                ch.get('chapterName') or
                'Chapter %d' % ch.get('chapterIndex', 0)
            ).strip()

            url_fragment = (
                'https://www.webnovel.com/go/pcm/chapter/get-content'
                '?bookId=%s&chapterId=%s' % (
                    self.story.getMetadata('storyId'),
                    ch['chapterId']
                )
            )
            if ch.get('isVip'):
                url_fragment += '&isVip=1'

            self.add_chapter(title, url_fragment)

        self.story.setMetadata('numChapters', len(chapters))

    def getChapterText(self, url):
        """Retrieve the actual chapter content HTML."""
        # Parse the identifying parameters from the constructed URL
        params = self._parse_query(url)
        book_id = params.get('bookId')
        chapter_id = params.get('chapterId')
        is_vip = params.get('isVip') == '1'

        # Make sure we have a fresh CSRF token
        if not self.csrf_token:
            self._fetch_csrf_token()

        # Build request for the standard content API
        request_params = {
            'bookId': book_id,
            'chapterId': chapter_id,
            '_csrfToken': self.csrf_token,
        }
        headers = {
            'X-Requested-With': 'XMLHttpRequest',
            'Referer': self.url,
            'X-CSRF-TOKEN': self.csrf_token,
        }

        if is_vip:
            vip_token = self.getConfig('vip_token', None)
            if vip_token:
                request_params['vipToken'] = vip_token
            else:
                logger.info(
                    "VIP chapter requested without vip_token; "
                    "falling back to session cookies."
                )

        full_url = 'https://www.webnovel.com/go/pcm/chapter/get-content?' + \
                   '&'.join('%s=%s' % (k, v) for k, v in request_params.items())

        # Attempt standard download
        resp = self.get_request(full_url, headers=headers)
        if resp.status_code != 200:
            raise exceptions.FailedToDownload(
                "HTTP error %d while fetching chapter." % resp.status_code
            )

        data = resp.json()
        if data.get('code') != 0:
            msg = data.get('message', 'Unknown error')

            # If it's a VIP chapter, try the VIP‑specific endpoint
            if is_vip or 'VIP' in msg:
                vip_token = self.getConfig('vip_token', None)
                if vip_token:
                    vip_url = full_url.replace(
                        'get-content', 'get-vip-content'
                    ) + '&vipToken=' + vip_token
                    resp = self.get_request(vip_url, headers=headers)
                    if resp.status_code == 200:
                        data = resp.json()
                        if data.get('code') == 0:
                            return self._extract_content(data)
                raise exceptions.FailedToDownload(
                    "VIP chapter could not be retrieved: %s" % msg
                )

            # CSRF token might have expired – refresh once and retry
            if data.get('code') == 401 or 'CSRF' in msg:
                logger.warning("CSRF token expired, refreshing.")
                self.csrf_token = None
                self._fetch_csrf_token()
                request_params['_csrfToken'] = self.csrf_token
                headers['X-CSRF-TOKEN'] = self.csrf_token
                full_url = 'https://www.webnovel.com/go/pcm/chapter/get-content?' + \
                           '&'.join('%s=%s' % (k, v) for k, v in request_params.items())
                resp = self.get_request(full_url, headers=headers)
                data = resp.json()
                if data.get('code') != 0:
                    raise exceptions.FailedToDownload(
                        "API error after CSRF refresh: %s" % data.get('message', '')
                    )
            else:
                raise exceptions.FailedToDownload("API error: %s" % msg)

        return self._extract_content(data)

    # --------------------------------------------------------------------------
    # Helper methods
    # --------------------------------------------------------------------------
    @staticmethod
    def _parse_query(url):
        """Extract query-string parameters from a URL."""
        query = url.split('?')[1] if '?' in url else ''
        params = {}
        for pair in query.split('&'):
            if '=' in pair:
                k, v = pair.split('=', 1)
                params[k] = v
        return params

    @staticmethod
    def _extract_content(data):
        """Safely pull the HTML content from an API JSON response."""
        try:
            content = data['data']['content']
        except KeyError:
            raise exceptions.FailedToDownload(
                "Unexpected API response structure: %s" % data
            )
        if not content:
            raise exceptions.FailedToDownload("Empty chapter content returned.")
        return content

    # --------------------------------------------------------------------------
    # CSRF token handling
    # --------------------------------------------------------------------------
    def _extract_csrf(self, soup, content=None):
        """Try to find the CSRF token in meta tags or embedded JavaScript."""
        # 1. <meta name="_csrf_token" content="...">
        meta = (
            soup.find('meta', attrs={'name': '_csrf_token'}) or
            soup.find('meta', attrs={'name': 'csrf-token'})
        )
        if meta and meta.get('content'):
            self.csrf_token = meta['content']
            return

        # 2. window._csrf_token = "..."; in page source
        if content:
            if isinstance(content, bytes):
                content = content.decode('utf-8', errors='replace')
            m = re.search(
                r'window\._csrf_token\s*=\s*["\']([^"\']+)["\']',
                content
            )
            if m:
                self.csrf_token = m.group(1)
                return

        # 3. data-csrf attribute on <html>
        html = soup.find('html')
        if html and html.get('data-csrf'):
            self.csrf_token = html['data-csrf']
            return

        raise exceptions.FailedToDownload(
            "Could not find CSRF token on the page."
        )

    def _fetch_csrf_token(self):
        """Re-fetch the story page to obtain a current CSRF token."""
        resp = self.get_request(self.url)
        soup = self.make_soup(resp.content)
        self._extract_csrf(soup, resp.content)
        if not self.csrf_token:
            raise exceptions.FailedToDownload(
                "Unable to retrieve a valid CSRF token."
            )

    # --------------------------------------------------------------------------
    # Metadata extraction
    # --------------------------------------------------------------------------
    def _extract_metadata(self, soup):
        """Parse story metadata from the page HTML."""
        # --- Title ---
        og_title = soup.find('meta', property='og:title')
        if og_title:
            self.story.setMetadata('title', og_title['content'].strip())
        else:
            h1 = soup.find('h1')
            if h1:
                self.story.setMetadata('title', h1.text.strip())

        # --- Author ---
        author_elem = (
            soup.find('a', class_='author-name') or
            soup.find('span', class_='author')
        )
        if author_elem:
            self.story.setMetadata('author', author_elem.text.strip())
            author_url = author_elem.get('href')
            if author_url:
                author_id = re.search(r'/author/(\d+)', author_url)
                if author_id:
                    self.story.setMetadata('authorId', author_id.group(1))
        else:
            author_meta = soup.find('meta', attrs={'name': 'author'})
            if author_meta:
                self.story.setMetadata('author', author_meta['content'].strip())
            else:
                logger.warning("Author information not found.")

        # --- Translator / Editor (common detail items) ---
        detail_items = soup.find_all(
            class_=re.compile(r'detail-item|info-item')
        )
        for item in detail_items:
            text = item.get_text()
            if 'Translator' in text:
                value = item.find(class_='value') or item.find_next_sibling('span')
                if value:
                    self.story.setMetadata('translator', value.text.strip())
            elif 'Editor' in text:
                value = item.find(class_='value') or item.find_next_sibling('span')
                if value:
                    self.story.setMetadata('editor', value.text.strip())

        # --- Category (from breadcrumb) ---
        breadcrumb = soup.find(class_=re.compile(r'breadcrumb'))
        if breadcrumb:
            links = breadcrumb.find_all('a')
            if len(links) > 1:
                self.story.setMetadata('category', links[1].text.strip())

        # --- Dates ---
        update_elem = soup.find(
            class_='update-time'
        ) or soup.find('time', class_='last-update')
        if update_elem:
            text = update_elem.text.strip()
            # Strip "Updated" prefix if present
            m = re.search(r'(?:Updated\s+)?(.+)', text, re.IGNORECASE)
            if m:
                dt = self.parse_relative_date(m.group(1))
                self.story.setMetadata('dateUpdated', makeDate(dt))

        # --- Description ---
        desc_elem = soup.find(class_='description') or soup.find(class_='summary')
        if desc_elem:
            self.story.setMetadata('description', self.utf8FromSoup(desc_elem))

        # --- Cover image ---
        cover = soup.find('img', class_='cover') or \
                soup.find('meta', property='og:image')
        if cover:
            src = cover.get('src') or cover.get('content')
            if src:
                self.story.setMetadata('cover_image', src)

    # --------------------------------------------------------------------------
    # Chapter list fetching (paginated JSON API)
    # --------------------------------------------------------------------------
    def _fetch_chapter_list(self):
        """Retrieve the complete chapter list from the webnovel API."""
        book_id = self.story.getMetadata('storyId')
        all_chapters = []
        page_index = 1
        page_size = 500  # safe maximum for a single API response

        while True:
            params = {
                'bookId': book_id,
                '_csrfToken': self.csrf_token,
                'pageIndex': page_index,
                'pageSize': page_size,
            }
            headers = {
                'X-Requested-With': 'XMLHttpRequest',
                'Referer': self.url,
                'X-CSRF-TOKEN': self.csrf_token,
            }
            url = 'https://www.webnovel.com/go/pcm/chapter/get-chapter-list?' + \
                  '&'.join('%s=%s' % (k, v) for k, v in params.items())

            resp = self.get_request(url, headers=headers)
            data = resp.json()

            if data.get('code') != 0:
                raise exceptions.FailedToDownload(
                    "Failed to fetch chapter list: %s" % data.get('message')
                )

            chapter_data = data['data']
            if isinstance(chapter_data, dict):
                chapters = chapter_data.get('chapterList', [])
                total_pages = chapter_data.get('pageCount', 1)
            else:
                chapters = chapter_data
                total_pages = 1

            all_chapters.extend(chapters)
            if page_index >= total_pages:
                break
            page_index += 1

        # Ensure stable ordering by chapter index
        all_chapters.sort(key=lambda x: x.get('chapterIndex', 0))
        return all_chapters

    # --------------------------------------------------------------------------
    # Relative date parsing
    # --------------------------------------------------------------------------
    def parse_relative_date(self, datestr):
        """Convert a relative date string (e.g. '3 days ago') to a UTC datetime."""
        datestr = datestr.strip().lower()
        now = datetime.datetime.utcnow()

        if 'just now' in datestr or 'a few seconds ago' in datestr:
            return now - datetime.timedelta(seconds=30)

        # Minutes
        m = re.search(r'(\d+)\s*min(?:ute)?s?\s*ago', datestr)
        if m:
            return now - datetime.timedelta(minutes=int(m.group(1)))

        # Hours
        m = re.search(r'(\d+)\s*hours?\s*ago', datestr)
        if m:
            return now - datetime.timedelta(hours=int(m.group(1)))
        if 'an hour' in datestr:
            return now - datetime.timedelta(hours=1)

        # Days
        m = re.search(r'(\d+)\s*days?\s*ago', datestr)
        if m:
            return now - datetime.timedelta(days=int(m.group(1)))
        if 'yesterday' in datestr:
            return now - datetime.timedelta(days=1)

        # Weeks
        m = re.search(r'(\d+)\s*weeks?\s*ago', datestr)
        if m:
            return now - datetime.timedelta(weeks=int(m.group(1)))
        if 'last week' in datestr:
            return now - datetime.timedelta(days=7)

        # Months (approximate)
        m = re.search(r'(\d+)\s*months?\s*ago', datestr)
        if m:
            return now - datetime.timedelta(days=int(m.group(1)) * 30)

        # Years
        m = re.search(r'(\d+)\s*years?\s*ago', datestr)
        if m:
            return now - datetime.timedelta(days=int(m.group(1)) * 365)

        logger.warning("Unrecognised relative date: %s – using current time.", datestr)
        return now
