/**
 * Finds all unique elements in an array that match a given key.
 * 
 * The function first removes all duplicate values from the input array (O(n) time, O(n) space),
 * then filters the remaining unique elements to those strictly equal to the provided key.
 * If no matches are found or the array is empty, an empty object is returned.
 * 
 * @param {Array} arr - The input array to search.
 * @param {*} key - The value to match against each element (using strict equality).
 * @returns {Object} An object whose keys are the unique matching elements and values are the elements themselves.
 *                   Returns an empty object if the input array is empty or the key is not found.
 * 
 * Time Complexity: O(n) where n is arr.length
 * Space Complexity: O(n)
 */
function getUniqueMatchingElements(arr, key) {
  // Return empty object for empty or invalid array
  if (!Array.isArray(arr) || arr.length === 0) {
    return {};
  }

  // Step 1: Remove duplicate values from the array while preserving order
  const seen = new Set();
  const uniqueArr = [];
  for (const item of arr) {
    if (!seen.has(item)) {
      seen.add(item);
      uniqueArr.push(item);
    }
  }

  // Step 2: Filter the deduplicated array to elements matching the key
  const matches = uniqueArr.filter(item => item === key);

  // Step 3: If no element matches the key, return empty object
  if (matches.length === 0) {
    return {};
  }

  // Step 4: Build the result object containing all matched unique elements.
  // Using the matched elements as keys ensures the object "contains" them.
  // The value for each key is set to the element itself (or `true` for a set-like object).
  const result = {};
  for (const match of matches) {
    result[match] = match;   // You can use `true` here if only presence matters
  }

  return result;
}

