**Authentication Controller** (`controllers/authController.js`)
```js
const crypto = require('crypto');
const User = require('../models/User');
const RefreshToken = require('../models/RefreshToken');
const TempToken = require('../models/TempToken');
const { generateAccessToken, generateRefreshToken } = require('../helpers/token');
const { validationResult } = require('express-validator');

// Helper to set refresh token cookie
const setRefreshTokenCookie = (res, token) => {
  res.cookie('refreshToken', token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 7 * 24 * 60 * 60 * 1000 // 7 days
  });
};

// @route   POST /api/auth/register
exports.register = async (req, res, next) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const { email, password } = req.body;
    const existingUser = await User.findOne({ email });
    if (existingUser) return res.status(409).json({ error: 'Email already registered' });

    const user = new User({ email, password });
    await user.save();

    // Automatically log in after registration (or send verification email)
    const accessToken = generateAccessToken(user._id);
    const refreshTokenString = generateRefreshToken();
    const refreshTokenHash = RefreshToken.hashToken(refreshTokenString);

    await RefreshToken.create({
      tokenHash: refreshTokenHash,
      userId: user._id,
      expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)
    });

    setRefreshTokenCookie(res, refreshTokenString);
    res.status(201).json({ accessToken });
  } catch (err) {
    next(err);
  }
};

// @route   POST /api/auth/login
exports.login = async (req, res, next) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const { email, password } = req.body;
    const user = await User.findOne({ email });
    if (!user) return res.status(401).json({ error: 'Invalid credentials' });

    const isMatch = await user.comparePassword(password);
    if (!isMatch) return res.status(401).json({ error: 'Invalid credentials' });

    // If 2FA is enabled, issue a temporary token instead
    if (user.is2FAEnabled) {
      const tempToken = crypto.randomBytes(32).toString('hex');
      await TempToken.create({ userId: user._id, token: tempToken });
      return res.json({ requires2FA: true, tempToken });
    }

    const accessToken = generateAccessToken(user._id);
    const refreshTokenString = generateRefreshToken();
    const refreshTokenHash = RefreshToken.hashToken(refreshTokenString);

    await RefreshToken.create({
      tokenHash: refreshTokenHash,
      userId: user._id,
      expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)
    });

    setRefreshTokenCookie(res, refreshTokenString);
    res.json({ accessToken });
  } catch (err) {
    next(err);
  }
};

// @route   POST /api/auth/refresh-token
exports.refreshToken = async (req, res, next) => {
  try {
    const rawToken = req.cookies.refreshToken;
    if (!rawToken) return res.status(401).json({ error: 'Refresh token missing' });

    const hash = RefreshToken.hashToken(rawToken);
    const storedToken = await RefreshToken.findOne({ tokenHash: hash, revoked: false });

    if (!storedToken || storedToken.expiresAt < new Date()) {
      res.clearCookie('refreshToken');
      if (storedToken) {
        storedToken.revoked = true;
        await storedToken.save();
      }
      return res.status(401).json({ error: 'Invalid or expired refresh token' });
    }

    // Rotate: revoke current token, issue new pair
    storedToken.revoked = true;
    await storedToken.save();

    const user = await User.findById(storedToken.userId);
    if (!user) return res.status(401).json({ error: 'User not found' });

    const newAccessToken = generateAccessToken(user._id);
    const newRefreshTokenString = generateRefreshToken();
    const newHash = RefreshToken.hashToken(newRefreshTokenString);

    await RefreshToken.create({
      tokenHash: newHash,
      userId: user._id,
      expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)
    });

    setRefreshTokenCookie(res, newRefreshTokenString);
    res.json({ accessToken: newAccessToken });
  } catch (err) {
    next(err);
  }
};

// @route   POST /api/auth/logout
exports.logout = async (req, res, next) => {
  try {
    const rawToken = req.cookies.refreshToken;
    if (rawToken) {
      const hash = RefreshToken.hashToken(rawToken);
      await RefreshToken.updateMany({ tokenHash: hash }, { revoked: true });
    }
    res.clearCookie('refreshToken');
    res.json({ message: 'Logged out' });
  } catch (err) {
    next(err);
  }
};
```

