// @route   GET /api/auth/enable-2fa
exports.enable2FA = async (req, res, next) => {
  try {
    const user = req.user;
    if (user.is2FAEnabled) return res.status(400).json({ error: '2FA already enabled' });

    const secret = speakeasy.generateSecret({
      length: 20,
      name: `MyApp:${user.email}`
    });
    user.totpSecret = secret.base32;
    await user.save();

    const otpAuthUrl = `otpauth://totp/MyApp:${encodeURIComponent(user.email)}?secret=${secret.base32}&issuer=MyApp`;
    const qrCodeDataUrl = await QRCode.toDataURL(otpAuthUrl);

    res.json({ secret: secret.base32, qrCode: qrCodeDataUrl });
