// @route   POST /api/auth/verify-2fa-enable
exports.verify2FAEnable = async (req, res, next) => {
  try {
    const { token } = req.body; // TOTP from authenticator app
    const user = req.user;
    if (!user.totpSecret) return res.status(400).json({ error: '2FA not set up' });

    const verified = speakeasy.totp.verify({
      secret: user.totpSecret,
      encoding: 'base32',
      token,
      window: 1 // allow 30s drift
    });
    if (!verified) return res.status(400).json({ error: 'Invalid TOTP code' });

    user.is2FAEnabled = true;
    await user.save();
    res.json({ message: '2FA enabled' });
  } catch (err) {
    next(err);
  }
};

// @route   POST /api/auth/login-2fa
exports.login2FA = async (req, res, next) => {
  try {
    const { tempToken, totpCode } = req.body;
    const storedTemp = await TempToken.findOne({ token: tempToken });
    if (!storedTemp || storedTemp.expiresAt < new Date()) {
      return res.status(401).json({ error: 'Invalid or expired temporary token' });
    }

    const user = await User.findById(storedTemp.userId);
    if (!user || !user.is2FAEnabled || !user.totpSecret) {
      return res.status(401).json({ error: '2FA not enabled or user invalid' });
    }

    const verified = speakeasy.totp.verify({
      secret: user.totpSecret,
      encoding: 'base32',
      token: totpCode,
      window: 1
    });
    if (!verified) return res.status(400).json({ error: 'Invalid TOTP code' });

    // Clean up temporary token
    await TempToken.deleteOne({ _id: storedTemp._id });

    // Issue final tokens
    const accessToken = generateAccessToken(user._id);
    const refreshTokenString = generateRefreshToken();
    const hash = RefreshToken.hashToken(refreshTokenString);

    await RefreshToken.create({
      tokenHash: hash,
      userId: user._id,
      expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)
    });

    setRefreshTokenCookie(res, refreshTokenString);
    res.json({ accessToken });
  } catch (err) {
    next(err);
  }
};
