 SequentialPipeline { transformers }
 }
 }

 impl TransformationPipeline for SequentialPipeline {
 fn apply(&self, c: char) -> char {
 self.transformers.iter().fold(c, |acc, transformer| transformer.transform(acc))
 }
 }

