```

### `app.py`
```python
import os
from functools import wraps
from flask import Flask, render_template, request, redirect, url_for, session, flash
from pymongo import MongoClient
from werkzeug.security import generate_password_hash, check_password_hash
from bson.objectid import ObjectId

# ---------- Configuration & Error Handling ----------
# Load environment variables. Use python-dotenv in development if needed.
# from dotenv import load_dotenv
# load_dotenv()

required_env_vars = ['SECRET_KEY', 'MONGO_URI']
for var in required_env_vars:
    if not os.environ.get(var):
        raise RuntimeError(f"Missing required environment variable: {var}")

app = Flask(__name__)
app.secret_key = os.environ['SECRET_KEY']

# ---------- MongoDB Setup ----------
try:
    mongo_client = MongoClient(os.environ['MONGO_URI'])
    mongo_client.server_info()  # trigger connection error early
    db = mongo_client['image_sorting_db']
    users_col = db['users']
    images_col = db['images']
except Exception as e:
    raise RuntimeError(f"Failed to connect to MongoDB: {e}")

# ---------- Permission Mapping ----------
PERMISSION_LEVELS = {
    'guest': 0,
    'regional': 1,
    'national': 2
}

# ---------- Decorators ----------
def login_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            flash('Please log in first.', 'warning')
            return redirect(url_for('login'))
        return f(*args, **kwargs)
    return decorated

def permission_required(min_level):
    """
    Decorate routes to require a minimum permission level.
    `min_level` is a string: 'guest', 'regional', or 'national'.
    """
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if 'user_id' not in session:
                flash('Please log in first.', 'warning')
                return redirect(url_for('login'))

            user = users_col.find_one({'_id': ObjectId(session['user_id'])})
            if not user:
                session.clear()
                flash('User not found.', 'danger')
                return redirect(url_for('login'))

            user_perm = user.get('permission', 'guest')
            user_level = PERMISSION_LEVELS.get(user_perm, 0)
            required_level = PERMISSION_LEVELS.get(min_level, 0)

            if user_level < required_level:
                flash('You do not have permission to access this page.', 'danger')
                return redirect(url_for('dashboard'))
            return f(*args, **kwargs)
        return decorated
    return decorator

# ---------- Routes ----------
@app.route('/')
def home():
    return render_template('home.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')
        if not username or not password:
            flash('Username and password are required.', 'danger')
            return redirect(url_for('login'))

        user = users_col.find_one({'username': username})
        if user and check_password_hash(user['password'], password):
            session['user_id'] = str(user['_id'])
            session['username'] = user['username']
            session['permission'] = user.get('permission', 'guest')
            flash('Login successful.', 'success')
            return redirect(url_for('dashboard'))
        else:
            flash('Invalid username or password.', 'danger')

    return render_template('login.html')

@app.route('/logout')
def logout():
    session.clear()
    flash('You have been logged out.', 'info')
    return redirect(url_for('home'))

@app.route('/dashboard')
@login_required
def dashboard():
    user = users_col.find_one({'_id': ObjectId(session['user_id'])})
    if not user:
        session.clear()
        flash('Session expired.', 'warning')
        return redirect(url_for('login'))
    return render_template('dashboard.html', user=user)

@app.route('/sort', methods=['GET', 'POST'])
@login_required
@permission_required('regional')  # at least regional
def sort_images():
    user = users_col.find_one({'_id': ObjectId(session['user_id'])})
    user_perm = user.get('permission', 'guest')
    user_region = user.get('region')

    if request.method == 'POST':
        # Example sorting action: update image category or status
        image_id = request.form.get('image_id')
        new_category = request.form.get('category')

        if not image_id or not new_category:
            flash('Missing data.', 'warning')
            return redirect(url_for('sort_images'))

        # Permission check for the action
        image = images_col.find_one({'_id': ObjectId(image_id)})
        if not image:
            flash('Image not found.', 'danger')
            return redirect(url_for('sort_images'))

        # National users can sort any image; regional users only images from their region
        if user_perm == 'national' or (user_perm == 'regional' and image.get('region') == user_region):
            images_col.update_one({'_id': ObjectId(image_id)}, {'$set': {'category': new_category}})
            flash('Image sorted successfully.', 'success')
        else:
            flash('You do not have permission to sort this image.', 'danger')

        return redirect(url_for('sort_images'))

    # GET: fetch images based on user permission
    if user_perm == 'national':
        images = list(images_col.find())
    elif user_perm == 'regional':
        images = list(images_col.find({'region': user_region})) if user_region else []
    else:
        images = []  # Should not happen due to decorator

    return render_template('sort.html', user=user, images=images)

# ---------- Error Handlers ----------
@app.errorhandler(404)
def not_found(e):
    return render_template('404.html'), 404

@app.errorhandler(500)
def server_error(e):
    return render_template('500.html'), 500

# ---------- Start ----------
if __name__ == '__main__':
    app.run(debug=True)
```

