## After: The New Async/Await Implementation

All asynchronous operations are promisified, and the logic flows sequentially without nesting.

```javascript
const fs = require('fs').promises;                  // promise-based read
const util = require('util');
const {
  validateSchema,
  checkDuplicates,
  db,
  emailService
} = require('./services');

const validateSchemaAsync = util.promisify(validateSchema);
const checkDuplicatesAsync = util.promisify(checkDuplicates);
const dbInsertAsync = util.promisify(db.insert);
const sendEmailAsync = util.promisify(emailService.send);

async function processFileNew(filename) {
  // 1. Read file
  const data = await fs.readFile(filename, 'utf8');

  // 2. Parse JSON (synchronous, errors thrown automatically)
  const parsed = JSON.parse(data);

  // 3. Validate schema
  const valid = await validateSchemaAsync(parsed);
  if (!valid) throw new Error('Invalid data');

  // 4. Check duplicates
  const isDup = await checkDuplicatesAsync(parsed);
  if (isDup) throw new Error('Duplicate data');

  // 5. Insert into database
  const record = await dbInsertAsync(parsed);

  // 6. Send confirmation email
  await sendEmailAsync(record.email, 'Welcome');

  return record;
}

module.exports = { processFileNew };
```

### Final State (after old code removal)

Once fully migrated, the `processFile` function can simply wrap the async version, or consumers can be updated to use the promise interface directly.

```javascript
// Simplified façade / direct export
const { processFileNew } = require('./processFileNew');

function processFile(filename, callback) {
  processFileNew(filename)
    .then(record => callback(null, record))
    .catch(err => callback(err));
}

module.exports = { processFile, processFileNew };
```

