<body>
    <div id="game-container">
        <h1>💣 Minesweeper</h1>
        <div class="controls" id="difficulty-controls">
            <button id="easy-btn" class="active">Easy (9×9, 10 mines)</button>
            <button id="medium-btn">Medium (16×16, 40 mines)</button>
            <button id="hard-btn">Hard (30×16, 99 mines)</button>
            <button id="reset-btn">🔄 New Game</button>
        </div>
        <div class="info">
            <span id="mine-counter">Mines: 10</span>
            <span id="status">Status: Click a cell to start</span>
        </div>
        <canvas id="game-canvas"></canvas>
    </div>

    <script>
        // ================================================================
        //  GameState – purely manages grid data, mines, flags, and rules
        // ================================================================
        class GameState {
            constructor(rows, cols, totalMines) {
                this.rows = rows;
                this.cols = cols;
                this.totalMines = totalMines;
                this.init();
            }

            // Reset all transient state to start a fresh round
            init() {
                this.revealed = Array.from({ length: this.rows }, () => Array(this.cols).fill(false));
                this.flagged   = Array.from({ length: this.rows }, () => Array(this.cols).fill(false));
                this.numbers   = Array.from({ length: this.rows }, () => Array(this.cols).fill(0));
                this.mines     = new Set();                 // stores "row,col" strings
                this.minesPlaced = false;
                this.firstClickDone = false;
                this.gameStatus = 'waiting';                // 'waiting' | 'playing' | 'win' | 'lose'
                this.revealedCount = 0;
                this.triggeredMine = null;                  // {row, col} of the mine that ended the game
            }

            // ---------- Mine placement (called once, after first click) ----------
            placeMines(excludeRow, excludeCol) {
                // The first click and its 8 neighbours are guaranteed safe -> excluded from mine placement
                const excluded = new Set();
                for (let dr = -1; dr <= 1; dr++) {
                    for (let dc = -1; dc <= 1; dc++) {
                        const r = excludeRow + dr;
                        const c = excludeCol + dc;
                        if (this.isValidCell(r, c)) excluded.add(`${r},${c}`);
                    }
                }

                // All cells that are allowed to contain a mine
                const eligible = [];
                for (let r = 0; r < this.rows; r++) {
                    for (let c = 0; c < this.cols; c++) {
                        if (!excluded.has(`${r},${c}`)) {
                            eligible.push({ r, c });
                        }
                    }
                }

                // Shuffle eligible cells using Fisher‑Yates and pick the first totalMines
                this.shuffleArray(eligible);
                this.mines.clear();
                for (let i = 0; i < this.totalMines; i++) {
                    const cell = eligible[i];
                    this.mines.add(`${cell.r},${cell.c}`);
                }

                this.calculateNumbers();
                this.minesPlaced = true;
            }

            // For every non‑mine cell, count how many mines touch it
            calculateNumbers() {
                // Reset counts
                for (let r = 0; r < this.rows; r++) {
                    for (let c = 0; c < this.cols; c++) {
                        this.numbers[r][c] = 0;
                    }
                }
                for (let mineStr of this.mines) {
                    const [r, c] = mineStr.split(',').map(Number);
                    for (let dr = -1; dr <= 1; dr++) {
                        for (let dc = -1; dc <= 1; dc++) {
                            const nr = r + dr;
                            const nc = c + dc;
                            if (this.isValidCell(nr, nc) && !this.mines.has(`${nr},${nc}`)) {
                                this.numbers[nr][nc]++;
                            }
                        }
                    }
                }
            }

            // ---------- Core interaction: reveal a cell (with BFS flood‑fill) ----------
            revealCell(row, col) {
                if (!this.isValidCell(row, col) || this.revealed[row][col] || this.flagged[row][col]) return;
                if (this.gameStatus !== 'waiting' && this.gameStatus !== 'playing') return;

                // First click -> plant mines, then continue to reveal
                if (!this.firstClickDone) {
                    this.firstClickDone = true;
                    this.placeMines(row, col);
                    this.gameStatus = 'playing';
                }

                // Hit a mine -> game over
                if (this.mines.has(`${row},${col}`)) {
                    this.gameStatus = 'lose';
                    this.triggeredMine = { row, col };
                    this.revealed[row][col] = true;
                    this.revealAllMines();
                    return;
                }

                // BFS (flood‑fill) to reveal all connected empty cells and their numbered borders
                const queue = [{ r: row, c: col }];
                const visited = new Set();
                visited.add(`${row},${col}`);

                while (queue.length > 0) {
                    const { r, c } = queue.shift();
                    if (this.revealed[r][c]) continue;          // safety check

                    this.revealed[r][c] = true;
                    this.revealedCount++;

                    // If the cell is empty (0), add all its unrevealed, unflagged neighbours
                    if (this.numbers[r][c] === 0) {
                        for (let dr = -1; dr <= 1; dr++) {
                            for (let dc = -1; dc <= 1; dc++) {
                                if (dr === 0 && dc === 0) continue;
                                const nr = r + dr;
                                const nc = c + dc;
                                const key = `${nr},${nc}`;
                                if (this.isValidCell(nr, nc) && !this.revealed[nr][nc] && !this.flagged[nr][nc] && !visited.has(key)) {
                                    visited.add(key);
                                    queue.push({ r: nr, c: nc });
                                }
                            }
                        }
                    }
                }

                // Win condition: all non‑mine cells revealed
                if (this.revealedCount === this.rows * this.cols - this.totalMines) {
                    this.gameStatus = 'win';
                }
            }

            // Show all mines (called on game loss)
            revealAllMines() {
                for (let mineStr of this.mines) {
                    const [r, c] = mineStr.split(',').map(Number);
                    this.revealed[r][c] = true;
                }
            }

            // ---------- Flag management ----------
            toggleFlag(row, col) {
                if (!this.isValidCell(row, col) || this.revealed[row][col]) return;
                if (this.gameStatus !== 'playing') return;
                this.flagged[row][col] = !this.flagged[row][col];
            }

            getFlagCount() {
                let count = 0;
                for (let r = 0; r < this.rows; r++)
                    for (let c = 0; c < this.cols; c++)
                        if (this.flagged[r][c]) count++;
                return count;
            }

            // ---------- Helpers ----------
            isValidCell(r, c) {
                return r >= 0 && r < this.rows && c >= 0 && c < this.cols;
            }

            shuffleArray(arr) {
                for (let i = arr.length - 1; i > 0; i--) {
                    const j = Math.floor(Math.random() * (i + 1));
                    [arr[i], arr[j]] = [arr[j], arr[i]];
                }
            }
        }

        // ================================================================
        //  Renderer – draws the game on a <canvas>, driven by rAF
        // ================================================================
        class Renderer {
            constructor(canvas, gameState) {
                this.canvas = canvas;
                this.ctx = canvas.getContext('2d');
                this.gameState = gameState;
                this.cellSize = 30;                // pixels per cell (internal resolution)
                this.needsRedraw = true;

                // Color palette
                this.colors = {
                    unrevealed: '#bdbdbd',
                    revealed:   '#e0e0e0',
                    numberColors: [
                        '',           // 0 (not drawn)
                        '#0000ff',    // 1
                        '#008000',    // 2
                        '#ff0000',    // 3
                        '#000080',    // 4
                        '#800000',    // 5
                        '#008080',    // 6
                        '#000000',    // 7
                        '#808080'     // 8
                    ]
                };

                this.initCanvas();
                this.startRenderLoop();
            }

            initCanvas() {
                this.canvas.width  = this.gameState.cols * this.cellSize;
                this.canvas.height = this.gameState.rows * this.cellSize;
            }

            // Continuously checks the `needsRedraw` flag – redraws once, then waits for the next flag
            startRenderLoop() {
                const loop = () => {
                    if (this.needsRedraw) {
                        this.draw();
                        this.needsRedraw = false;
                    }
                    requestAnimationFrame(loop);
                };
                requestAnimationFrame(loop);
            }

            // ---------- Main draw routine ----------
            draw() {
                const ctx = this.ctx;
                const gs  = this.gameState;
                const cs  = this.cellSize;

                ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

                // Iterate every cell of the grid
                for (let r = 0; r < gs.rows; r++) {
                    for (let c = 0; c < gs.cols; c++) {
                        const x = c * cs;
                        const y = r * cs;
                        const isRevealed = gs.revealed[r][c];
                        const isFlagged  = gs.flagged[r][c];
                        const isMine     = gs.mines.has(`${r},${c}`);
                        const number     = gs.numbers[r][c];

                        if (isRevealed) {
                            // Revealed cell background
                            ctx.fillStyle = this.colors.revealed;
                            ctx.fillRect(x, y, cs, cs);

                            if (isMine) {
                                // Draw mine body (black circle)
                                ctx.fillStyle = '#000';
                                ctx.beginPath();
                                ctx.arc(x + cs / 2, y + cs / 2, cs / 4, 0, Math.PI * 2);
                                ctx.fill();
                                // Specular highlight
                                ctx.fillStyle = '#fff';
                                ctx.beginPath();
                                ctx.arc(x + cs / 2 - cs / 10, y + cs / 2 - cs / 10, cs / 10, 0, Math.PI * 2);
                                ctx.fill();

                                // If this is the mine the player clicked, tint the background red
                                if (gs.triggeredMine && gs.triggeredMine.row === r && gs.triggeredMine.col === c) {
                                    ctx.fillStyle = 'rgba(255, 0, 0, 0.45)';
                                    ctx.fillRect(x, y, cs, cs);
                                }
                            } else if (number > 0) {
                                // Draw the number hint
                                ctx.fillStyle = this.colors.numberColors[number];
                                ctx.font = `bold ${cs * 0.7}px "Courier New", monospace`;
                                ctx.textAlign = 'center';
                                ctx.textBaseline = 'middle';
                                ctx.fillText(number, x + cs / 2, y + cs / 2);
                            }
                        } else {
                            // Unrevealed cell – raised 3D look
                            ctx.fillStyle = this.colors.unrevealed;
                            ctx.fillRect(x, y, cs, cs);

                            // Highlight (top & left)
                            ctx.fillStyle = '#ffffff';
                            ctx.fillRect(x, y, cs, 2);
                            ctx.fillRect(x, y, 2, cs);
                            // Shadow (bottom & right)
                            ctx.fillStyle = '#7b7b7b';
                            ctx.fillRect(x, y + cs - 2, cs, 2);
                            ctx.fillRect(x + cs - 2, y, 2, cs);

                            if (isFlagged) {
                                // Draw a red flag (triangle + pole)
                                ctx.fillStyle = '#ff0000';
                                ctx.beginPath();
                                ctx.moveTo(x + cs * 0.3, y + cs * 0.2);
                                ctx.lineTo(x + cs * 0.7, y + cs * 0.4);
                                ctx.lineTo(x + cs * 0.3, y + cs * 0.6);
                                ctx.fill();
                                ctx.strokeStyle = '#000';
                                ctx.lineWidth = 1.5;
                                ctx.beginPath();
                                ctx.moveTo(x + cs * 0.3, y + cs * 0.2);
                                ctx.lineTo(x + cs * 0.3, y + cs * 0.8);
                                ctx.stroke();
                                ctx.lineWidth = 1; // reset for grid lines
                            }
                        }

                        // Thin grid line around every cell
                        ctx.strokeStyle = '#888';
                        ctx.lineWidth = 0.5;
                        ctx.strokeRect(x, y, cs, cs);
                    }
                }

                // ----- Game‑over / win overlay -----
                if (gs.gameStatus === 'lose') {
                    ctx.fillStyle = 'rgba(255, 0, 0, 0.15)';
                    ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);
                    ctx.fillStyle = '#000';
                    ctx.font = '40px Arial';
                    ctx.textAlign = 'center';
                    ctx.fillText('Game Over', this.canvas.width / 2, this.canvas.height / 2);
                } else if (gs.gameStatus === 'win') {
                    ctx.fillStyle = 'rgba(0, 255, 0, 0.15)';
                    ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);
                    ctx.fillStyle = '#000';
                    ctx.font = '40px Arial';
                    ctx.textAlign = 'center';
                    ctx.fillText('You Win! 🎉', this.canvas.width / 2, this.canvas.height / 2);
                }
            }
        }

        // ================================================================
        //  InputHandler – translates mouse events into game actions
        // ================================================================
        class InputHandler {
            constructor(canvas, gameState, renderer) {
                this.canvas = canvas;
                this.gameState = gameState;
                this.renderer = renderer;

                // Attach listeners once
                this.canvas.addEventListener('mousedown', this.onMouseDown.bind(this));
                this.canvas.addEventListener('contextmenu', (e) => e.preventDefault()); // suppress right‑click menu
                this.canvas.addEventListener('mouseup', (e) => e.preventDefault());     // prevent text selection
            }

            // Update references when a new game starts (avoids rebinding events)
            setGameReferences(gameState, renderer) {
                this.gameState = gameState;
                this.renderer = renderer;
            }

            // Convert mouse event coordinates to (row, col), accounting for CSS scaling
            getCellFromEvent(e) {
                const rect = this.canvas.getBoundingClientRect();
                const scaleX = this.canvas.width / rect.width;    // ratio if canvas is CSS‑scaled
                const scaleY = this.canvas.height / rect.height;

                const x = (e.clientX - rect.left) * scaleX;
                const y = (e.clientY - rect.top) * scaleY;

                const col = Math.floor(x / this.renderer.cellSize);
                const row = Math.floor(y / this.renderer.cellSize);

                return this.gameState.isValidCell(row, col) ? { row, col } : null;
            }

            onMouseDown(e) {
                const cell = this.getCellFromEvent(e);
                if (!cell) return;
                e.preventDefault();

                if (e.button === 0) {         // left click
                    this.handleLeftClick(cell.row, cell.col);
                } else if (e.button === 2) { // right click
                    this.handleRightClick(cell.row, cell.col);
                }
            }

            handleLeftClick(row, col) {
                if (this.gameState.gameStatus === 'win' || this.gameState.gameStatus === 'lose') return;
                if (this.gameState.flagged[row][col]) return;   // ignore flagged cells

                this.gameState.revealCell(row, col);
                this.renderer.needsRedraw = true;
                this.updateUI();
            }

            handleRightClick(row, col) {
                if (this.gameState.gameStatus !== 'playing') return;
                this.gameState.toggleFlag(row, col);
                this.renderer.needsRedraw = true;
                this.updateUI();
            }

            // Sync the text status bar and mine counter with the current state
            updateUI() {
                const mineCounter = document.getElementById('mine-counter');
                const statusEl    = document.getElementById('status');

                if (mineCounter) {
                    const flags = this.gameState.getFlagCount();
                    const mines = this.gameState.totalMines;
                    mineCounter.textContent = `Mines: ${mines - flags}`;
                }
                if (statusEl) {
                    switch (this.gameState.gameStatus) {
                        case 'waiting': statusEl.textContent = 'Status: Click a cell to start'; break;
                        case 'playing': statusEl.textContent = 'Status: Playing';               break;
                        case 'win':     statusEl.textContent = 'Status: You Win! 🎉';            break;
                        case 'lose':    statusEl.textContent = 'Status: Game Over 💥';           break;
                    }
                }
            }
        }

        // ================================================================
        //  Application bootstrap & UI wiring
        // ================================================================
        let currentGame = null;           // holds { gameState, renderer, inputHandler }

        function startNewGame(rows, cols, mines) {
            const canvas = document.getElementById('game-canvas');
            const gameState = new GameState(rows, cols, mines);
            const renderer = new Renderer(canvas, gameState);

            // Re‑use the existing InputHandler (so we don't pile up event listeners)
            if (currentGame && currentGame.inputHandler) {
                currentGame.inputHandler.setGameReferences(gameState, renderer);
                currentGame.gameState = gameState;
                currentGame.renderer = renderer;
            } else {
                const inputHandler = new InputHandler(canvas, gameState, renderer);
                currentGame = { gameState, renderer, inputHandler };
            }

            // Mark for redraw and update the text UI
            currentGame.renderer.needsRedraw = true;
            currentGame.inputHandler.updateUI();

            // Highlight the active difficulty button
            const buttons = document.querySelectorAll('#difficulty-controls button:not(#reset-btn)');
            buttons.forEach(btn => btn.classList.remove('active'));
            if (rows === 9 && cols === 9 && mines === 10) {
                document.getElementById('easy-btn').classList.add('active');
            } else if (rows === 16 && cols === 16 && mines === 40) {
                document.getElementById('medium-btn').classList.add('active');
            } else if (rows === 30 && cols === 16 && mines === 99) {
                document.getElementById('hard-btn').classList.add('active');
            }
        }

        // --- Attach UI buttons after the DOM is ready ---
        window.addEventListener('DOMContentLoaded', () => {
            document.getElementById('easy-btn').addEventListener('click',   () => startNewGame(9, 9, 10));
            document.getElementById('medium-btn').addEventListener('click', () => startNewGame(16, 16, 40));
            document.getElementById('hard-btn').addEventListener('click',   () => startNewGame(30, 16, 99));
            document.getElementById('reset-btn').addEventListener('click',  () => {
                if (currentGame && currentGame.gameState) {
                    const gs = currentGame.gameState;
                    startNewGame(gs.rows, gs.cols, gs.totalMines);
                } else {
                    startNewGame(9, 9, 10);
                }
            });

            // Kick off with an Easy game
            startNewGame(9, 9, 10);
        });
    </script>
</body>
</html>
```

**NuRCU: A NUMA‑Aware Hierarchical RCU for Heterogeneous Systems with Provable Safety**

### 1. Problem and Design Goals
We require a Read‑Copy‑Update (RCU) synchronization scheme that:
* Is **lock‑free** on the read side.
* Guarantees **detection of quiescent states** (moments when no thread holds an RCU read lock).
* Operates in a **heterogeneous multicore** system with **non‑uniform memory access (NUMA)**.
* **Minimizes read‑side latency overhead**.
* Is **provably safe under arbitrary thread preemption**.

Standard RCU implementations either rely on tight kernel integration (e.g., Linux’s Tree RCU, which hooks into the scheduler) or incur high read‑side costs (memory barriers on every lock/unlock). We present **NuRCU**, a design that decouples read‑side ordering from the fast path by using a global memory barrier on the writer side, and scales to many cores via a **NUMA‑partitioned hierarchical tree of active‑reader counters**.

---

### 2. System Model
* **Hardware:** Cache‑coherent shared‑memory system with multiple NUMA domains. Cores within a domain share a local memory controller; cross‑domain accesses are slower. Cores may differ in instruction‑set architecture or performance (heterogeneity).
* **Threads:** Preemptively scheduled by the OS; a thread can be descheduled **at any arbitrary point**, including inside an RCU read‑side critical section.
* **Memory Ordering:** Weakly ordered memory model (e.g., ARM, PowerPC) unless explicit barriers are used. We assume the availability of a lightweight **global memory barrier** primitive – such as Linux’s `membarrier(MEMBARRIER_CMD_GLOBAL)` or an equivalent IPI‑based mechanism – that can force a memory barrier on all cores.

---

### 3. NuRCU Design

#### 3.1 Overall Architecture
NuRCU organises threads into a two‑level hierarchy:
* **Leaf nodes:** Each covers a small group of threads (e.g., 16–32) that share a NUMA domain. A leaf maintains an **active‑reader count**.
* **Global epoch counter:** A monotonically increasing `gp_num` that writers advance to start a new grace period.

The **read side** is extremely lightweight: threads update only local (per‑thread) data and occasionally an atomic counter in their local leaf. No hardware memory barriers are used.
The **writer side** performs a global barrier, advances the epoch, and then waits for every leaf to report that its active count has dropped to zero. Because leaves are much fewer than threads, this wait scales well and stays NUMA‑friendly.

#### 3.2 Data Structures (per NUMA node)
```c
// Per thread (allocated on thread’s local NUMA node)
struct rcu_thread_state {
    int nesting;                    // non-atomic, accessed only by owner
    struct rcu_leaf *leaf;          // pointer to local leaf
};

// Leaf node (one per group of threads on the same NUMA node)
struct rcu_leaf {
    atomic_int active_count;        // number of threads in this leaf with nesting > 0
    atomic_int gp_to_watch;         // grace period number that needs a QS report
    atomic_int last_reported_gp;    // the latest gp_num this leaf has already reported
};

// Global
atomic_long global_gp_num;          // current grace period epoch
```
All per‑thread and per‑leaf memory is allocated from the threads’ **local NUMA node**, so the fast path hits local caches.

#### 3.3 Read‑Side Fast Path (Lock‑Free)
```c
void rcu_read_lock(struct rcu_thread_state *self) {
    if (self->nesting == 0) {
        // Transition 0 → 1: announce presence to the leaf
        atomic_fetch_add_explicit(&self->leaf->active_count, 1,
                                  memory_order_relaxed);
    }
    self->nesting++;
    compiler_barrier();   // prevent code hoisting, no CPU barrier
}

void rcu_read_unlock(struct rcu_thread_state *self) {
    compiler_barrier();
    self->nesting--;
    if (self->nesting == 0) {
        // Last RCU lock released – decrement leaf counter
        if (atomic_fetch_sub_explicit(&self->leaf->active_count, 1,
                                      memory_order_relaxed) == 1) {
            // active_count just became 0. Check if a GP report is owed.
            int gp = atomic_load_explicit(&self->leaf->gp_to_watch,
                                          memory_order_acquire);
            int old = atomic_load_explicit(&self->leaf->last_reported_gp,
                                           memory_order_relaxed);
            if (gp > old) {
                atomic_compare_exchange_strong(&self->leaf->last_reported_gp,
                                               &old, gp,
                                               memory_order_release);
            }
        }
    }
}
```
`rcu_dereference(p)` is implemented as a simple `READ_ONCE(p)` (a relaxed load with a compiler barrier), because the writer’s global barrier ensures correctness without an acquire.

**Overhead:** Two integer increments (local), one atomic RMW on the leaf’s `active_count` (only on the first lock / last unlock of a batch). All operations touch memory in the local NUMA domain. No hardware memory fences.

#### 3.4 Writer‑Side Grace Period
```c
void synchronize_rcu() {
    // 1. Publish new data (pointer update, etc.)
    atomic_store_explicit(&shared_ptr, new_ptr, memory_order_relaxed);

    // 2. Global memory barrier (e.g., membarrier syscall)
    //    Ensures all prior stores on all cores are visible,
    //    and that subsequent loads see a consistent state.
    membarrier(MEMBARRIER_CMD_GLOBAL);

    // 3. Advance the global grace‑period epoch
    int new_gp = atomic_fetch_add_explicit(&global_gp_num, 1,
                                           memory_order_relaxed) + 1;

    // 4. Notify all leaves of the new GP; immediately report any already idle
    for_each_leaf (L) {
        atomic_store_explicit(&L->gp_to_watch, new_gp, memory_order_release);
        if (atomic_load_explicit(&L->active_count, memory_order_acquire) == 0) {
            // Leaf is already quiescent – try to report on its behalf
            int old = atomic_load_explicit(&L->last_reported_gp, memory_order_relaxed);
            if (new_gp > old)
                atomic_compare_exchange_strong(&L->last_reported_gp, &old, new_gp,
                                               memory_order_release);
        }
    }

    // 5. Wait until every leaf has reported for this GP
    for_each_leaf (L) {
        while (atomic_load_explicit(&L->last_reported_gp,
                                    memory_order_acquire) < new_gp) {
            spin_or_yield();  // busy‑wait, can also block on a per‑leaf event
        }
    }

    // 6. All pre‑grace‑period readers are gone; safe to reclaim old data.
    kfree(old_ptr);
}
```

#### 3.5 Handling Arbitrary Thread Preemption
* **Preempted inside a critical section** (`nesting > 0`): The leaf’s `active_count` stays non‑zero. The leaf **cannot** report until the thread resumes and calls `rcu_read_unlock`. The writer blocks – this is correct because the preempted thread still holds a reference to the old data. Forward progress of reclamation resumes as soon as the reader finishes its critical section.
* **Preempted outside a critical section** (`nesting == 0`): The leaf’s `active_count` is unaffected. If the thread has not yet reported for the current GP, the writer might wait for it. However, a thread that is not in a critical section is already **quiescent**. In our design, this is handled in step 4 of the writer: if `active_count == 0` at GP start, the writer immediately reports the leaf (or the leaf reports itself). Thus a sleeping/idle thread never blocks the writer.
* New threads created during a grace period are initialised with `last_reported_gp = current_gp`, so they are born quiescent.

#### 3.6 Memory Ordering and Safety Proof
The design follows the proven ordering of **userspace RCU’s membarrier flavor**, adapted to a hierarchical epoch scheme.

**Key ordering guarantee:**
* Writer stores new data (relaxed).
* Writer executes `membarrier` → **a full barrier on every core**.
* Writer advances `gp_num` and sets leaf `gp_to_watch`.

Any reader that increments `active_count` **before** the global barrier on its core will have that increment visible to the writer’s step 4/5.  
Any reader that begins a critical section **after** the global barrier on its core will see the writer’s new data (the barrier flushed the writer’s store and orders the reader’s subsequent loads).

**Quiescent state detection invariant:**  
A leaf’s `last_reported_gp` reaches `new_gp` only after its `active_count` has been zero at some point **since** `new_gp` was written to `gp_to_watch`. Because each active reader increments `active_count` before entering its critical section and decrements it after, the system reaches a state where no thread holds a pre‑grace‑period pointer reference exactly when all leaves have reported. This proves **safe reclamation**.

**Lock‑freedom:** The read‑side path is obstruction‑free (no locks, no blocking). The writer performs atomic operations and may spin waiting for readers, which is typical for RCU grace‑period waiting.

---

### 4. Latency Analysis and NUMA Optimisations

**Read‑side latency** is minimised:
* No hardware memory barriers on the fast path.
* Only **local** memory accesses: `nesting` is thread‑private, `active_count` is in a cache line shared only by the small group of threads on the **same NUMA node**. Contention is negligible for typical leaf sizes (16–32 threads).
* On x86, the unoptimised fast path is ~2‑3 instructions; on ARM, the atomics are single instructions with no DMB.

**NUMA awareness:**
* All per‑thread and leaf structures are allocated on the thread’s home node. Thread migration is allowed but discouraged; if a thread migrates, its leaf accesses may become remote, but correctness is unaffected. The system can optionally re‑home the thread to a local leaf.
* The writer’s pass over leaves performs **one remote read per leaf** (O(leaves)), which is much cheaper than scanning every thread (O(threads)). Because leaves are placed on their respective NUMA nodes, the writer can parallelise the scan to overlap cross‑node latencies.
* The global barrier (`membarrier`) is a single syscall whose cost is amortised over many updates.

**Grace‑period latency** is dominated by the longest read‑side critical section. In a heterogeneous system, a slow core holding a lock may delay reclamation, which is semantically required by RCU. The hierarchical design allows fast cores to report quickly, unblocking the local leaf, while the writer only waits for the slowest leaf.

---

### 5. Heterogeneity Considerations
* **Mixed ISAs / performance levels:** The read‑side primitives use only standard atomic operations and compiler barriers, which are portable. The global barrier mechanism must cover all cores; on Linux, `membarrier` is architecture‑independent.
* **Topology discovery:** During initialisation, the system groups cores into leaves based on NUMA distances and optionally core type (e.g., separating big and LITTLE cores into different leaves to avoid fast readers being delayed by slow‑core contention on the same `active_count` cache line). This grouping is a configuration parameter and does not change the algorithm’s logic.
* **Preemption on slow cores:** A reader preempted on a little core holds its leaf’s `active_count` high. The writer correctly waits; no safety violation occurs.

---

### 6. Conclusion
NuRCU achieves lock‑free, low‑latency read‑side RCU in a heterogeneous, NUMA system. By combining **(i)** per‑thread nesting with **(ii)** a hierarchically partitioned active‑reader count and **(iii)** a writer‑side global memory barrier, it eliminates read‑side hardware fences while keeping writer‑side scanning scalable. The design is provably safe under arbitrary preemption because the active count precisely tracks live critical sections, and the epoch‑based reporting guarantees that a quiescent state is detected exactly when all pre‑existing readers have departed. This makes it suitable for performance‑critical applications on modern asymmetric multicore processors.

## Production-Ready Fix: Idempotent Payment Processing with MySQL & Kafka

### 1. Root Cause & Solution Overview
During payment-provider failover, the same charge request is retried by upstream clients or internal retry logic. Without idempotency, duplicate requests reach the provider, causing duplicate charges.  

**Fix:** Introduce a **strict idempotency layer** using a unique `idempotency_key` (passed by the client or derived from the basket). The service:
- Records every payment attempt in MySQL before calling the provider.
- On duplicate keys, returns the previously stored result for 24 hours.
- Uses a transactional outbox pattern to reliably publish payment events to Kafka (allowing replay without duplication).

---

### 2. Database Schema Migration
Add two tables: `payment_idempotency` for deduplication and `outbox_events` for reliable Kafka publishing.

```sql
-- 001_add_idempotency_and_outbox.sql

CREATE TABLE payment_idempotency (
    idempotency_key VARCHAR(255) NOT NULL,
    status ENUM('processing','succeeded','failed') NOT NULL,
    response_data JSON DEFAULT NULL,
    correlation_id VARCHAR(255) NOT NULL,
    created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    PRIMARY KEY (idempotency_key),
    INDEX idx_status_updated (status, updated_at)   -- for stale record sweeping
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE outbox_events (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    event_type VARCHAR(255) NOT NULL,
    payload JSON NOT NULL,
    correlation_id VARCHAR(255) NOT NULL,
    created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    published BOOLEAN NOT NULL DEFAULT FALSE,
    INDEX idx_published_created (published, created_at)  -- for outbox poller
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
```

**Cleanup Job:** Run every hour to delete records older than 24 hours (after they’ve served their retry window) and to mark stuck `processing` records as `failed` after a 5‑minute timeout.

```sql
-- Periodic cleanup (run via cron or scheduled job)
DELETE FROM payment_idempotency
WHERE created_at < NOW() - INTERVAL 24 HOUR
  AND status IN ('succeeded', 'failed');

UPDATE payment_idempotency
SET status = 'failed',
    response_data = JSON_OBJECT('error', 'processing_timeout'),
    updated_at = NOW(3)
WHERE status = 'processing'
  AND updated_at < NOW() - INTERVAL 5 MINUTE;
```

---

### 3. Service-Layer Code (Go)
We’ll implement `CheckoutService.ProcessPayment` with idempotency guarantees. The code uses `database/sql`, `logrus` for structured logging, and Prometheus metrics.

```go
package checkout

import (
    "context"
    "database/sql"
    "encoding/json"
    "fmt"
    "time"

    "github.com/prometheus/client_golang/prometheus"
    log "github.com/sirupsen/logrus"
)

// Prometheus metrics
var (
    idempotencyHits = prometheus.NewCounter(prometheus.CounterOpts{
        Name: "checkout_idempotency_hits_total",
        Help: "Number of duplicate payment requests returned from cache.",
    })
    idempotencyProcessingConflicts = prometheus.NewCounter(prometheus.CounterOpts{
        Name: "checkout_idempotency_processing_conflicts_total",
        Help: "Number of duplicate requests received while original is still processing.",
    })
    outboxPublished = prometheus.NewCounter(prometheus.CounterOpts{
        Name: "checkout_outbox_published_total",
        Help: "Number of outbox events successfully published to Kafka.",
    })
)

func init() {
    prometheus.MustRegister(idempotencyHits, idempotencyProcessingConflicts, outboxPublished)
}

type PaymentRequest struct {
    IdempotencyKey string
    Amount         int64
    Currency       string
    // ... other payment details
    CorrelationID  string
}

type PaymentResponse struct {
    Status      string // "succeeded" or "failed"
    ProviderID  string
    Message     string
    CorrelationID string
}

type CheckoutService struct {
    db              *sql.DB
    paymentProvider PaymentProvider
    kafka           KafkaProducer
}

// Main entry point with idempotency and retry window.
func (s *CheckoutService) ProcessPayment(ctx context.Context, req PaymentRequest) (*PaymentResponse, error) {
    // Add correlation id to all subsequent logs
    logger := log.WithField("correlation_id", req.CorrelationID)

    // 1. Idempotency check / insert
    existingResp, err := s.checkOrCreateIdempotency(ctx, req, logger)
    if err != nil {
        return nil, fmt.Errorf("idempotency check failed: %w", err)
    }
    if existingResp != nil {
        // Duplicate request – return stored result
        logger.WithField("idempotency_key", req.IdempotencyKey).
            Info("Duplicate request served from cache")
        idempotencyHits.Inc()
        return existingResp, nil
    }

    // 2. Call payment provider (with retry logic for transient failures)
    paymentResult, err := s.chargeWithRetry(ctx, req)
    if err != nil {
        // Even on failure, we must update the idempotency record
        // so that retries don't keep hitting the provider.
        s.finalizeIdempotency(ctx, req.IdempotencyKey, "failed", nil, req.CorrelationID, logger)
        return nil, fmt.Errorf("payment failed: %w", err)
    }

    // 3. Build response
    resp := &PaymentResponse{
        Status:      paymentResult.Status,
        ProviderID:  paymentResult.ProviderID,
        Message:     paymentResult.Message,
        CorrelationID: req.CorrelationID,
    }

    // 4. Atomically update idempotency record and insert outbox event
    if err := s.finalizeIdempotencyWithOutbox(ctx, req.IdempotencyKey, "succeeded", resp, req.CorrelationID); err != nil {
        // At this point the payment already succeeded – we must not fail the client.
        // Log critical error and alert on-call; the outbox publisher will eventually
        // pick up the event if we fall back to a manual insert.
        logger.WithError(err).Error("CRITICAL: failed to finalize idempotency after successful payment")
    }

    return resp, nil
}

// checkOrCreateIdempotency inserts a 'processing' row. Returns the cached response if
// the key already exists and is terminal, or an error if still processing (client should retry).
func (s *CheckoutService) checkOrCreateIdempotency(ctx context.Context, req PaymentRequest, logger *log.Entry) (*PaymentResponse, error) {
    tx, err := s.db.BeginTx(ctx, nil)
    if err != nil {
        return nil, err
    }
    defer tx.Rollback()

    // Try inserting a new 'processing' record
    _, err = tx.ExecContext(ctx, `
        INSERT INTO payment_idempotency
            (idempotency_key, status, correlation_id, created_at, updated_at)
        VALUES (?, 'processing', ?, NOW(3), NOW(3))
    `, req.IdempotencyKey, req.CorrelationID)

    if err == nil {
        // Successfully reserved the key – proceed with payment.
        if commitErr := tx.Commit(); commitErr != nil {
            return nil, commitErr
        }
        return nil, nil  // no existing response, caller should process
    }

    // Duplicate entry error – key already exists
    if !isDuplicateKeyError(err) {
        return nil, err
    }
    tx.Rollback() // explicitly rollback, though deferred

    // Read the existing row
    var status string
    var responseData []byte
    var updatedAt time.Time
    err = s.db.QueryRowContext(ctx, `
        SELECT status, response_data, updated_at
        FROM payment_idempotency
        WHERE idempotency_key = ?
    `, req.IdempotencyKey).Scan(&status, &responseData, &updatedAt)
    if err != nil {
        return nil, fmt.Errorf("reading existing idempotency key: %w", err)
    }

    switch status {
    case "succeeded", "failed":
        // Terminal state – return stored response
        var resp PaymentResponse
        if err := json.Unmarshal(responseData, &resp); err != nil {
            return nil, fmt.Errorf("unmarshalling stored response: %w", err)
        }
        return &resp, nil

    case "processing":
        // Check if the record is stale (after 60 seconds we assume the original died)
        if time.Since(updatedAt) > 60*time.Second {
            logger.Warn("Taking over stale processing record")
            // Update the record as if we started a fresh attempt
            _, err = s.db.ExecContext(ctx, `
                UPDATE payment_idempotency
                SET status = 'processing',
                    correlation_id = ?,
                    updated_at = NOW(3)
                WHERE idempotency_key = ? AND status = 'processing'
            `, req.CorrelationID, req.IdempotencyKey)
            if err != nil {
                return nil, fmt.Errorf("taking over stale record: %w", err)
            }
            return nil, nil // proceed with payment
        }

        // Original still active – return a retryable error
        idempotencyProcessingConflicts.Inc()
        return nil, fmt.Errorf("payment with idempotency_key %s is already in progress; retry after 5 seconds", req.IdempotencyKey)

    default:
        return nil, fmt.Errorf("unknown idempotency status: %s", status)
    }
}

// finalizeIdempotency updates the status and response_data for a completed payment.
func (s *CheckoutService) finalizeIdempotency(ctx context.Context, idempotencyKey string,
    status string, resp *PaymentResponse, correlationID string, logger *log.Entry) error {

    var respJSON []byte
    if resp != nil {
        respJSON, _ = json.Marshal(resp)
    }
    _, err := s.db.ExecContext(ctx, `
        UPDATE payment_idempotency
        SET status = ?,
            response_data = ?,
            updated_at = NOW(3)
        WHERE idempotency_key = ? AND status = 'processing'
    `, status, respJSON, idempotencyKey)
    if err != nil {
        logger.WithError(err).Error("Failed to update idempotency record")
    }
    return err
}

// finalizeIdempotencyWithOutbox atomically updates the record and inserts an outbox event.
func (s *CheckoutService) finalizeIdempotencyWithOutbox(ctx context.Context,
    idempotencyKey string, status string, resp *PaymentResponse, correlationID string) error {

    tx, err := s.db.BeginTx(ctx, nil)
    if err != nil {
        return err
    }
    defer tx.Rollback()

    respJSON, _ := json.Marshal(resp)
    _, err = tx.ExecContext(ctx, `
        UPDATE payment_idempotency
        SET status = ?, response_data = ?, updated_at = NOW(3)
        WHERE idempotency_key = ? AND status = 'processing'
    `, status, respJSON, idempotencyKey)
    if err != nil {
        return fmt.Errorf("update idempotency in tx: %w", err)
    }

    eventPayload, _ := json.Marshal(map[string]interface{}{
        "idempotency_key": idempotencyKey,
        "status":          status,
        "response":        resp,
    })
    _, err = tx.ExecContext(ctx, `
        INSERT INTO outbox_events (event_type, payload, correlation_id, created_at)
        VALUES (?, ?, ?, NOW(3))
    `, "payment_completed", eventPayload, correlationID)
    if err != nil {
        return fmt.Errorf("insert outbox event in tx: %w", err)
    }

    return tx.Commit()
}

// chargeWithRetry calls the payment provider with exponential backoff.
func (s *CheckoutService) chargeWithRetry(ctx context.Context, req PaymentRequest) (*PaymentResult, error) {
    // Implementation includes retry logic, using req.IdempotencyKey as provider reference.
    // ...
}
```

---

### 4. Kafka Outbox Publisher (At-Least-Once Semantic)
A background goroutine polls `outbox_events` and reliably publishes to Kafka. This ensures that payment events survive crashes and can be replayed by downstream services.

```go
func (s *CheckoutService) StartOutboxPublisher(ctx context.Context, pollInterval time.Duration) {
    go func() {
        for {
            select {
            case <-ctx.Done():
                return
            case <-time.After(pollInterval):
                s.publishOutboxEvents(ctx)
            }
        }
    }()
}

func (s *CheckoutService) publishOutboxEvents(ctx context.Context) {
    tx, err := s.db.BeginTx(ctx, nil)
    if err != nil {
        log.WithError(err).Error("outbox publisher: begin tx")
        return
    }
    defer tx.Rollback()

    // Read the oldest unpublished events (limit to avoid long transactions)
    rows, err := tx.QueryContext(ctx, `
        SELECT id, event_type, payload, correlation_id
        FROM outbox_events
        WHERE published = false
        ORDER BY id
        LIMIT 100
        FOR UPDATE SKIP LOCKED
    `)
    if err != nil {
        log.WithError(err).Error("outbox publisher: select")
        return
    }
    defer rows.Close()

    var events []OutboxEvent
    for rows.Next() {
        var ev OutboxEvent
        if err := rows.Scan(&ev.ID, &ev.Type, &ev.Payload, &ev.CorrelationID); err != nil {
            log.WithError(err).Error("outbox publisher: scan")
            continue
        }
        events = append(events, ev)
    }

    for _, ev := range events {
        // Publish to Kafka (synchronous with retries)
        if err := s.kafka.Publish(ctx, ev.Type, ev.Payload, ev.CorrelationID); err != nil {
            log.WithError(err).WithField("outbox_id", ev.ID).Error("outbox publisher: kafka publish failed")
            // Skip marking this one as published; it will be retried.
            continue
        }
        // Mark as published
        if _, err := tx.ExecContext(ctx, `
            UPDATE outbox_events SET published = true WHERE id = ?
        `, ev.ID); err != nil {
            log.WithError(err).Error("outbox publisher: mark published failed")
            // Will be retried (idempotent if published twice).
        }
        outboxPublished.Inc()
    }

    if err := tx.Commit(); err != nil {
        log.WithError(err).Error("outbox publisher: commit")
    }
}
```

---

### 5. Structured Logging & Monitoring
Every log line includes `correlation_id` for cross‑service tracing. Metrics give real‑time visibility into duplicate detection.

**Key log events:**
- `"Duplicate request served from cache"` (INFO) – when an idempotency key is reused.
- `"Taking over stale processing record"` (WARN) – original job died, new attempt begins.
- `"CRITICAL: failed to finalize idempotency after successful payment"` (ERROR) – requires immediate on‑call attention.

**Prometheus metrics:**
- `checkout_idempotency_hits_total`: counts successful deduplications.
- `checkout_idempotency_processing_conflicts_total`: counts requests that found an active processing record (client retried too early).
- `checkout_outbox_published_total`: counts events successfully delivered to Kafka.

Alerts can be configured on a low ratio of `hits` vs total requests, or on any `processing_conflicts` spikes.

---

### 6. 24-Hour Retry Window Guarantee
- `payment_idempotency` retains terminal records (`succeeded`/`failed`) for **24 hours** via the cleanup job.
- Within that window, any retry with the same `idempotency_key` receives the exact same response (no provider call).
- After 24 hours, the key is eligible for deletion. A new request with a recycled key must be treated as fresh (the client must ensure keys are unique within the window).
- The cleanup job also drains stale `processing` records (>5 min), preventing permanent lock-up.

---

### 7. Summary of Idempotency Flow
1. Client sends `Idempotency-Key: <unique>` and `Correlation-Id: <trace>`.
2. Service tries to INSERT a `processing` record in MySQL.
   - **Success** → call payment provider.
   - **Duplicate** → read existing record.
     - Terminal → return stored response.
     - Processing (fresh) → return 409 Conflict, client retries later.
     - Processing (stale) → take over and proceed.
3. After payment, atomically UPDATE the record to terminal state and INSERT an outbox event.
4. Background publisher delivers the event to Kafka with at-least-once semantics.
5. Downstream consumers use the same `idempotency_key` for their own deduplication.

This design eliminates duplicate charges during provider failover, meets the 24‑hour idempotency window, and provides full traceability through correlation IDs and structured observability.

