import sys
import random
import io
import struct
import pickle
import _pickle


# ----------------------------------------------------------------------
# Import the test.fuzzhelper library.  If it is not available, a minimal
# mock is provided so the script can still be executed stand-alone for
# demonstration purposes.
# ----------------------------------------------------------------------
try:
    import test.fuzzhelper as fh
except ImportError:
    class _FuzzHelperMock:
        """Minimal stand-in for the test.fuzzhelper library."""
        @staticmethod
        def random_bool():
            return random.choice([True, False])

        @staticmethod
        def random_int(min_val=-100, max_val=100):
            return random.randint(min_val, max_val)

        @staticmethod
        def random_bytes(min_len=0, max_len=256):
            length = random.randint(min_len, max_len)
            return bytes(random.getrandbits(8) for _ in range(length))
    fh = _FuzzHelperMock()
    print("Warning: test.fuzzhelper not found; using built-in mock.",
          file=sys.stderr)


# ----------------------------------------------------------------------
# dir_func – modifies object attributes conditionally based on random
#            boolean values.
# ----------------------------------------------------------------------
def dir_func(obj):
    """Modify *obj*'s attributes conditionally using random booleans.

    For each candidate attribute (up to 10), a random boolean decides
    whether to set a new random value or to delete the attribute.
    """
    num_attrs = random.randint(0, 10)
    for i in range(num_attrs):
        attr_name = f"_fuzz_attr_{i}"
        if fh.random_bool():            # <-- conditional on a random boolean
            # Set a random attribute from a varied pool of values
            value = random.choice([
                0, 1, 3.14, "hello", b"world", None, True, False,
                [], {}, {1, 2}, (1, 2),
                io.BytesIO(b'test')
            ])
            try:
                setattr(obj, attr_name, value)
            except (AttributeError, TypeError):
                pass
        else:
            if hasattr(obj, attr_name):
                try:
                    delattr(obj, attr_name)
                except (AttributeError, TypeError):
                    pass


# ----------------------------------------------------------------------
# Helper class and generators for random fuzz inputs.
# ----------------------------------------------------------------------
class _FuzzObject:
    """Empty class whose instances can be modified by dir_func."""


def random_object():
    """Return a randomly generated object of various types."""
    category = random.randint(0, 10)
    try:
        if category == 0:
            return random.randint(-100, 100)
        elif category == 1:
            return random.uniform(-100.0, 100.0)
        elif category == 2:
            return "".join(random.choice("abcde")
                           for _ in range(random.randint(0, 10)))
        elif category == 3:
            return bytes(random.randint(0, 255)
                         for _ in range(random.randint(0, 10)))
        elif category == 4:
            return [random_object() for _ in range(random.randint(0, 5))]
        elif category == 5:
            return {random.randint(0, 10): random_object()
                    for _ in range(random.randint(0, 3))}
        elif category == 6:
            return tuple(random_object()
                         for _ in range(random.randint(0, 3)))
        elif category == 7:
            return set(random.randint(0, 100)
                       for _ in range(random.randint(0, 3)))
        else:
            obj = _FuzzObject()
            dir_func(obj)                 # apply our dir_func
            return obj
    except Exception:
        return None                       # fallback on any generation error


def random_bytes():
    """Return random bytes using fuzzhelper."""
    return fh.random_bytes(0, 200)


def random_file():
    """Return a file-like object (BytesIO or StringIO)."""
    if fh.random_bool():
        return io.BytesIO(random_bytes())
    else:
        return io.StringIO("some random text")


def random_bool():
    """Return a random boolean using fuzzhelper."""
    return fh.random_bool()


def random_int():
    """Return a random integer using fuzzhelper."""
    return fh.random_int(-100, 100)


# ----------------------------------------------------------------------
# Main test function – runs 9999 iterations of fuzz testing.
# ----------------------------------------------------------------------
def test():
    # Expected exceptions: any of these is considered a normal rejection
    # of invalid input by the _pickle module.
    expected_exceptions = (
        TypeError, ValueError, AttributeError, LookupError,
        pickle.PickleError, pickle.UnpicklingError,
        EOFError, MemoryError, RecursionError, OverflowError,
        io.UnsupportedOperation, OSError, ImportError, ModuleNotFoundError,
        struct.error, IndexError, KeyError,
    )

    for iteration in range(1, 10000):
        # Choose a _pickle function/class at random
        target = random.choice(['dumps', 'loads', 'dump', 'load',
                                'Pickler', 'Unpickler'])
        args = []
        kwargs = {}

        try:
            if target == 'dumps':
                obj = random_object()
                protocol = random.choice([None, random_int(),
                                          random.randint(-1, 5)])
                fix_imports = random_bool()
                args = [obj]
                kwargs = {'protocol': protocol, 'fix_imports': fix_imports}
                _pickle.dumps(*args, **kwargs)

            elif target == 'loads':
                data = random_bytes()
                fix_imports = random_bool()
                args = [data]
                kwargs = {'fix_imports': fix_imports}
                _pickle.loads(*args, **kwargs)

            elif target == 'dump':
                obj = random_object()
                f = random_file()
                protocol = random.choice([None, random_int(),
                                          random.randint(-1, 5)])
                fix_imports = random_bool()
                if not hasattr(f, 'write'):
                    raise TypeError("File object is not writable")
                _pickle.dump(obj, f, protocol=protocol,
                             fix_imports=fix_imports)

            elif target == 'load':
                f = random_file()
                fix_imports = random_bool()
                if not hasattr(f, 'read'):
                    raise TypeError("File object is not readable")
                if hasattr(f, 'seek'):
                    f.seek(0)
                _pickle.load(f, fix_imports=fix_imports)

            elif target == 'Pickler':
                f = random_file()
                protocol = random.choice([None, random_int(),
                                          random.randint(-1, 5)])
                fix_imports = random_bool()
                if not hasattr(f, 'write'):
                    raise TypeError("File object is not writable")
                pickler = _pickle.Pickler(f, protocol=protocol,
                                          fix_imports=fix_imports)
                obj = random_object()
                pickler.dump(obj)

            elif target == 'Unpickler':
                f = random_file()
                fix_imports = random_bool()
                if not hasattr(f, 'read'):
                    raise TypeError("File object is not readable")
                if hasattr(f, 'seek'):
                    f.seek(0)
                unpickler = _pickle.Unpickler(f, fix_imports=fix_imports)
                unpickler.load()

        except expected_exceptions:
            # Expected exception – the input was handled gracefully.
            pass
        except Exception as exc:
            # Unexpected exception – print diagnostics and fail.
            print(f"\nFAIL: Iteration {iteration} - "
                  f"Unexpected {type(exc).__name__}: {exc}")
            print(f"  target: {target}, args: {args!r}, kwargs: {kwargs!r}")
            raise

        if iteration % 1000 == 0:
            print(f"Progress: {iteration}/9999 iterations completed.",
                  file=sys.stderr)

    print("\nSUCCESS: All 9999 fuzz test iterations completed.")


# ----------------------------------------------------------------------
# Run the test loop when the script is executed directly.
# ----------------------------------------------------------------------
if __name__ == '__main__':
    test()
```

