 use std::collections::HashMap;

 pub trait TransformStrategy {
 fn transform(&self, c: char, context: &mut Context) -> char;
 }

 struct UpperCaseStrategy;
 impl TransformStrategy for UpperCaseStrategy {
 fn transform(&self, c: char, _context: &mut Context) -> char {
 c.to_ascii_uppercase()
 }
 }

 struct LowerCaseStrategy;
 impl TransformStrategy for LowerCaseStrategy {
 fn transform(&self, c: char, _context: &mut Context) -> char {
 c.to_ascii_lowercase()
 }
 }

 struct ToggleCaseStrategy;
 impl TransformStrategy for ToggleCaseStrategy {
 fn transform(&self, c: char, context: &mut Context) -> char {
 if context.toggle {
 context.toggle = false;
 c.to_ascii_uppercase()
 } else {
 context.toggle = true;
 c.to_ascii_lowercase()
 }
 }
 }

 struct Context {
 toggle: bool,
 cache: HashMap<char, char>,
 }

 struct Processor<'a> {
 chars: &'a [char],
 index: usize,
 result: String,
 strategies: Vec<Box<dyn TransformStrategy + 'a>>,
 context: Context,
 }

 impl<'a> Processor<'a> {
 fn new(chars: &'a [char]) -> Self {
 let strategies: Vec<Box<dyn TransformStrategy + 'a>> = vec![
 Box::new(UpperCaseStrategy),
 Box::new(LowerCaseStrategy),
 Box::new(ToggleCaseStrategy),
 ];
 Self {
 chars,
 index: 0,
 result: String::with_capacity(chars.len()),
 strategies,
 context: Context {
 toggle: false,
 cache: HashMap::new(),
 },
 }
 }

 fn process(&mut self) -> String {
 if self.index < self.chars.len() {
 let c = self.chars[self.index];
 let transformed = if let Some(&cached) = self.context.cache.get(&c) {
 cached
 } else {
 let strategy = &self.strategies[self.index % self.strategies.len()];
 let t = strategy.transform(c, &mut self.context);
 self.context.cache.insert(c, t);
 t
 };
 self.result.push(transformed);
 self.index += 1;
 self.process()
 } else {
 self.result.clone()
 }
 }
 }

 fn recursive_helper<'a>(processor: &mut Processor<'a>) -> String {
 processor.process()
 }

 let chars: Vec<char> = a.chars().collect();
 let mut processor = Processor::new(&chars);
 recursive_helper(&mut processor)
}
