#### 2.2. Ephemeral Staging Module

The pipeline invokes this module for each commit, passing the commit SHA and image tag.

```hcl
# modules/staging-env/main.tf

variable "commit_sha" {}
variable "image_tag" {}
variable "app_name" {}
variable "vpc_id" {}
variable "private_subnets" { type = list(string) }
variable "ecs_cluster_id" {}
variable "ecs_execution_role_arn" {}
variable "ecs_task_role_arn" {}
variable "ecs_sg_id" {}
variable "staging_alb_listener_arn" {}
variable "staging_domain" {}
variable "hosted_zone_id" {}
variable "db_secret_arn" {}
variable "log_group_name" {}

locals {
  subdomain = "${var.commit_sha}.${var.staging_domain}"  # e.g., abc123.staging.example.com
  tg_name   = "${var.app_name}-${substr(var.commit_sha, 0, 8)}"
}

resource "aws_ecs_task_definition" "staging" {
  family                   = "${var.app_name}-staging-${var.commit_sha}"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = 256
  memory                   = 512
  execution_role_arn       = var.ecs_execution_role_arn
  task_role_arn            = var.ecs_task_role_arn
  container_definitions    = jsonencode([
    {
      name  = var.app_name
      image = "${data.aws_ecr_repository.app.repository_url}:${var.image_tag}"
      portMappings = [{ containerPort = 80 }]
      secrets = [
        { name = "DB_PASSWORD", valueFrom = var.db_secret_arn }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = var.log_group_name
          awslogs-region        = var.aws_region
          awslogs-stream-prefix = "staging-${var.commit_sha}"
        }
      }
      healthCheck = {
        command     = ["CMD-SHELL", "curl -f http://localhost/health || exit 1"]
        interval    = 10
        timeout     = 5
        retries     = 3
        startPeriod = 30
      }
    }
  ])
}

resource "aws_lb_target_group" "staging" {
  name        = local.tg_name
  port        = 80
  protocol    = "HTTP"
  vpc_id      = var.vpc_id
  target_type = "ip"
  health_check {
    path                = "/health"
    interval            = 10
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }
}

resource "aws_lb_listener_rule" "staging" {
  listener_arn = var.staging_alb_listener_arn
  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.staging.arn
  }
  condition {
    host_header { values = [local.subdomain] }
  }
}

resource "aws_ecs_service" "staging" {
  name            = "${var.app_name}-staging-${var.commit_sha}"
  cluster         = var.ecs_cluster_id
  task_definition = aws_ecs_task_definition.staging.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = var.private_subnets
    security_groups  = [var.ecs_sg_id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.staging.arn
    container_name   = var.app_name
    container_port   = 80
  }

  lifecycle {
    create_before_destroy = true
  }
}

# Optional DNS record (using Route53)
resource "aws_route53_record" "staging" {
  zone_id = var.hosted_zone_id
  name    = local.subdomain
  type    = "CNAME"
  ttl     = 60
  records = [var.staging_alb_dns_name]
}

output "url" {
  value = "https://${local.subdomain}"
}

data "aws_ecr_repository" "app" {
  name = var.app_name
}
