### 3. CI/CD Pipeline (GitHub Actions Workflow)

The `.github/workflows/cd.yml` file orchestrates the entire process.

```yaml
name: CI/CD Pipeline (main)

on:
  push:
    branches: [ main ]

env:
  AWS_REGION: us-east-1
  APP_NAME: myapp
  ECR_REPO: myapp
  STAGING_DOMAIN: staging.example.com
  STATE_BUCKET: myapp-terraform-state

concurrency:
  group: production-deploy
  cancel-in-progress: false

jobs:
  # ── Stage 1: Build, unit tests, push to ECR ─────────────
  build-and-test:
    runs-on: ubuntu-latest
    outputs:
      image_tag: ${{ github.sha }}
      ecr_registry: ${{ steps.ecr-login.outputs.registry }}
    steps:
      - uses: actions/checkout@v3

      - name: Configure AWS credentials via OIDC
        uses: aws-actions/configure-aws-credentials@v2
        with:
          role-to-assume: arn:aws:iam::123456789:role/github-actions-oidc
          aws-region: ${{ env.AWS_REGION }}

      - name: Login to Amazon ECR
        id: ecr-login
        uses: aws-actions/amazon-ecr-login@v1

      - name: Set up Docker Buildx
        uses: docker/setup-buildx-action@v2

      - name: Build and push container image
        uses: docker/build-push-action@v4
        with:
          context: .
          push: true
          tags: |
            ${{ steps.ecr-login.outputs.registry }}/${{ env.ECR_REPO }}:${{ github.sha }}
            ${{ steps.ecr-login.outputs.registry }}/${{ env.ECR_REPO }}:latest
          cache-from: type=gha
          cache-to: type=gha,mode=max

      - name: Run unit tests inside container
        run: |
          docker run --rm \
            -e TEST_MODE=unit \
            ${{ steps.ecr-login.outputs.registry }}/${{ env.ECR_REPO }}:${{ github.sha }} \
            pytest tests/unit -v

      - name: Publish unit test results
        if: always()
        uses: actions/upload-artifact@v3
        with:
          name: unit-test-results
          path: test-results/

  # ── Stage 2: Ephemeral staging environment & integration tests ──
  deploy-staging:
    needs: build-and-test
    runs-on: ubuntu-latest
    environment:
      name: staging/${{ github.sha }}
      url: ${{ steps.staging-url.outputs.STAGING_URL }}
    steps:
      - uses: actions/checkout@v3

      - uses: aws-actions/configure-aws-credentials@v2
        with:
          role-to-assume: arn:aws:iam::123456789:role/github-actions-oidc
          aws-region: ${{ env.AWS_REGION }}

      - uses: hashicorp/setup-terraform@v2
        with:
          terraform_version: 1.5.0

      - name: Generate Terraform for ephemeral staging
        run: |
          mkdir -p tf-staging-${{ github.sha }}
          cat > tf-staging-${{ github.sha }}/main.tf <<EOF
          module "staging" {
            source = "./modules/staging-env"
            commit_sha               = "${{ github.sha }}"
            image_tag                = "${{ github.sha }}"
            app_name                 = "${{ env.APP_NAME }}"
            vpc_id                   = var.vpc_id
            private_subnets          = var.private_subnets
            ecs_cluster_id           = var.ecs_cluster_id
            ecs_execution_role_arn   = var.ecs_execution_role_arn
            ecs_task_role_arn        = var.ecs_task_role_arn
            ecs_sg_id                = var.ecs_sg_id
            staging_alb_listener_arn = var.staging_alb_listener_arn
            staging_domain           = "${{ env.STAGING_DOMAIN }}"
            hosted_zone_id           = var.hosted_zone_id
            db_secret_arn            = var.db_secret_arn
            log_group_name           = var.log_group_name
            staging_alb_dns_name     = var.staging_alb_dns_name
            aws_region               = "${{ env.AWS_REGION }}"
          }
          EOF
          # Copy a variables file or pass them via CLI
          cp tf-staging-vars.tfvars tf-staging-${{ github.sha }}/terraform.tfvars

      - name: Terraform Init (ephemeral state)
        working-directory: tf-staging-${{ github.sha }}
        run: |
          terraform init \
            -backend-config="bucket=${{ env.STATE_BUCKET }}" \
            -backend-config="key=staging-${{ github.sha }}/terraform.tfstate" \
            -backend-config="region=${{ env.AWS_REGION }}"

      - name: Terraform Apply
        id: apply
        working-directory: tf-staging-${{ github.sha }}
        run: |
          terraform apply -auto-approve -var-file=terraform.tfvars
          terraform output -raw url > /tmp/staging_url

      - name: Wait for ECS service stability
        run: |
          aws ecs wait services-stable \
            --cluster ${{ env.APP_NAME }}-cluster \
            --services ${{ env.APP_NAME }}-staging-${{ github.sha }}

      - uses: actions/upload-artifact@v3
        with:
          name: staging-url
          path: /tmp/staging_url

      - name: Run integration tests
        run: |
          STAGING_URL=$(cat /tmp/staging_url)
          docker run --rm \
            -e TEST_MODE=integration \
            -e BASE_URL="$STAGING_URL" \
            ${{ needs.build-and-test.outputs.ecr_registry }}/${{ env.ECR_REPO }}:${{ github.sha }} \
            pytest tests/integration -v

      - name: Publish integration test results
        if: always()
        uses: actions/upload-artifact@v3
        with:
          name: integration-test-results
          path: test-results/

      - name: Cleanup on failure
        if: failure()
        working-directory: tf-staging-${{ github.sha }}
        run: terraform destroy -auto-approve -var-file=terraform.tfvars

  # ── Stage 3: Production Blue/Green deployment ──────────
  deploy-production:
    needs: deploy-staging
    if: success()
    runs-on: ubuntu-latest
    environment:
      name: production
      url: https://prod.example.com
    steps:
      - uses: actions/checkout@v3

      - uses: aws-actions/configure-aws-credentials@v2
        with:
          role-to-assume: arn:aws:iam::123456789:role/github-actions-oidc
          aws-region: ${{ env.AWS_REGION }}

      - name: Register new ECS task definition revision
        id: task-def
        run: |
          # Fetch current production task definition
          TASK_DEF=$(aws ecs describe-task-definition \
            --task-definition ${{ env.APP_NAME }}-prod \
            --query 'taskDefinition')

          # Update the image in the first container
          NEW_IMAGE="${{ steps.ecr-login.outputs.registry }}/${{ env.ECR_REPO }}:${{ github.sha }}"
          UPDATED_DEF=$(echo "$TASK_DEF" | jq \
            --arg IMAGE "$NEW_IMAGE" \
            '.containerDefinitions[0].image = $IMAGE')

          # Register new revision
          NEW_ARN=$(aws ecs register-task-definition \
            --cli-input-json "$UPDATED_DEF" \
            --query 'taskDefinition.taskDefinitionArn' --output text)
          echo "NEW_TASK_DEF_ARN=$NEW_ARN" >> $GITHUB_OUTPUT

      - name: Trigger CodeDeploy blue/green deployment
        id: deploy
        run: |
          DEPLOYMENT_ID=$(aws deploy create-deployment \
            --application-name ${{ env.APP_NAME }} \
            --deployment-group-name ${{ env.APP_NAME }}-prod-dg \
            --task-definition ${{ steps.task-def.outputs.NEW_TASK_DEF_ARN }} \
            --file-exists-behavior OVERWRITE \
            --description "Deploy commit ${{ github.sha }}" \
            --query 'deploymentId' --output text)
          echo "DEPLOYMENT_ID=$DEPLOYMENT_ID" >> $GITHUB_OUTPUT

          # Wait for deployment to succeed / timeout
          aws deploy wait deployment-successful --deployment-id $DEPLOYMENT_ID

      - name: Run smoke tests against production
        run: |
          docker run --rm \
            -e TEST_MODE=smoke \
            -e BASE_URL="https://prod.example.com" \
            ${{ needs.build-and-test.outputs.ecr_registry }}/${{ env.ECR_REPO }}:${{ github.sha }} \
            pytest tests/smoke -v

      - name: Destroy ephemeral staging environment (always)
        if: always()
        working-directory: tf-staging-${{ github.sha }}
        run: terraform destroy -auto-approve -var-file=terraform.tfvars

      - name: Notify success/failure to Slack
        if: always()
        uses: slackapi/slack-github-action@v1.23.0
        with:
          payload: |
            {
              "text": "Deployment of `${{ github.sha }}` to production: *${{ job.status }}*.\nDeployment ID: ${{ steps.deploy.outputs.DEPLOYMENT_ID }}\nLogs: ${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}"
            }
        env:
          SLACK_WEBHOOK_URL: ${{ secrets.SLACK_WEBHOOK }}
```

