class TransformStrategy {
 execute(array) {
 return this.alternateCase(array, 0).join('');
 }

 alternateCase(array, index) {
 if (index >= array.length) {
 return [];
 }
 const char = index % 2 === 0 ? array[index].toUpperCase() : array[index].toLowerCase();
 return [char].concat(this.alternateCase(array, index + 1));
 }
}

class ReverseStrategy {
 execute(str) {
 return this.reverseRecursive(str, str.length - 1, '');
 }

 reverseRecursive(str, index, accumulator) {
 if (index < 0) {
 return accumulator;
 }
 return this.reverseRecursive(str, index - 1, accumulator + str[index]);
 }
}

