 this.memoizer = memoizer;
 this.transformStrategy = memoizer.memoize(transformStrategy.execute.bind(transformStrategy));
 this.reverseStrategy = memoizer.memoize(reverseStrategy.execute.bind(reverseStrategy));
 }

 process() {
