## 2. TypeScript Implementation (SQS Worker with Idempotency)

This code uses `pg` for PostgreSQL, `winston` for structured logging, and assumes the SQS message body is a JSON webhook event.

### 2.1 Idempotency Handler

```typescript
// src/handlers/processWebhookEvent.ts
import { PoolClient } from 'pg';
import { Logger } from 'winston';

export interface WebhookEvent {
  event_id: string;      // payment provider unique ID
  invoice_id: string;    // target invoice ID (UUID)
  // ... other fields
}

export interface ProcessingResult {
  processed: boolean;
  duplicate: boolean;
  invoiceUpdated: boolean;
}

/**
 * Core logic – must run inside a database transaction.
 * Returns detailed result for logging/audit.
 */
export async function processWebhookEvent(
  db: PoolClient,
  event: WebhookEvent,
  correlationId: string,
  logger: Logger,
): Promise<ProcessingResult> {
  const { event_id, invoice_id } = event;

  // 1. Insert idempotency key, skip if already present
  const insertResult = await db.query(
    `INSERT INTO processed_webhook_events (idempotency_key, invoice_id, correlation_id)
     VALUES ($1, $2, $3)
     ON CONFLICT (idempotency_key) DO NOTHING
     RETURNING idempotency_key`,
    [event_id, invoice_id, correlationId],
  );

  if (insertResult.rows.length === 0) {
    logger.info('Duplicate event ignored', { event_id, invoice_id, correlationId });
    return { processed: false, duplicate: true, invoiceUpdated: false };
  }

  // 2. Event is new – conditionally update the invoice
  const updateResult = await db.query(
    `UPDATE invoices
        SET status = 'paid',
            payment_event_id = $1,
            updated_at = NOW()
      WHERE id = $2 AND status = 'unpaid'`,
    [event_id, invoice_id],
  );

  const invoiceUpdated = updateResult.rowCount > 0;
  if (!invoiceUpdated) {
    logger.warn('Invoice update skipped (already paid or missing)', {
      event_id,
      invoice_id,
      correlationId,
    });
  } else {
    logger.info('Invoice marked paid', { event_id, invoice_id, correlationId });
  }

  return { processed: true, duplicate: false, invoiceUpdated };
}
```

### 2.2 SQS Message Handler (Entry Point)

```typescript
// src/handlers/sqsHandler.ts
import { Pool } from 'pg';
import { Logger } from 'winston';
import { v4 as uuidv4 } from 'uuid';
import { processWebhookEvent, WebhookEvent } from './processWebhookEvent';

/**
 * Wraps the idempotent processing with transaction management,
 * correlation ID extraction/generation, and error handling.
 */
export async function handleSQSMessage(
  messageBody: string,
  messageAttributes: Record<string, any> = {},
  dbPool: Pool,
  logger: Logger,
): Promise<void> {
  // Extract or create correlation ID for tracing
  const correlationId =
    messageAttributes?.correlationId?.StringValue ||
    process.env.CORRELATION_ID ||   // if set by upstream service
    uuidv4();

  const ctxLogger = logger.child({ correlationId });
  let client: PoolClient | undefined;

  try {
    const event: WebhookEvent = JSON.parse(messageBody);
    if (!event.event_id || !event.invoice_id) {
      throw new Error(
        `Invalid webhook event: missing event_id or invoice_id. CorrelationId: ${correlationId}`,
      );
    }

    client = await dbPool.connect();
    await client.query('BEGIN');

    const result = await processWebhookEvent(client, event, correlationId, ctxLogger);
    await client.query('COMMIT');

    ctxLogger.info('Message processed', { result, event_id: event.event_id });
  } catch (error: any) {
    if (client) {
      await client.query('ROLLBACK').catch((e) =>
        ctxLogger.error('Rollback failed', { error: e }),
      );
    }
    ctxLogger.error(`Processing failed: ${error.message}`, { error });
    // Re-throw to return error to SQS (message will be retried after visibility timeout)
    throw new Error(`Processing failed. CorrelationId: ${correlationId}`);
  } finally {
    client?.release();
  }
}
```

### 2.3 SQS Consumer Bootstrap (for completeness)

```typescript
// src/worker.ts
import { SQSClient, ReceiveMessageCommand, DeleteMessageCommand } from '@aws-sdk/client-sqs';
import { Pool } from 'pg';
import { createLogger } from 'winston';
import { handleSQSMessage } from './handlers/sqsHandler';

const sqs = new SQSClient({ region: 'us-east-1' });
const dbPool = new Pool({ /* connection config */ });
const logger = createLogger({ /* transports */ });

const QUEUE_URL = process.env.SQS_QUEUE_URL!;

async function poll() {
  const command = new ReceiveMessageCommand({
    QueueUrl: QUEUE_URL,
    MaxNumberOfMessages: 10,
    WaitTimeSeconds: 20,
  });

  const response = await sqs.send(command);
  const messages = response.Messages ?? [];

  const results = await Promise.allSettled(
    messages.map(async (msg) => {
      try {
        await handleSQSMessage(
          msg.Body!,
          msg.MessageAttributes,
          dbPool,
          logger,
        );
        // Success – delete from queue
        await sqs.send(new DeleteMessageCommand({
          QueueUrl: QUEUE_URL,
          ReceiptHandle: msg.ReceiptHandle!,
        }));
      } catch {
        // Error already logged; SQS will retry after visibility timeout
      }
    }),
  );

  // Continue polling
  setImmediate(poll);
}

poll();
```

