class Solution:
    def valid_word_chain(self, words: List[str]) -> bool:
        # An empty list or a list with one word is trivially a valid chain.
        if len(words) <= 1:
            return True

        # Check each adjacent pair: last char of current must equal first char of next.
        for i in range(len(words) - 1):
            # If either word is empty, the chain is invalid (no characters to compare).
            if not words[i] or not words[i+1]:
                return False
            if words[i][-1] != words[i+1][0]:
