            outline: 3px solid var(--color-accent);
            outline-offset: 2px;
        }

        /* ========== TYPOGRAPHY ========== */
        h1,
        h2,
        h3,
        h4 {
            line-height: 1.15;
            font-weight: 700;
            letter-spacing: -0.02em;
        }
        h1 {
            font-size: clamp(2.8rem, 7vw, 5.5rem);
            letter-spacing: -0.03em;
        }
        h2 {
            font-size: clamp(1.8rem, 3.2vw, 2.6rem);
        }
        h3 {
            font-size: clamp(1.2rem, 1.8vw, 1.45rem);
            font-weight: 600;
        }
        .text-mono {
            font-family: var(--font-mono);
            font-size: 0.8rem;
            letter-spacing: 0.06em;
            text-transform: uppercase;
            color: var(--color-text-secondary);
        }
        .text-accent {
            color: var(--color-accent);
        }

        /* ========== LAYOUT ========== */
        .container {
            width: 100%;
            max-width: var(--max-width);
            margin-inline: auto;
            padding-inline: clamp(16px, 3vw, 32px);
        }
        section {
            padding-block: clamp(60px, 10vh, 100px);
        }

        /* ========== HEADER ========== */
        .header {
            position: sticky;
            top: 0;
            z-index: 100;
            height: var(--header-height);
            display: flex;
            align-items: center;
            background: transparent;
            transition: background var(--transition-smooth), box-shadow var(--transition-smooth);
            will-change: background, box-shadow;
        }
        .header.scrolled {
            background: rgba(252, 252, 250, 0.88);
            backdrop-filter: blur(16px);
            -webkit-backdrop-filter: blur(16px);
            box-shadow: var(--shadow-header);
        }
        .header__inner {
            display: flex;
            align-items: center;
            justify-content: space-between;
            width: 100%;
            max-width: var(--max-width);
            margin-inline: auto;
            padding-inline: clamp(16px, 3vw, 32px);
        }
        .header__logo {
            font-size: 1.3rem;
            font-weight: 800;
            letter-spacing: -0.02em;
            color: var(--color-dark);
            text-decoration: none;
            z-index: 5;
        }
        .header__logo span {
            color: var(--color-accent);
        }

        /* Desktop Navigation */
        .nav-desktop {
            display: flex;
            align-items: center;
            gap: 32px;
            list-style: none;
        }
        .nav-desktop a {
            text-decoration: none;
            color: var(--color-text);
            font-weight: 500;
            font-size: 0.95rem;
            transition: color var(--transition-fast);
            position: relative;
        }
        .nav-desktop a::after {
            content: '';
            position: absolute;
            bottom: -4px;
            left: 0;
            width: 0;
            height: 2px;
            background: var(--color-accent);
            transition: width var(--transition-smooth);
            border-radius: 2px;
        }
        .nav-desktop a:hover,
        .nav-desktop a:focus-visible {
            color: var(--color-accent);
        }
        .nav-desktop a:hover::after,
        .nav-desktop a:focus-visible::after {
            width: 100%;
        }

        /* Hamburger Button */
        .hamburger {
            display: none;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            gap: 5px;
            width: 40px;
            height: 40px;
            background: transparent;
            border: none;
            cursor: pointer;
            z-index: 5;
            padding: 6px;
            border-radius: var(--radius-sm);
            transition: background var(--transition-fast);
        }
        .hamburger:hover {
            background: var(--color-surface);
        }
        .hamburger:focus-visible {
            outline: 3px solid var(--color-accent);
            outline-offset: 2px;
        }
        .hamburger__line {
            display: block;
            width: 22px;
            height: 2px;
            background: var(--color-dark);
            border-radius: 2px;
            transition: transform var(--transition-smooth), opacity var(--transition-fast);
        }
        /* Animate hamburger when menu is open */
        .menu-open .hamburger__line:nth-child(1) {
            transform: translateY(7px) rotate(45deg);
        }
        .menu-open .hamburger__line:nth-child(2) {
            opacity: 0;
            transform: scaleX(0);
        }
        .menu-open .hamburger__line:nth-child(3) {
            transform: translateY(-7px) rotate(-45deg);
        }

        /* ========== SIDEBAR OVERLAY ========== */
        .sidebar-overlay {
            position: fixed;
            inset: 0;
            z-index: 150;
            background: var(--color-overlay);
            opacity: 0;
            pointer-events: none;
            transition: opacity var(--transition-smooth);
            will-change: opacity;
        }
        .menu-open .sidebar-overlay {
            opacity: 1;
            pointer-events: auto;
        }

        /* ========== OFF-CANVAS SIDEBAR ========== */
        .sidebar {
            position: fixed;
            top: 0;
            right: 0;
            z-index: 200;
            width: min(var(--sidebar-width), 85vw);
            height: 100vh;
            height: 100dvh;
            background: var(--color-dark);
            color: #fff;
            display: flex;
            flex-direction: column;
            padding: 28px 24px;
            transform: translateX(100%);
            transition: transform var(--transition-spring);
            will-change: transform;
            overflow-y: auto;
        }
        .menu-open .sidebar {
            transform: translateX(0);
        }
        .sidebar__close {
            align-self: flex-end;
            width: 40px;
            height: 40px;
            background: rgba(255, 255, 255, 0.1);
            border: none;
            border-radius: var(--radius-full);
            color: #fff;
            font-size: 1.2rem;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: background var(--transition-fast);
            flex-shrink: 0;
        }
        .sidebar__close:hover {
            background: rgba(255, 255, 255, 0.2);
        }
        .sidebar__close:focus-visible {
            outline: 3px solid var(--color-accent);
            outline-offset: 2px;
        }
        .sidebar__nav {
            list-style: none;
            margin-top: 40px;
            display: flex;
            flex-direction: column;
            gap: 8px;
        }
        .sidebar__nav a {
            display: block;
            color: #ccc;
            text-decoration: none;
            font-size: 1.2rem;
            font-weight: 500;
            padding: 12px 16px;
            border-radius: var(--radius-sm);
            transition: all var(--transition-fast);
        }
        .sidebar__nav a:hover,
        .sidebar__nav a:focus-visible {
            color: #fff;
            background: rgba(255, 255, 255, 0.08);
        }
        .sidebar__nav a:focus-visible {
            outline: 2px solid var(--color-accent);
            outline-offset: -2px;
        }
        .sidebar__cta {
            margin-top: auto;
            padding: 14px 20px;
            background: var(--color-accent);
            color: #fff;
            border: none;
            border-radius: var(--radius-md);
            font-weight: 600;
            font-size: 1rem;
            cursor: pointer;
            text-align: center;
            text-decoration: none;
            transition: background var(--transition-fast);
        }
        .sidebar__cta:hover {
            background: var(--color-accent-hover);
        }

        /* ========== HERO SECTION ========== */
        .hero {
            position: relative;
            padding-block: clamp(80px, 14vh, 140px) clamp(60px, 8vh, 80px);
            overflow: hidden;
            text-align: center;
        }
        /* Decorative background orbs */
        .hero::before,
        .hero::after {
            content: '';
            position: absolute;
            border-radius: 50%;
            pointer-events: none;
            z-index: 0;
        }
        .hero::before {
            top: -120px;
            right: -80px;
            width: 550px;
            height: 550px;
            background: radial-gradient(circle at center, rgba(232, 81, 58, 0.10) 0%, transparent 70%);
        }
        .hero::after {
            bottom: -80px;
            left: -60px;
            width: 350px;
            height: 350px;
            background: radial-gradient(circle at center, rgba(60, 120, 200, 0.07) 0%, transparent 70%);
        }
        .hero__content {
            position: relative;
            z-index: 1;
            max-width: 800px;
            margin-inline: auto;
        }
        .hero__label {
            display: inline-block;
            font-family: var(--font-mono);
            font-size: 0.8rem;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            color: var(--color-accent);
            margin-bottom: 16px;
            font-weight: 600;
        }
        .hero__title {
            margin-bottom: 20px;
        }
        .hero__subtitle {
            font-size: clamp(1rem, 2vw, 1.3rem);
            color: var(--color-text-secondary);
            max-width: 540px;
            margin-inline: auto;
            margin-bottom: 36px;
            line-height: 1.5;
        }
        .hero__cta {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 16px 32px;
            background: var(--color-accent);
            color: #fff;
            font-weight: 600;
            font-size: 1rem;
            text-decoration: none;
            border-radius: var(--radius-md);
            transition: background var(--transition-fast), transform var(--transition-fast);
            will-change: transform;
        }
        .hero__cta:hover {
            background: var(--color-accent-hover);
            transform: translateY(-2px);
        }
        .hero__cta:focus-visible {
            outline: 3px solid var(--color-accent);
            outline-offset: 3px;
        }
        .hero__cta-arrow {
            transition: transform var(--transition-fast);
        }
        .hero__cta:hover .hero__cta-arrow {
            transform: translateX(3px);
        }

        /* ========== ABOUT SECTION ========== */
        .about__grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
            gap: 32px;
            margin-top: 40px;
        }
        .about-card {
            padding: 28px 24px;
            background: var(--color-white);
            border: 1px solid var(--color-border);
            border-radius: var(--radius-lg);
            transition: box-shadow var(--transition-smooth);
        }
        .about-card:hover {
            box-shadow: var(--shadow-card-hover);
        }
        .about-card__icon {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 44px;
            height: 44px;
            border-radius: var(--radius-md);
            background: var(--color-accent-subtle);
            font-size: 1.2rem;
            margin-bottom: 14px;
        }
        .about-card h3 {
            margin-bottom: 8px;
        }
        .about-card p {
            color: var(--color-text-secondary);
            font-size: 0.95rem;
        }

        /* ========== TICKETS SECTION ========== */
        .tickets__grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 24px;
            margin-top: 40px;
        }
        .ticket-card {
            background: var(--color-white);
            border: 2px solid var(--color-border);
            border-radius: var(--radius-lg);
            padding: 28px 24px;
            transition: all var(--transition-smooth);
            position: relative;
            overflow: hidden;
            display: flex;
            flex-direction: column;
        }
        .ticket-card:hover {
            box-shadow: var(--shadow-card-hover);
            border-color: #d5d5d3;
        }
        /* Selected state: accent left border indicator */
        .ticket-card--selected {
            border-color: var(--color-accent);
            border-left-width: 4px;
            border-left-color: var(--color-accent);
            box-shadow: var(--shadow-card);
        }
        .ticket-card__badge {
            display: inline-block;
            font-family: var(--font-mono);
            font-size: 0.7rem;
            letter-spacing: 0.07em;
            text-transform: uppercase;
            background: var(--color-accent-subtle);
            color: var(--color-accent);
            padding: 4px 10px;
            border-radius: var(--radius-sm);
            margin-bottom: 16px;
            font-weight: 700;
            align-self: flex-start;
        }
        .ticket-card__name {
            font-size: 1.3rem;
            font-weight: 700;
            margin-bottom: 6px;
        }
        .ticket-card__price {
            font-size: 2.2rem;
            font-weight: 800;
            letter-spacing: -0.02em;
            margin-bottom: 4px;
        }
        .ticket-card__price span {
            font-size: 0.9rem;
            font-weight: 500;
            color: var(--color-text-secondary);
        }
        .ticket-card__desc {
            color: var(--color-text-secondary);
            font-size: 0.9rem;
            margin-bottom: 20px;
            flex-grow: 1;
        }
        .ticket-card__features {
            list-style: none;
            margin-bottom: 20px;
            font-size: 0.9rem;
            color: var(--color-text-secondary);
        }
        .ticket-card__features li {
            padding: 4px 0;
            padding-left: 20px;
            position: relative;
        }
        .ticket-card__features li::before {
            content: '✓';
            position: absolute;
            left: 0;
            color: var(--color-accent);
            font-weight: 700;
        }

        /* Quantity selector */
        .quantity-selector {
            display: flex;
            align-items: center;
            gap: 8px;
            margin-top: auto;
        }
        .quantity-btn {
            width: 34px;
            height: 34px;
            border-radius: var(--radius-full);
            border: 2px solid var(--color-border);
            background: var(--color-white);
            cursor: pointer;
            font-size: 1rem;
            font-weight: 600;
            color: var(--color-text);
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all var(--transition-fast);
            flex-shrink: 0;
        }
        .quantity-btn:hover:not(:disabled) {
            border-color: var(--color-accent);
            color: var(--color-accent);
            background: var(--color-accent-subtle);
        }
        .quantity-btn:active:not(:disabled) {
            transform: scale(0.94);
        }
        .quantity-btn:disabled {
            opacity: 0.35;
            cursor: not-allowed;
            pointer-events: none;
        }
        .quantity-btn:focus-visible {
            outline: 3px solid var(--color-accent);
            outline-offset: 2px;
        }
        .quantity-display {
            width: 36px;
            text-align: center;
            font-weight: 700;
            font-size: 1.1rem;
            user-select: none;
        }
        .quantity-label {
            font-size: 0.8rem;
            color: var(--color-text-secondary);
            margin-left: 4px;
        }

        /* ========== CART SUMMARY BAR ========== */
        .cart-summary {
            position: fixed;
            bottom: 0;
            left: 0;
            right: 0;
            z-index: 50;
            background: rgba(252, 252, 250, 0.94);
            backdrop-filter: blur(16px);
            -webkit-backdrop-filter: blur(16px);
            border-top: 1px solid var(--color-border);
            box-shadow: var(--shadow-bar);
            padding: 16px 24px;
            transform: translateY(100%);
            opacity: 0;
            transition: transform var(--transition-spring), opacity var(--transition-smooth);
            will-change: transform, opacity;
            pointer-events: none;
        }
        .cart-summary--visible {
            transform: translateY(0);
            opacity: 1;
            pointer-events: auto;
        }
        .cart-summary__inner {
            max-width: var(--max-width);
            margin-inline: auto;
            display: flex;
            align-items: center;
            justify-content: space-between;
            flex-wrap: wrap;
            gap: 12px;
        }
        .cart-summary__info {
            font-weight: 600;
            font-size: 0.95rem;
        }
        .cart-summary__total {
            font-weight: 800;
            font-size: 1.2rem;
            color: var(--color-accent);
        }
        .cart-summary__btn {
            padding: 12px 28px;
            background: var(--color-accent);
            color: #fff;
            font-weight: 600;
            font-size: 0.95rem;
            border: none;
            border-radius: var(--radius-md);
            cursor: pointer;
            transition: background var(--transition-fast), transform var(--transition-fast);
            white-space: nowrap;
        }
        .cart-summary__btn:hover {
            background: var(--color-accent-hover);
            transform: translateY(-1px);
        }
        .cart-summary__btn:focus-visible {
            outline: 3px solid var(--color-accent);
            outline-offset: 3px;
        }
        .cart-summary__btn:disabled {
            opacity: 0.5;
            cursor: not-allowed;
            pointer-events: none;
        }

        /* ========== CONFIRMATION MESSAGE ========== */
        .confirmation {
            display: none;
            text-align: center;
            padding: 32px 20px;
            background: var(--color-white);
            border: 2px solid #22c55e;
            border-radius: var(--radius-lg);
            margin-top: 24px;
            animation: fadeInUp 0.5s ease forwards;
        }
        .confirmation--visible {
            display: block;
        }
        .confirmation__icon {
            font-size: 3rem;
            margin-bottom: 12px;
        }
        .confirmation h3 {
            color: #16a34a;
            margin-bottom: 8px;
        }
        .confirmation p {
            color: var(--color-text-secondary);
        }

        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(16px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        /* ========== SPEAKERS SECTION ========== */
        .speakers__grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 24px;
            margin-top: 40px;
        }
        .speaker-card {
            text-align: center;
            padding: 24px 16px;
            background: var(--color-white);
            border: 1px solid var(--color-border);
            border-radius: var(--radius-lg);
            transition: box-shadow var(--transition-smooth), transform var(--transition-fast);
            will-change: transform;
        }
        .speaker-card:hover {
            box-shadow: var(--shadow-card-hover);
            transform: translateY(-4px);
        }
        .speaker-avatar {
            width: 80px;
            height: 80px;
            border-radius: var(--radius-full);
            margin-inline: auto;
            margin-bottom: 16px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: 700;
            font-size: 1.4rem;
            color: #fff;
            letter-spacing: 0.02em;
        }
        .speaker-avatar--coral {
            background: linear-gradient(135deg, #e8513a, #f0826d);
        }
        .speaker-avatar--teal {
            background: linear-gradient(135deg, #1a7a6d, #3da89b);
        }
        .speaker-avatar--indigo {
            background: linear-gradient(135deg, #4a5fd2, #7b8de0);
        }
        .speaker-avatar--amber {
            background: linear-gradient(135deg, #d4852b, #e8a84c);
        }
        .speaker-card__name {
            font-weight: 700;
            font-size: 1.05rem;
            margin-bottom: 2px;
        }
        .speaker-card__role {
            font-size: 0.85rem;
            color: var(--color-text-secondary);
        }

        /* ========== VENUE SECTION ========== */
        .venue {
            background: var(--color-surface);
            text-align: center;
            border-radius: var(--radius-lg);
            margin: 0 clamp(16px, 3vw, 32px) clamp(60px, 8vh, 80px);
            padding: clamp(40px, 8vh, 70px) 24px;
        }
        .venue address {
            font-style: normal;
            font-size: 1.1rem;
            color: var(--color-text-secondary);
            margin-top: 16px;
        }
        .venue time {
            display: block;
            font-weight: 700;
            font-size: 1.3rem;
            margin-top: 8px;
        }

        /* ========== FOOTER ========== */
        .footer {
            padding: 32px 24px;
            text-align: center;
            border-top: 1px solid var(--color-border);
            color: var(--color-text-secondary);
            font-size: 0.85rem;
        }
        .footer a {
            color: var(--color-accent);
            text-decoration: none;
            font-weight: 500;
        }
        .footer a:hover {
            text-decoration: underline;
        }

        /* ========== SCROLL REVEAL ========== */
        .reveal {
            opacity: 0;
            transform: translateY(28px);
            transition: opacity 0.7s ease, transform 0.7s ease;
        }
        .reveal.revealed {
            opacity: 1;
            transform: translateY(0);
        }

        /* ========== REDUCED MOTION ========== */
        @media (prefers-reduced-motion: reduce) {
            *,
            *::before,
            *::after {
                animation-duration: 0.01ms !important;
                animation-iteration-count: 1 !important;
                transition-duration: 0.01ms !important;
                scroll-behavior: auto !important;
            }
            .reveal {
                opacity: 1;
                transform: none;
                transition: none;
            }
            .hero__cta:hover {
                transform: none;
            }
            .speaker-card:hover {
                transform: none;
            }
            .cart-summary {
                transition: none;
            }
            .sidebar {
                transition: none;
            }
            .sidebar-overlay {
                transition: none;
            }
        }

        /* ========== RESPONSIVE BREAKPOINTS ========== */
        @media (max-width: 768px) {
            .nav-desktop {
                display: none;
            }
            .hamburger {
                display: flex;
            }
            .hero__title {
                font-size: clamp(2.2rem, 10vw, 3.5rem);
            }
            .tickets__grid {
                grid-template-columns: 1fr;
                max-width: 420px;
                margin-inline: auto;
            }
            .speakers__grid {
                grid-template-columns: repeat(2, 1fr);
                gap: 16px;
            }
            .cart-summary__inner {
                flex-direction: column;
                align-items: stretch;
                text-align: center;
            }
            .cart-summary__btn {
                width: 100%;
                padding: 14px;
            }
            .about__grid {
                grid-template-columns: 1fr;
            }
            .venue {
                margin-inline: 12px;
                border-radius: var(--radius-md);
            }
        }

        @media (max-width: 420px) {
            .speakers__grid {
                grid-template-columns: 1fr 1fr;
                gap: 12px;
            }
            .speaker-card {
                padding: 16px 10px;
            }
            .speaker-avatar {
                width: 60px;
                height: 60px;
                font-size: 1.1rem;
            }
            .ticket-card {
                padding: 20px 16px;
            }
            .ticket-card__price {
                font-size: 1.7rem;
            }
        }

        /* ========== FOCUS VISIBLE GLOBAL ========== */
        :focus-visible {
            outline: 3px solid var(--color-accent);
            outline-offset: 2px;
            border-radius: 2px;
        }
    </style>
</head>
<body>

    <!-- Skip navigation link for accessibility -->
    <a href="#main-content" class="skip-link">Skip to main content</a>

    <!-- ========== HEADER ========== -->
    <header class="header" id="header" role="banner">
        <div class="header__inner">
            <a href="#" class="header__logo" aria-label="SYNTHESIS 2025 Home">SYNTH<span>ESIS</span> 2025</a>

            <!-- Desktop navigation -->
            <nav aria-label="Primary navigation">
                <ul class="nav-desktop">
                    <li><a href="#about">About</a></li>
                    <li><a href="#tickets">Tickets</a></li>
                    <li><a href="#speakers">Speakers</a></li>
                    <li><a href="#venue">Venue</a></li>
                </ul>
            </nav>

            <!-- Mobile hamburger button -->
            <button
            class="hamburger"
