<script>
    (function() {
        // ========== DOM REFERENCES ==========
        const body = document.body;
        const header = document.getElementById('header');
        const hamburger = document.getElementById('hamburger');
        const sidebar = document.getElementById('sidebar');
        const sidebarOverlay = document.getElementById('sidebar-overlay');
        const sidebarCloseBtn = document.getElementById('sidebar-close');
        const sidebarLinks = document.querySelectorAll('.sidebar-link');
        const cartSummary = document.getElementById('cart-summary');
        const cartCountEl = document.getElementById('cart-count');
        const cartTotalEl = document.getElementById('cart-total');
        const cartRegisterBtn = document.getElementById('cart-register-btn');
        const confirmationEl = document.getElementById('confirmation');
        const ticketCards = document.querySelectorAll('.ticket-card');
        const revealElements = document.querySelectorAll('.reveal');

        // ========== STATE ==========
        const cart = {
            'early-bird': 0,
            'general': 0,
            'vip': 0
        };
        const prices = {
            'early-bird': 149,
            'general': 199,
            'vip': 349
        };
        const MAX_TICKETS = 10;
        let menuOpen = false;

        // ========== MENU FUNCTIONS ==========
        function openMenu() {
            menuOpen = true;
            body.classList.add('menu-open');
            sidebar.setAttribute('aria-hidden', 'false');
            sidebarOverlay.setAttribute('aria-hidden', 'false');
            hamburger.setAttribute('aria-expanded', 'true');
            hamburger.setAttribute('aria-label', 'Close navigation menu');
            // Move focus to the close button inside the sidebar
            requestAnimationFrame(() => {
                sidebarCloseBtn.focus();
            });
        }

        function closeMenu() {
            menuOpen = false;
            body.classList.remove('menu-open');
            sidebar.setAttribute('aria-hidden', 'true');
            sidebarOverlay.setAttribute('aria-hidden', 'true');
            hamburger.setAttribute('aria-expanded', 'false');
            hamburger.setAttribute('aria-label', 'Open navigation menu');
            // Return focus to the hamburger button
            hamburger.focus();
        }

        function toggleMenu() {
            if (menuOpen) {
                closeMenu();
            } else {
                openMenu();
            }
        }

        // ========== TICKET CART FUNCTIONS ==========
        function getTicketTypeFromCard(card) {
            return card.getAttribute('data-ticket');
        }

        function updateTicketCardUI(ticketType) {
            const card = document.querySelector(`.ticket-card[data-ticket="${ticketType}"]`);
            if (!card) return;
            const qty = cart[ticketType];
            const displayEl = card.querySelector('.quantity-display');
            const decrementBtn = card.querySelector('.quantity-decrement');
            const incrementBtn = card.querySelector('.quantity-increment');

            // Update display
            displayEl.textContent = qty;

            // Toggle selected class on the card
            if (qty > 0) {
                card.classList.add('ticket-card--selected');
            } else {
                card.classList.remove('ticket-card--selected');
            }

            // Update button disabled states
            decrementBtn.disabled = (qty <= 0);
            incrementBtn.disabled = (qty >= MAX_TICKETS);
        }

        function updateCartSummary() {
            const totalQty = Object.values(cart).reduce((sum, q) => sum + q, 0);
            const totalPrice = Object.entries(cart).reduce(
                (sum, [type, qty]) => sum + qty * prices[type],
                0
            );

            // Update summary bar content
            cartCountEl.textContent = totalQty === 0 ?
                '0 tickets selected' :
                `${totalQty} ticket${totalQty > 1 ? 's' : ''} selected`;
            cartTotalEl.textContent = `$${totalPrice}`;

            // Show/hide the cart summary bar
            if (totalQty > 0) {
                cartSummary.classList.add('cart-summary--visible');
                cartRegisterBtn.disabled = false;
            } else {
                cartSummary.classList.remove('cart-summary--visible');
                cartRegisterBtn.disabled = true;
            }

            // Hide confirmation if the cart changes after registration
            if (confirmationEl.classList.contains('confirmation--visible') && totalQty === 0) {
                confirmationEl.classList.remove('confirmation--visible');
            }
        }

        function changeQuantity(ticketType, delta) {
            const current = cart[ticketType];
            const newQty = Math.max(0, Math.min(MAX_TICKETS, current + delta));
            if (newQty === current) return; // No change
            cart[ticketType] = newQty;
            updateTicketCardUI(ticketType);
            updateCartSummary();
        }

        function handleRegister() {
            const totalQty = Object.values(cart).reduce((sum, q) => sum + q, 0);
            if (totalQty === 0) return;

            // Hide the cart summary bar and show confirmation
            cartSummary.classList.remove('cart-summary--visible');
            confirmationEl.classList.add('confirmation--visible');

            // Scroll to the confirmation message
            confirmationEl.scrollIntoView({ behavior: 'smooth', block: 'center' });

            // Reset cart state after a short delay (so the bar animates out first)
            setTimeout(() => {
                // Reset all quantities
                Object.keys(cart).forEach(type => {
                    cart[type] = 0;
                    updateTicketCardUI(type);
                });
                updateCartSummary();
            }, 400);
        }

        // ========== SCROLL HANDLER FOR HEADER ==========
        function handleScroll() {
            const scrollY = window.scrollY;
            if (scrollY > 20) {
                header.classList.add('scrolled');
            } else {
                header.classList.remove('scrolled');
            }
        }

        // ========== INTERSECTION OBSERVER FOR REVEAL ANIMATIONS ==========
        function setupRevealObserver() {
            // Check for reduced motion preference
            const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
            if (prefersReducedMotion) {
                // Immediately reveal all elements without animation
                revealElements.forEach(el => el.classList.add('revealed'));
                return;
            }

            const observerOptions = {
                root: null,
                rootMargin: '0px 0px -60px 0px',
                threshold: 0.1
            };

            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('revealed');
                        observer.unobserve(entry.target);
                    }
                });
            }, observerOptions);

            revealElements.forEach(el => observer.observe(el));
        }

        // ========== EVENT LISTENERS ==========
        function bindEvents() {
            // Hamburger toggle
            hamburger.addEventListener('click', toggleMenu);

            // Sidebar close button
            sidebarCloseBtn.addEventListener('click', closeMenu);

            // Overlay click closes menu
            sidebarOverlay.addEventListener('click', closeMenu);

            // Close menu when a sidebar link is clicked
            sidebarLinks.forEach(link => {
                link.addEventListener('click', () => {
                    if (menuOpen) closeMenu();
                });
            });

            // ESC key closes the menu
            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape' && menuOpen) {
                    closeMenu();
                }
            });

            // Ticket quantity buttons — use event delegation on the tickets grid
            const ticketsGrid = document.getElementById('tickets-grid');
            ticketsGrid.addEventListener('click', (e) => {
                const btn = e.target.closest('.quantity-btn');
                if (!btn) return;
                const card = btn.closest('.ticket-card');
                if (!card) return;
                const ticketType = getTicketTypeFromCard(card);
                if (btn.classList.contains('quantity-increment')) {
                    changeQuantity(ticketType, 1);
                } else if (btn.classList.contains('quantity-decrement')) {
                    changeQuantity(ticketType, -1);
                }
            });

            // Register button
            cartRegisterBtn.addEventListener('click', handleRegister);

            // Scroll listener for header effect (throttled via rAF)
            let ticking = false;
            window.addEventListener('scroll', () => {
                if (!ticking) {
                    requestAnimationFrame(() => {
                        handleScroll();
                        ticking = false;
                    });
                    ticking = true;
                }
            });

            // Resize handler: close menu if screen goes above mobile breakpoint
            window.addEventListener('resize', () => {
                if (window.innerWidth > 768 && menuOpen) {
                    closeMenu();
                }
            });

            // Initial scroll check
            handleScroll();
        }

        // ========== INITIALIZATION ==========
        function init() {
            bindEvents();
            setupRevealObserver();
            // Initialize cart UI for all ticket types
            Object.keys(cart).forEach(type => updateTicketCardUI(type));
            updateCartSummary();
        }

        // Run when DOM is ready
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', init);
        } else {
            init();
        }
    })();
</script>
</body>
</html>
```
### Ticketing Features

Let's take a look at the interactive tool and design elements that make this ticketing platform engaging and easy to use.

**Interactive Ticket Cart**
The ticket purchasing flow is the core of this experience. Each ticket card acts as a product configurator. You can increment or decrement your selection, and the card visually updates with an "accent border" to indicate it's been chosen. A dynamic summary bar slides up from the bottom, showing your total items and price in real time. The "Register Now" button completes the purchase and triggers a confirmation message.

**Mobile Off-Canvas Navigation**
For small screens, the standard horizontal menu is replaced by a slide-in sidebar. The hamburger icon animates to a close button when active, and the navigation is tucked away behind a semi-transparent overlay. This pattern keeps the interface clean without sacrificing functionality.

**Accessible & Responsive Typography**
The design uses a fully responsive typography scale powered by CSS `clamp()` functions. Headlines and body text will scale smoothly across all devices. The layout adapts using CSS Grid and Flexbox, ensuring ticket cards and speaker profiles stack neatly on smaller screens.

**Motion-Respecting Animations**
The site includes subtle "reveal on scroll" animations for content sections. Critically, these animations are completely disabled for users who have the "prefers-reduced-motion" setting enabled in their operating system, adhering to accessibility best practices.

---

**Optimization Tip:** You can replace the placeholder speaker names, roles, and avatar colors (CSS classes like `.speaker-avatar--coral`) with your own team's information. The ticket prices and event dates are also easily editable in the HTML and the `prices` object inside the `<script>` tag.

