        const bgLayers = [];

        /** Creates a deterministic set of mountain shapes */
        function generateMountains(layerWidth) {
            const mountains = [];
            let x = 0;
            while (x < layerWidth) {
                const w = 80 + Math.random() * 160;
                const h = 100 + Math.random() * 180;
                mountains.push({ x, width: w, height: h });
                x += w * 0.7; // overlap slightly
            }
            mountains.sort((a, b) => a.x - b.x);
            return mountains;
        }

        /** Creates rolling hills using overlapping circles */
        function generateHills(layerWidth) {
            const hills = [];
            let x = -50;
            while (x < layerWidth + 100) {
                const radius = 70 + Math.random() * 180;
                hills.push({ x, y: CANVAS_HEIGHT - 20, radius });
                x += radius * 0.8;
            }
            hills.sort((a, b) => a.x - b.x);
            return hills;
        }

        /** Creates background trees with trunks and canopies */
        function generateTrees(layerWidth) {
            const trees = [];
            let x = 20;
            while (x < layerWidth) {
                const trunkHeight = 20 + Math.random() * 40;
                const canopyRadius = 15 + Math.random() * 25;
                trees.push({ x, baseY: CANVAS_HEIGHT - 60, trunkHeight, canopyRadius });
                x += 60 + Math.random() * 100;
            }
            trees.sort((a, b) => a.x - b.x);
            return trees;
        }

        /** Build the three parallax layers with different scroll factors */
        function initBackgrounds() {
            const maxCameraX = WORLD_WIDTH - CANVAS_WIDTH;

            // Layer 1: Far mountains (scroll factor 0.15)
            const factor1 = 0.15;
            const layerWidth1 = maxCameraX * factor1 + CANVAS_WIDTH;
            bgLayers.push({
                factor: factor1,
                elements: generateMountains(layerWidth1),
                drawFn: drawMountain
            });

            // Layer 2: Hills (factor 0.4)
            const factor2 = 0.4;
            const layerWidth2 = maxCameraX * factor2 + CANVAS_WIDTH;
            bgLayers.push({
                factor: factor2,
                elements: generateHills(layerWidth2),
                drawFn: drawHill
            });

            // Layer 3: Trees (factor 0.7)
            const factor3 = 0.7;
            const layerWidth3 = maxCameraX * factor3 + CANVAS_WIDTH;
            bgLayers.push({
                factor: factor3,
                elements: generateTrees(layerWidth3),
                drawFn: drawTree
            });
        }

        // =====================
        // CAMERA
        // =====================
        let cameraX = 0;

        /** Centers camera on player, clamped to world bounds */
        function updateCamera() {
            cameraX = player.x + player.width / 2 - CANVAS_WIDTH / 2;
            cameraX = Math.max(0, Math.min(cameraX, WORLD_WIDTH - CANVAS_WIDTH));
        }

        // =====================
        // PHYSICS & GAME UPDATE
        // =====================
        function spawnParticles(x, y, count) {
            for (let i = 0; i < count; i++) {
                const angle = Math.random() * Math.PI * 2;
                const speed = 1 + Math.random() * 3;
                particles.push({
                    x: x, y: y,
                    vx: Math.cos(angle) * speed,
                    vy: Math.sin(angle) * speed - 1,
                    life: 30 + Math.random() * 20,
                    maxLife: 50
                });
            }
        }

        /** Fixed-timestep update (called 60 times per second) */
        function update() {
            // ---- Input ----
            const moveLeft = keys['ArrowLeft'] || keys['KeyA'];
            const moveRight = keys['ArrowRight'] || keys['KeyD'];
            const jumpKey = keys['ArrowUp'] || keys['KeyW'] || keys[' '];

            // Detect jump on the rising edge (press, not hold)
            let jumpPressed = false;
            if (jumpKey && !previousJumpKey) {
                jumpPressed = true;
            }
            previousJumpKey = jumpKey;

            // Horizontal movement and facing direction
            if (moveLeft) {
                player.vx = -MOVE_SPEED;
                player.facingRight = false;
                player.isRunning = true;
            } else if (moveRight) {
                player.vx = MOVE_SPEED;
                player.facingRight = true;
                player.isRunning = true;
            } else {
                player.vx = 0;
                player.isRunning = false;
            }

            // Jumping (only when on ground)
            if (jumpPressed && player.onGround) {
                player.vy = JUMP_FORCE;
                player.onGround = false;
            }

            // Apply gravity
            player.vy += GRAVITY;
            if (player.vy > MAX_FALL_SPEED) {
                player.vy = MAX_FALL_SPEED;
            }

            // ---- X-axis movement & collision ----
            player.x += player.vx;
            for (const plat of platforms) {
                if (player.x < plat.x + plat.w &&
                    player.x + player.width > plat.x &&
                    player.y < plat.y + plat.h &&
                    player.y + player.height > plat.y) {
                    // Resolve horizontal overlap
                    if (player.vx > 0) {
                        player.x = plat.x - player.width; // hit right edge
                    } else if (player.vx < 0) {
                        player.x = plat.x + plat.w;       // hit left edge
                    }
                    player.vx = 0;
                }
            }

            // Clamp player inside world horizontally
            if (player.x < 0) {
                player.x = 0;
                player.vx = 0;
            }
            if (player.x + player.width > WORLD_WIDTH) {
                player.x = WORLD_WIDTH - player.width;
                player.vx = 0;
            }

            // ---- Y-axis movement & collision ----
            player.y += player.vy;
            player.onGround = false; // will be set true if landing
            for (const plat of platforms) {
                if (player.x < plat.x + plat.w &&
                    player.x + player.width > plat.x &&
                    player.y < plat.y + plat.h &&
                    player.y + player.height > plat.y) {
                    if (player.vy > 0) {
                        // Falling – land on top of platform
                        player.y = plat.y - player.height;
                        player.vy = 0;
                        player.onGround = true;
                    } else if (player.vy < 0) {
                        // Jumping up – hit underside of platform
                        player.y = plat.y + plat.h;
                        player.vy = 0;
                    }
                }
            }

            // Safety stop at canvas bottom (should never happen because of ground platform)
            if (player.y + player.height > CANVAS_HEIGHT) {
                player.y = GROUND_Y - player.height;
                player.vy = 0;
                player.onGround = true;
            }

            // ---- Coin collection (circle vs AABB) ----
            for (const coin of coins) {
                if (coin.collected) continue;
                // Closest point on player AABB to coin center
                const closestX = Math.max(player.x, Math.min(coin.x, player.x + player.width));
                const closestY = Math.max(player.y, Math.min(coin.y, player.y + player.height));
                const dx = coin.x - closestX;
                const dy = coin.y - closestY;
                if (dx * dx + dy * dy < coin.radius * coin.radius) {
                    coin.collected = true;
                    score++;
                    // Spawn a burst of particles for visual feedback
                    spawnParticles(coin.x, coin.y, 8);
                }
            }

            // ---- Update particles ----
            for (let i = particles.length - 1; i >= 0; i--) {
                const p = particles[i];
                p.x += p.vx;
                p.y += p.vy;
                p.vy += 0.1; // particle gravity
                p.life--;
                if (p.life <= 0) {
                    particles.splice(i, 1);
                }
            }

            // ---- Animation timer ----
            if (player.isRunning) {
                player.animTimer++;
                if (player.animTimer > 5) {        // change leg frame every 5 updates
                    player.animFrame = (player.animFrame + 1) % 2;
                    player.animTimer = 0;
                }
            } else {
                player.animFrame = 0;
                player.animTimer = 0;
            }

            // Move camera
            updateCamera();
        }

        // =====================
        // RENDERING FUNCTIONS
        // =====================

        /** Draws the static sky gradient and sun */
        function drawSky() {
            const gradient = ctx.createLinearGradient(0, 0, 0, CANVAS_HEIGHT);
            gradient.addColorStop(0, '#0b3d91');
            gradient.addColorStop(0.4, '#1e90ff');
            gradient.addColorStop(0.8, '#87ceeb');
            gradient.addColorStop(1, '#c3e3fa');
            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

            // Sun
            ctx.fillStyle = '#FFD700';
            ctx.beginPath();
            ctx.arc(650, 100, 40, 0, Math.PI * 2);
            ctx.fill();
            // Sun rays
            ctx.strokeStyle = '#FFD700';
            ctx.lineWidth = 2;
            for (let i = 0; i < 12; i++) {
                const angle = i * Math.PI / 6;
                const dx = Math.cos(angle) * 55;
                const dy = Math.sin(angle) * 55;
                ctx.beginPath();
                ctx.moveTo(650 + Math.cos(angle) * 45, 100 + Math.sin(angle) * 45);
                ctx.lineTo(650 + dx, 100 + dy);
                ctx.stroke();
            }
        }

        /** Draws a single mountain (triangle + snow cap) */
        function drawMountain(ctx, m, offsetX) {
            const sx = m.x - offsetX;
            if (sx + m.width < 0 || sx > CANVAS_WIDTH) return;

            // Mountain body
            ctx.fillStyle = '#4a3f6b';
            ctx.beginPath();
            ctx.moveTo(sx, CANVAS_HEIGHT);
            ctx.lineTo(sx + m.width / 2, CANVAS_HEIGHT - m.height);
            ctx.lineTo(sx + m.width, CANVAS_HEIGHT);
            ctx.closePath();
            ctx.fill();

            // Snow cap
            ctx.fillStyle = '#ffffff';
            ctx.beginPath();
            ctx.moveTo(sx + m.width / 2, CANVAS_HEIGHT - m.height);
            ctx.lineTo(sx + m.width * 0.35, CANVAS_HEIGHT - m.height * 0.7);
            ctx.lineTo(sx + m.width * 0.65, CANVAS_HEIGHT - m.height * 0.7);
            ctx.closePath();
            ctx.fill();
        }

        /** Draws a single hill (top semicircle filled down to bottom) */
        function drawHill(ctx, h, offsetX) {
            const sx = h.x - offsetX;
            if (sx + h.radius < 0 || sx - h.radius > CANVAS_WIDTH) return;

            ctx.fillStyle = '#2d5a27';
            ctx.beginPath();
            // Top semicircle (PI to 0 clockwise goes through top)
            ctx.arc(sx, h.y, h.radius, Math.PI, 0);
            // Fill the area below the arc down to the bottom edge
            ctx.lineTo(sx + h.radius, CANVAS_HEIGHT);
            ctx.lineTo(sx - h.radius, CANVAS_HEIGHT);
            ctx.closePath();
            ctx.fill();
        }

        /** Draws a single tree (trunk + canopy circle) */
        function drawTree(ctx, t, offsetX) {
            const sx = t.x - offsetX;
            if (sx + 20 < 0 || sx - 20 > CANVAS_WIDTH) return;

            // Trunk
            ctx.fillStyle = '#5d4037';
            const trunkW = 6;
            ctx.fillRect(sx - trunkW / 2, t.baseY - t.trunkHeight, trunkW, t.trunkHeight);

            // Canopy
            ctx.fillStyle = '#3b5e2b';
            ctx.beginPath();
            ctx.arc(sx, t.baseY - t.trunkHeight - t.canopyRadius / 2, t.canopyRadius, 0, Math.PI * 2);
            ctx.fill();
        }

        /** Draws a bobbing, shiny coin */
        function drawCoin(ctx, coin, sx, sy, time) {
            const bobY = Math.sin(time * 0.005 + coin.x) * 2;
            const y = sy + bobY;
            ctx.save();
            ctx.translate(sx, y);

            // Outer gold circle
            ctx.fillStyle = '#FFD700';
            ctx.beginPath();
            ctx.arc(0, 0, coin.radius, 0, Math.PI * 2);
            ctx.fill();

            // Inner darker circle
            ctx.fillStyle = '#FFA500';
            ctx.beginPath();
            ctx.arc(-1, -1, coin.radius * 0.6, 0, Math.PI * 2);
            ctx.fill();

            // Shine highlight
            ctx.fillStyle = '#FFFFFF';
            ctx.beginPath();
            ctx.arc(-2, -3, coin.radius * 0.3, 0, Math.PI * 2);
            ctx.fill();

            ctx.restore();
        }

        /** Draws the player sprite with running animation */
        function drawPlayer(ctx, x, y, facingRight, isRunning, animFrame) {
            const cx = x + PLAYER_WIDTH / 2;   // center X
            const cy = y + PLAYER_HEIGHT;      // bottom Y (feet position)

            ctx.save();
            ctx.translate(cx, cy);
            if (!facingRight) {
                ctx.scale(-1, 1);              // mirror for left-facing
            }

            // Body (torso)
            ctx.fillStyle = '#ffcc00';
            ctx.fillRect(-8, -30, 16, 20);

            // Head
            ctx.beginPath();
            ctx.arc(0, -36, 8, 0, Math.PI * 2);
            ctx.fill();

            // Eyes
            ctx.fillStyle = '#000000';
            ctx.fillRect(2, -39, 3, 3);        // right eye
            ctx.fillRect(-5, -39, 3, 3);       // left eye

            // Legs with running animation
            ctx.fillStyle = '#333333';
            if (isRunning) {
                if (animFrame === 0) {
                    ctx.fillRect(-6, -10, 5, 10);  // left leg down
                    ctx.fillRect(1, -10, 5, 6);    // right leg up
                } else {
                    ctx.fillRect(-6, -10, 5, 6);   // left leg up
                    ctx.fillRect(1, -10, 5, 10);   // right leg down
                }
            } else {
                // Idle stance
                ctx.fillRect(-6, -10, 5, 10);
                ctx.fillRect(1, -10, 5, 10);
            }

            // Arms
            ctx.fillStyle = '#ffcc00';
            ctx.fillRect(-12, -26, 4, 10);      // left arm
            ctx.fillRect(8, -26, 4, 10);        // right arm

            ctx.restore();
        }

        /** Main render call – draws all layers, objects, UI */
        function render(timestamp) {
            ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

            // 1. Static sky (parallax factor 0)
            drawSky();

            // 2. Parallax background layers (mountains, hills, trees)
            for (const layer of bgLayers) {
                const offset = cameraX * layer.factor;
                for (const elem of layer.elements) {
                    layer.drawFn(ctx, elem, offset);
                }
            }

            // 3. Platforms
            ctx.strokeStyle = '#3e2723';
            ctx.lineWidth = 1;
            for (const plat of platforms) {
                const sx = plat.x - cameraX;
                if (sx + plat.w < 0 || sx > CANVAS_WIDTH) continue; // off‑screen culling

                // Platform body (brown)
                ctx.fillStyle = '#6b4c3b';
                ctx.fillRect(sx, plat.y, plat.w, plat.h);
                // Grass top (green strip)
                ctx.fillStyle = '#4caf50';
                ctx.fillRect(sx, plat.y, plat.w, 5);
                // Border
                ctx.strokeRect(sx, plat.y, plat.w, plat.h);
            }

            // 4. Coins
            for (const coin of coins) {
                if (coin.collected) continue;
                const sx = coin.x - cameraX;
                const sy = coin.y;
                if (sx + coin.radius < 0 || sx - coin.radius > CANVAS_WIDTH) continue;
                drawCoin(ctx, coin, sx, sy, timestamp);
            }

            // 5. Particles (from collected coins)
            for (const p of particles) {
                const sx = p.x - cameraX;
                if (sx < -10 || sx > CANVAS_WIDTH + 10) continue;
                const alpha = p.life / p.maxLife;
                ctx.fillStyle = `rgba(255, 215, 0, ${alpha})`;
                ctx.beginPath();
                ctx.arc(sx, p.y, 3 * alpha, 0, Math.PI * 2);
                ctx.fill();
            }

            // 6. Player
            const playerSX = player.x - cameraX;
            const playerSY = player.y;
            drawPlayer(ctx, playerSX, playerSY, player.facingRight, player.isRunning, player.animFrame);

            // 7. UI – Score display
            ctx.font = 'bold 24px "Arial", sans-serif';
            ctx.fillStyle = '#ffffff';
            ctx.strokeStyle = '#000000';
            ctx.lineWidth = 2;
            ctx.strokeText(`Score: ${score}`, 20, 40);
            ctx.fillText(`Score: ${score}`, 20, 40);
        }

        // =====================
        // GAME LOOP (fixed timestep)
        // =====================
        let lastTime = 0;
        const FIXED_DT = 1000 / 60;    // 16.67ms per physics step
        let accumulator = 0;

        function gameLoop(timestamp) {
            if (lastTime === 0) lastTime = timestamp;

            let delta = timestamp - lastTime;
            lastTime = timestamp;

            // Prevent huge delta when tab is backgrounded
            if (delta > 200) delta = 200;
            accumulator += delta;
            if (accumulator > 200) accumulator = 200; // avoid spiral of death

            // Run physics at a fixed rate
            while (accumulator >= FIXED_DT) {
                update();
                accumulator -= FIXED_DT;
            }

            // Render with the current timestamp (for animations)
            render(timestamp);

            requestAnimationFrame(gameLoop);
        }

        // =====================
        // INIT & START
        // =====================
        initCoins();
        initBackgrounds();
        requestAnimationFrame(gameLoop);
    </script>
</body>
</html>
