Below is a complete TypeScript implementation of the 0/1 knapsack problem using dynamic programming.  
It solves a concrete instance with **5 items** and **capacity 17**, reconstructs the optimal set of items, and traces through the backtracking step by step.

```typescript
// ---------- Data for our example ----------
const weights = [3, 4, 7, 8, 9];
const values  = [5, 8, 12, 14, 16];
const capacity = 17;

// ---------- DP Solution ----------
function knapsack01(
  weights: number[],
  values: number[],
  capacity: number
): { maxValue: number; selectedItems: number[] } {
  const n = weights.length;

  // dp[i][w] = maximum value using first i items with capacity w
  const dp: number[][] = Array.from({ length: n + 1 }, () =>
    Array(capacity + 1).fill(0)
  );

  // Build DP table
  for (let i = 1; i <= n; i++) {
    const itemWeight = weights[i - 1];
    const itemValue = values[i - 1];
    for (let w = 0; w <= capacity; w++) {
      if (itemWeight <= w) {
        dp[i][w] = Math.max(
          dp[i - 1][w],                           // skip item
          dp[i - 1][w - itemWeight] + itemValue   // take item
        );
      } else {
        dp[i][w] = dp[i - 1][w];
      }
    }
  }

  // ---------- Reconstruct the optimal solution ----------
  const selectedItems: number[] = [];
  let w = capacity;

  console.log("=== Backtracking Trace ===");
  for (let i = n; i >= 1; i--) {
    const itemIdx = i - 1;               // convert to 0‑based index
    const skipValue = dp[i - 1][w];
    const takenValue = dp[i][w];

    console.log(
      `i=${i} (item ${itemIdx + 1}, weight=${weights[itemIdx]}, value=${values[itemIdx]}), ` +
      `current capacity w=${w}, dp[${i}][${w}]=${takenValue}, dp[${i - 1}][${w}]=${skipValue}`
    );

    if (takenValue !== skipValue) {
      // Item was included
      selectedItems.push(itemIdx + 1);   // store 1‑based index for readability
      w -= weights[itemIdx];
      console.log(`  -> Item ${itemIdx + 1} WAS taken. Remaining capacity: ${w}`);
    } else {
      console.log(`  -> Item ${itemIdx + 1} was NOT taken.`);
    }
  }

  selectedItems.reverse(); // restore original order
  return { maxValue: dp[n][capacity], selectedItems };
}

// ---------- Run the example ----------
const result = knapsack01(weights, values, capacity);

console.log("\n=== Final Result ===");
console.log("Optimal value:", result.maxValue);
console.log("Selected items (1‑based):", result.selectedItems);
```

