function sendAuditReports() {
  // ===== CONFIGURATION =====
  var RECIPIENT_COLUMN = 'A';  // Column that holds the analysts' emails (change as needed)
  var REPORT_TITLE = 'Audit Report - ' + Utilities.formatDate(new Date(), Session.getScriptTimeZone(), 'yyyy-MM-dd');
