/**
 * Dynamically imports modules and aggregates their exports into a single object.
 * This mimics the behavior of multiple static `export * from ...` statements.
 * 
 * @param {string[]} moduleNames - Array of module names (e.g., ['theme', 'typography']).
 * @returns {Promise<object>} A promise that resolves to an object containing all named exports
 *                            from the imported modules. In case of naming conflicts, the
 *                            module imported later overwrites earlier exports.
 * 
 * @example
 * // If './theme' exports { colors: [...], font: 'Arial' }
 * // and './typography' exports { font: 'Roboto', sizes: [...] }
 * const combined = await dynamicModuleImportExport(['theme', 'typography']);
 * // combined: { colors: [...], font: 'Roboto', sizes: [...] }
 */
async function dynamicModuleImportExport(moduleNames) {
  // Dynamically import all specified modules. Relative paths are assumed to be './<name>'.
  const modules = await Promise.all(
    moduleNames.map(name => import(`./${name}`))
  );

  // Merge all module exports into a single object (last write wins for duplicates).
  return Object.assign({}, ...modules);
}
