class Processor {
public:
 std::string process(const std::string& x, size_t index, int z, int w) {
 if (index >= x.size()) return "";
 auto key = std::make_tuple(index, z, w);
 auto cached = get_memo(key);
 if (cached.has_value()) return cached.value();

 char a = x[index];
