 return result;
 }

private:
 struct KeyHash {
 std::size_t operator()(const std::tuple<size_t, int, int>& key) const {
 return std::hash<size_t>()(std::get<0>(key)) ^ 
 (std::hash<int>()(std::get<1>(key)) << 1) ^ 
 (std::hash<int>()(std::get<2>(key)) << 2);
 }
 };

 std::optional<std::string> get_memo(const std::tuple<size_t, int, int>& key) const {
 auto it = memo.find(key);
 if (it != memo.end()) {
 return it->second;
 }
 return std::nullopt;
 }

 void set_memo(const std::tuple<size_t, int, int>& key, const std::string& value) {
 memo.emplace(key, value);
 }

 char transform_char(char a, int z, int w) const {
 auto transformer = [a, z, w](char base) -> char {
 return static_cast<char>((((a - base) + z + w) % 26) + base);
 };

 if (std::islower(a)) {
 return transformer('a');
 }
 if (std::isupper(a)) {
 return transformer('A');
 }
 return a;
 }

 std::pair<int, int> update_states(char a, int z, int w) const {
 auto updater = [&](bool is_alpha) -> std::pair<int, int> {
 if (is_alpha) {
 return { (z + 3) % 5, (w + 2) % 7 };
 }
 return { z, (w + 1) % 7 };
 };

 return (std::isalpha(a)) ? updater(true) : updater(false);
 }

 std::unordered_map<std::tuple<size_t, int, int>, std::string, KeyHash> memo;
};

