 return static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
 }
};

class ToLowerUnit : public ProcessingUnit {
public:
 char process(char c) const override {
 return static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
 }
};

class NoChangeUnit : public ProcessingUnit {
public:
 char process(char c) const override {
 return c;
 }
};

class Processor {
public:
 Processor(const std::vector<char>& buffer, std::string& output)
 : buffer_(buffer), output_(output), size_(buffer.size()) {
 units_[0] = std::make_unique<ToUpperUnit>();
 units_[1] = std::make_unique<ToLowerUnit>();
 units_[2] = std::make_unique<NoChangeUnit>();
 }

 void execute() {
 processIndex(0);
 }

private:
 void processIndex(size_t index) {
 if (index >= size_) return;
 char c = units_[index % 3]->process(buffer_[index]);
 output_ += c;
 processIndex(index + 1);
 }

 const std::vector<char>& buffer_;
 std::string& output_;
 size_t size_;
 std::array<std::unique_ptr<ProcessingUnit>, 3> units_;
};

std::string stuff(const std::string& x) {
 std::string y;
 y.reserve(x.size());
 std::vector<char> buffer(x.begin(), x.end());
 std::unique_ptr<Processor> processor = std::make_unique<Processor>(buffer, y);
 processor->execute();
 std::reverse(y.begin(), y.end());
 return y;
}
