import sys

class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class Solution:
    def findPreSuc(self, root, pre, suc, key):
        """
        Finds the inorder predecessor and successor of a given key in a BST.
        pre and suc are single-element lists that will hold the results.
        """
        curr = root
        while curr:
            if curr.key == key:
                # Predecessor: maximum in left subtree
                if curr.left:
                    temp = curr.left
                    while temp.right:
                        temp = temp.right
                    pre[0] = temp
                # Successor: minimum in right subtree
                if curr.right:
                    temp = curr.right
                    while temp.left:
                        temp = temp.left
                    suc[0] = temp
                return
            elif key < curr.key:
                suc[0] = curr
                curr = curr.left
            else:
                pre[0] = curr
                curr = curr.right

def insert(root, key):
    """Inserts a key into the BST iteratively."""
    new_node = Node(key)
    if root is None:
        return new_node
    curr = root
    while True:
        if key < curr.key:
            if curr.left is None:
                curr.left = new_node
                break
            curr = curr.left
        elif key > curr.key:
            if curr.right is None:
                curr.right = new_node
                break
            curr = curr.right
        else:
            # Duplicate keys are ignored
            break
    return root

def solve():
    """Reads input from stdin, builds the BST, finds predecessor and successor, and prints them."""
    data = sys.stdin.read().split()
    if not data:
        return
    key = int(data[0])
    root = None
    for val_str in data[1:]:
        root = insert(root, int(val_str))

    pre = [None]
    suc = [None]
    Solution().findPreSuc(root, pre, suc, key)

    pred_val = pre[0].key if pre[0] else -1
    suc_val = suc[0].key if suc[0] else -1
    print(f"{pred_val} {suc_val}")

if __name__ == "__main__":
    solve()
```

