pub fn stuff(a: &str) -> String {
 enum CharType {
 Uppercase,
 Lowercase,
 Other,
 }

 fn classify_char(c: char) -> CharType {
 if c.is_ascii_uppercase() {
 CharType::Uppercase
 } else if c.is_ascii_lowercase() {
 CharType::Lowercase
 } else {
 CharType::Other
 }
 }

 trait Shifter {
 fn shift(&self, c: char) -> char;
 }

 struct CaesarShifter {
 shift: u8,
 }

