 match classify_char(c) {
 CharType::Uppercase => (((c as u8 - 65 + self.shift) % 26) + 65) as char,
 CharType::Lowercase => (((c as u8 - 97 + self.shift) % 26) + 97) as char,
 CharType::Other => c,
 }
 }
 }

 fn process_recursively(chars: &[char], index: usize, shifter: &dyn Shifter, acc: &mut String) {
 if index == 0 {
 return;
 }
 let current = chars[index - 1];
 let shifted = shifter.shift(current);
 acc.push(shifted);
 process_recursively(chars, index - 1, shifter, acc)
 }

 fn expand_and_process(chars: &[char], shifter: &dyn Shifter, acc: &mut String) {
 let mut index = chars.len();
 process_recursively(chars, index, shifter, acc)
