Below is a complete C implementation of a **priority queue** backed by a **binary min‑heap**, along with an **iterator** that allows you to traverse the elements. A convenience macro `PQ_FOREACH` provides a **for‑each** style loop, similar to higher‑level languages.

## Design overview

- **Min‑heap** – the smallest element has the highest priority and sits at the root.  
  Operations: `insert`, `extract_min`, `peek`, `size`, `is_empty`.  
  The heap is stored in a dynamic array that grows/shrinks automatically.

- **Iterator** – a small struct holding a pointer to the priority queue and a current index.  
  It traverses the underlying array in **heap level order** (i.e. the raw array order, **not** sorted priority order).  
  An iterator is invalidated if the priority queue is modified.

- **For‑each macro** – `PQ_FOREACH(pq, var)` expands to a `for` loop that correctly iterates over every element, even when `continue` or `break` is used.

---

## Full C implementation

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

/* -------------------- Priority Queue -------------------- */
typedef struct {
    int *heap;      // dynamic array holding the heap
    int size;       // number of elements currently in the heap
    int capacity;   // allocated size of the array
} PriorityQueue;

/* -------------------- Iterator -------------------- */
typedef struct {
    PriorityQueue *pq;
    int index;      // current position in the heap array
} PQIterator;

/* ---------- Priority Queue function prototypes ---------- */
PriorityQueue* pq_create(int initial_capacity);
void pq_destroy(PriorityQueue *pq);
bool pq_is_empty(PriorityQueue *pq);
int pq_size(PriorityQueue *pq);
void pq_insert(PriorityQueue *pq, int value);
int pq_extract_min(PriorityQueue *pq);
int pq_peek(PriorityQueue *pq);

/* ---------- Iterator function prototypes ---------- */
PQIterator pq_iterator(PriorityQueue *pq);
bool pq_iterator_has_next(PQIterator *it);
int pq_iterator_next(PQIterator *it);

/* For‑each macro */
#define PQ_FOREACH(pq, var) \
    for (PQIterator _pq_foreach_it = pq_iterator(pq); \
         pq_iterator_has_next(&_pq_foreach_it) && \
         ((var = pq_iterator_next(&_pq_foreach_it)), 1); )

/* ============================================================
                Priority queue implementation
   ============================================================ */

// Swap two integers (helper)
static void swap(int *a, int *b) {
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

// Bubble a newly inserted element upward to restore heap order
static void heapify_up(int *heap, int idx) {
    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (heap[idx] < heap[parent]) {
            swap(&heap[idx], &heap[parent]);
            idx = parent;
        } else {
            break;
        }
    }
}

// Bubble the root element downward after extraction
static void heapify_down(int *heap, int size, int idx) {
    while (1) {
        int left = 2 * idx + 1;
        int right = 2 * idx + 2;
        int smallest = idx;

        if (left < size && heap[left] < heap[smallest])
            smallest = left;
        if (right < size && heap[right] < heap[smallest])
            smallest = right;

        if (smallest != idx) {
            swap(&heap[idx], &heap[smallest]);
            idx = smallest;
        } else {
            break;
        }
    }
}

PriorityQueue* pq_create(int initial_capacity) {
    if (initial_capacity <= 0) initial_capacity = 4;   // sensible default

    PriorityQueue *pq = malloc(sizeof(PriorityQueue));
    if (!pq) return NULL;

    pq->heap = malloc(initial_capacity * sizeof(int));
    if (!pq->heap) {
        free(pq);
        return NULL;
    }
    pq->size = 0;
    pq->capacity = initial_capacity;
    return pq;
}

void pq_destroy(PriorityQueue *pq) {
    if (pq) {
        free(pq->heap);
        free(pq);
    }
}

bool pq_is_empty(PriorityQueue *pq) {
    return pq->size == 0;
}

int pq_size(PriorityQueue *pq) {
    return pq->size;
}

void pq_insert(PriorityQueue *pq, int value) {
    // Grow array if full
    if (pq->size == pq->capacity) {
        int new_cap = pq->capacity * 2;
        int *new_heap = realloc(pq->heap, new_cap * sizeof(int));
        if (!new_heap) {
            fprintf(stderr, "pq_insert: memory allocation failed\n");
            return;
        }
        pq->heap = new_heap;
        pq->capacity = new_cap;
    }

    pq->heap[pq->size] = value;
    heapify_up(pq->heap, pq->size);
    pq->size++;
}

int pq_extract_min(PriorityQueue *pq) {
    if (pq_is_empty(pq)) {
        fprintf(stderr, "pq_extract_min: priority queue is empty\n");
        exit(EXIT_FAILURE);
    }

    int min_val = pq->heap[0];
    pq->heap[0] = pq->heap[pq->size - 1];
    pq->size--;
    heapify_down(pq->heap, pq->size, 0);

    // Shrink array if it's mostly empty
    if (pq->size > 0 && pq->size < pq->capacity / 4 && pq->capacity > 8) {
        int new_cap = pq->capacity / 2;
        int *new_heap = realloc(pq->heap, new_cap * sizeof(int));
        if (new_heap) {               // keep old heap if realloc fails
            pq->heap = new_heap;
            pq->capacity = new_cap;
        }
    }
    return min_val;
}

int pq_peek(PriorityQueue *pq) {
    if (pq_is_empty(pq)) {
        fprintf(stderr, "pq_peek: priority queue is empty\n");
        exit(EXIT_FAILURE);
    }
    return pq->heap[0];
}

/* ============================================================
                     Iterator implementation
   ============================================================ */

PQIterator pq_iterator(PriorityQueue *pq) {
    PQIterator it;
    it.pq = pq;
    it.index = 0;
    return it;
}

bool pq_iterator_has_next(PQIterator *it) {
    return it->index < it->pq->size;
}

int pq_iterator_next(PQIterator *it) {
    if (!pq_iterator_has_next(it)) {
        fprintf(stderr, "pq_iterator_next: no more elements\n");
        exit(EXIT_FAILURE);
    }
    return it->pq->heap[it->index++];
}

/* ============================================================
                     Example usage
   ============================================================ */

int main(void) {
    PriorityQueue *pq = pq_create(2);

    pq_insert(pq, 5);
    pq_insert(pq, 3);
    pq_insert(pq, 8);
    pq_insert(pq, 1);
    pq_insert(pq, 4);

    /* --- Manual iterator loop --- */
    printf("Elements (heap order): ");
    for (PQIterator it = pq_iterator(pq); pq_iterator_has_next(&it); ) {
        int v = pq_iterator_next(&it);
        printf("%d ", v);
    }
    printf("\n");

    /* --- For‑each macro --- */
    printf("Using PQ_FOREACH: ");
    int value;
    PQ_FOREACH(pq, value) {
        printf("%d ", value);
    }
    printf("\n");

    /* --- Extracting in priority order --- */
    printf("Extracting (sorted): ");
    while (!pq_is_empty(pq)) {
        printf("%d ", pq_extract_min(pq));
    }
    printf("\n");

    pq_destroy(pq);
    return 0;
}
```

### Compilation and output

```
Elements (heap order): 1 3 8 5 4 
Using PQ_FOREACH: 1 3 8 5 4 
Extracting (sorted): 1 3 4 5 8 
```

## Key points

- The **binary min‑heap** is stored as a flat array; children of node at index `i` are at `2i+1` and `2i+2`.
- `pq_insert` and `pq_extract_min` take **O(log n)** time; `pq_peek` is **O(1)**.
- The **iterator** simply traverses the array from index `0` to `size-1`. This order is **not** sorted – it reflects the current heap layout.
- **`PQ_FOREACH(pq, var)`** expands to a full `for` loop. It is safe with `continue` and `break`.
- Modifying the queue (insert/extract) while an iterator is active invalidates the iterator; it is the caller’s responsibility to avoid this.

This design gives you both the efficiency of a binary heap and the convenience of a for‑each loop in plain C.

Yes, absolutely! CSS Flexbox is a perfect tool for creating responsive three-column layouts. You can use it to build a row of three columns that stack or adapt on smaller screens.

Here’s a step-by‑step guide, including a complete example.

---

## Basic Three‑Column Flexbox Setup

The core idea is to set the parent container to `display: flex;` and give each column a flexible width. The easiest way is to use `flex: 1;` on all columns so they share the available space equally.

```html
<div class="row">
  <div class="column">Column 1</div>
  <div class="column">Column 2</div>
  <div class="column">Column 3</div>
</div>
```

```css
.row {
  display: flex;
  gap: 20px;            /* Optional spacing between columns */
}

.column {
  flex: 1;              /* Each column takes equal width */
  /* or flex: 1 1 0; */
  padding: 20px;
  background: #f0f0f0;
}
```

`flex: 1` is shorthand for `flex-grow: 1; flex-shrink: 1; flex-basis: 0;`. It tells each column to grow and shrink equally, ignoring the content’s intrinsic size.

> **Note:** You can also use percentage widths like `width: 33.33%`, but `flex: 1` is more flexible.

---

## Making It Responsive

A three‑column layout needs to adapt to smaller screens (e.g., tablets and mobiles). There are two common approaches:

### 1. Wrap columns using `flex-wrap`

If you just want columns to drop to a new row when the container becomes too narrow, you can add `flex-wrap` and set a minimum width for each column.

```css
.row {
  display: flex;
  flex-wrap: wrap;       /* Allow wrapping */
  gap: 20px;
}

.column {
  flex: 1 1 250px;        /* Grow, shrink, and base width of 250px */
  padding: 20px;
  background: #f0f0f0;
}
```

With `flex: 1 1 250px;` each column will be at least 250px wide. When the container is wider than `3 * 250px + gaps`, they sit side‑by‑side. Otherwise, the last column wraps to the next line. This is a very simple responsive behavior without media queries.

### 2. Stack all columns on small screens (media queries)

If you want all three columns to become full‑width (stacked vertically) below a certain breakpoint, use media queries:

```css
/* Desktop: three columns */
.row {
  display: flex;
  gap: 20px;
}

.column {
  flex: 1;
  padding: 20px;
  background: #f0f0f0;
}

/* Tablet: maybe two columns? (optional) */
@media (max-width: 900px) {
  .row {
    flex-wrap: wrap;
  }
  .column {
    flex: 1 1 40%;       /* Two columns per row */
  }
}

/* Mobile: single column */
@media (max-width: 600px) {
  .column {
    flex: 1 1 100%;      /* Full width */
  }
}
```

This gives you full control over exactly how the layout changes at each screen size.

---

## Complete Example with Mobile‑First Approach

Here’s a production‑ready snippet you can copy and modify:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Responsive 3 Columns with Flexbox</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 20px;
    }

    .row {
      display: flex;
      flex-wrap: wrap;
      gap: 20px;
    }

    .column {
      flex: 1 1 300px;       /* Minimum 300px, then grow/shrink */
      padding: 20px;
      background: #e2e8f0;
      border-radius: 8px;
      text-align: center;
    }

    /* Optional: remove gap on the outer edges if needed */
    .row > * {
      /* No extra styles needed, but you can add margin if you don't use gap */
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="row">
      <div class="column">
        <h2>Column 1</h2>
        <p>Responsive flexbox column</p>
      </div>
      <div class="column">
        <h2>Column 2</h2>
        <p>Stack on small screens</p>
      </div>
      <div class="column">
        <h2>Column 3</h2>
        <p>Automatically wrap</p>
      </div>
    </div>
  </div>
</body>
</html>
```

**How it works:**

- On large screens (`> 3 * 300px + gaps`), three columns appear in a row.
- On medium screens (between ~600px and 900px), one column wraps to the next line, leaving two on top and one below.
- On small screens (less than 600px), all columns become full‑width and stack vertically.

You can tweak the `300px` inside `flex: 1 1 300px;` to change the wrapping threshold.

---

## When to Choose Flexbox over CSS Grid

- **Flexbox** is ideal when you want columns to wrap naturally based on their content or a flexible minimum width, without defining an explicit number of columns per row.
- **CSS Grid** is better if you need a strictly defined 3‑column grid (e.g., exactly 3 columns on desktop and exactly 1 on mobile) with more control over alignment in both rows and columns.

For a simple, adaptive three‑column layout that gracefully wraps, flexbox with `flex-wrap` and a `flex‑basis` is often the quickest and cleanest solution.

