```rust
use std::sync::{Arc, Mutex, Condvar};

/// A simple synchronization primitive that allows one or more threads to wait
/// until a signal is given. Once signaled, all current and future calls to `wait`
/// return immediately.
pub struct SignalGuard {
    mutex: Mutex<bool>,
    condvar: Condvar,
}

impl SignalGuard {
    /// Creates a new `SignalGuard` in the unsignaled state.
    pub fn new() -> Self {
        SignalGuard {
            mutex: Mutex::new(false),
            condvar: Condvar::new(),
        }
    }

    /// Blocks the current thread until the guard is signaled.
    /// If the guard has already been signaled, returns immediately.
    pub fn wait(&self) {
        let mut signaled = self.mutex.lock().unwrap();
        // Loop to protect against spurious wakeups.
        while !*signaled {
            signaled = self.condvar.wait(signaled).unwrap();
        }
    }

    /// Signals the guard, waking all waiting threads.
    /// Subsequent calls to `wait` will no longer block.
    pub fn signal(&self) {
        let mut signaled = self.mutex.lock().unwrap();
        *signaled = true;
        self.condvar.notify_all();
    }
}

/// A handle that can be used to wake a `SignalGuard`.
/// Created from an `Arc<SignalGuard>`, it allows another thread to
/// signal the guard without having direct access to it.
pub struct StopGuard {
    stop: Arc<SignalGuard>,
}

impl StopGuard {
    /// Creates a new `StopGuard` associated with the given `SignalGuard`.
    pub fn new(stop: Arc<SignalGuard>) -> Self {
        StopGuard { stop }
    }

    /// Wakes the associated `SignalGuard` (equivalent to calling `signal`).
    pub fn wake(&self) {
        self.stop.signal();
    }
}
```

Below is a Swift solution for finding all unique triplets that sum to zero in an array of integers. The code includes both a brute‑force approach (O(n³)) and an optimised two‑pointer approach (O(n²)). Although the problem states an array of 8 integers, the functions work for any size.

## Brute‑force approach O(n³)
- Three nested loops try every possible combination of indices.
- Each valid triplet is sorted and inserted into a `Set` to eliminate duplicates.
- Simple but very slow for larger inputs.

```swift
func threeSumBruteForce(_ nums: [Int]) -> [[Int]] {
    var result = Set<[Int]>()       // Set ensures uniqueness
    let n = nums.count
    for i in 0..<n {
        for j in i+1..<n {
            for k in j+1..<n {
                if nums[i] + nums[j] + nums[k] == 0 {
                    let triplet = [nums[i], nums[j], nums[k]].sorted()
                    result.insert(triplet)
                }
            }
        }
    }
    return Array(result)
}
```

## Optimised approach O(n²) – Two pointers
- Sort the array first (O(n log n)).
- For each element, use a left and right pointer to find a pair that sums to the negative of that element.
- Skip duplicate values to avoid repeating triplets.

```swift
func threeSumOptimized(_ nums: [Int]) -> [[Int]] {
    var result = [[Int]]()
    let nums = nums.sorted()
    let n = nums.count

    for i in 0..<n - 2 {
        // Skip duplicate starting values
        if i > 0 && nums[i] == nums[i - 1] { continue }

        var left = i + 1
        var right = n - 1
        let target = -nums[i]

        while left < right {
            let sum = nums[left] + nums[right]
            if sum == target {
                result.append([nums[i], nums[left], nums[right]])

                // Move pointers and skip duplicates
                while left < right && nums[left] == nums[left + 1] { left += 1 }
                while left < right && nums[right] == nums[right - 1] { right -= 1 }
                left += 1
                right -= 1
            } else if sum < target {
                left += 1
            } else {
                right -= 1
            }
        }
    }
    return result
}
```

## Example usage
```swift
let numbers = [-1, 0, 1, 2, -1, -4, 3, -2] // 8 integers

print("Brute-force:", threeSumBruteForce(numbers))
print("Optimised:  ", threeSumOptimized(numbers))
// Both output: [[-2, -1, 3], [-2, 0, 2], [-1, -1, 2], [-1, 0, 1]]
```

## When to use which?
- The brute‑force method is perfectly acceptable for **very small arrays** (like 8 elements) because the constant factor is low and the code is trivial.
- The optimised version is far better for **n > 50**, scaling with O(n²) instead of O(n³).

