      mountCtx.moveTo(0, CANVAS.height);
      for (let x = 0; x <= levelWidth; x += 70) {
        const y = CANVAS.height - 120 - random() * 130;
        mountCtx.lineTo(x, y);
      }
      mountCtx.lineTo(levelWidth, CANVAS.height);
      mountCtx.closePath();
      mountCtx.fill();
      // Near mountains
      mountCtx.fillStyle = '#5E7A4C';
      mountCtx.beginPath();
      mountCtx.moveTo(0, CANVAS.height);
      for (let x = 0; x <= levelWidth; x += 100) {
        const y = CANVAS.height - 60 - random() * 100;
        mountCtx.lineTo(x, y);
      }
      mountCtx.lineTo(levelWidth, CANVAS.height);
      mountCtx.closePath();
      mountCtx.fill();
      bgLayers.push({ canvas: mountainsCanvas, factor: 0.4 });

      // --- Layer 3: Trees (parallax factor 0.7) ---
      const treesCanvas = document.createElement('canvas');
      treesCanvas.width = levelWidth;
      treesCanvas.height = CANVAS.height;
      const treesCtx = treesCanvas.getContext('2d');
      for (let x = 0; x < levelWidth; x += 60) {
        const treeX = x + random() * 30;
        const treeY = CANVAS.height - 55 - random() * 25;
        const sc = 0.6 + random() * 0.8;
        // Trunk
        treesCtx.fillStyle = '#8B4513';
        treesCtx.fillRect(treeX - 3 * sc, treeY, 6 * sc, 25 * sc);
        // Canopy
        treesCtx.fillStyle = '#228B22';
        treesCtx.beginPath();
        treesCtx.arc(treeX, treeY - 8 * sc, 14 * sc, 0, Math.PI * 2);
        treesCtx.arc(treeX - 8 * sc, treeY + 2 * sc, 10 * sc, 0, Math.PI * 2);
        treesCtx.arc(treeX + 8 * sc, treeY + 2 * sc, 10 * sc, 0, Math.PI * 2);
        treesCtx.fill();
      }
      bgLayers.push({ canvas: treesCanvas, factor: 0.7 });
    }

    // =====================
    // LEVEL DATA
    // =====================
    // Each level defines its width, start position, platforms, and end flag.
    const levels = [
      {
        width: 3200,
        playerStart: { x: 50, y: 392 },
        platforms: [
          // Ground segments and floating platforms (x, y, w, h)
          { x: 0, y: 440, w: 350, h: 20 },
          { x: 450, y: 440, w: 200, h: 20 },
          { x: 700, y: 400, w: 100, h: 20 },
          { x: 850, y: 440, w: 200, h: 20 },
          { x: 1000, y: 380, w: 120, h: 20 },
          { x: 1150, y: 440, w: 200, h: 20 },
          { x: 1250, y: 340, w: 100, h: 20 },
          { x: 1400, y: 440, w: 250, h: 20 },
          { x: 1500, y: 360, w: 100, h: 20 },
          { x: 1650, y: 280, w: 80, h: 20 },
          { x: 1700, y: 440, w: 200, h: 20 },
          { x: 1850, y: 350, w: 120, h: 20 },
          { x: 1950, y: 250, w: 100, h: 20 },
          { x: 2050, y: 440, w: 300, h: 20 },
          { x: 2200, y: 400, w: 150, h: 20 },
          { x: 2400, y: 320, w: 100, h: 20 },
          { x: 2550, y: 440, w: 200, h: 20 },
          { x: 2700, y: 370, w: 150, h: 20 },
          { x: 2900, y: 440, w: 200, h: 20 },
          { x: 3100, y: 350, w: 100, h: 20 }, // final platform before flag
          // Extra floating platforms for variety
          { x: 380, y: 360, w: 60, h: 20 },
          { x: 600, y: 300, w: 80, h: 20 },
          { x: 800, y: 280, w: 60, h: 20 },
          { x: 1050, y: 280, w: 60, h: 20 },
          { x: 1300, y: 240, w: 60, h: 20 },
          { x: 1800, y: 200, w: 60, h: 20 },
          { x: 2100, y: 280, w: 60, h: 20 },
          { x: 2600, y: 280, w: 80, h: 20 }
        ],
        endFlag: { x: 3120, y: 280, w: 30, h: 70 }
      }
      // To add more levels, simply append additional objects here.
    ];

    // =====================
    // GAME STATE
    // =====================
    const state = {
      lives: 3,
      currentLevel: 0,
      gameStatus: 'playing', // 'playing', 'gameOver', 'levelComplete', 'win'
      player: {
        x: 50, y: 392,
        vx: 0, vy: 0,
        width: PLAYER_WIDTH,
        height: PLAYER_HEIGHT,
        onGround: false,
        facingRight: true,
        animationState: 'idle',    // 'idle', 'run', 'jump', 'fall'
        frameIndex: 0,
        frameTimer: 0,
        currentFrame: 0,
        prevAnimationState: 'idle'
      },
      camera: { x: 0, y: 0 },
      platforms: [],
      endFlag: null,
      levelWidth: 0,
      lastTime: 0
    };

    // =====================
    // INITIALIZATION
    // =====================
    /** Reset the entire game to level 1 with full lives */
    function restartGame() {
      state.lives = 3;
      state.currentLevel = 0;
      loadLevel(0);
      state.gameStatus = 'playing';
    }

    /** Load a specific level by its index in the `levels` array */
    function loadLevel(levelIndex) {
      if (levelIndex >= levels.length) {
        state.gameStatus = 'win';
        return;
      }
      const level = levels[levelIndex];
      state.currentLevel = levelIndex;
      state.platforms = level.platforms;
      state.endFlag = level.endFlag;
      state.levelWidth = level.width;
      state.player.x = level.playerStart.x;
      state.player.y = level.playerStart.y;
      state.player.vx = 0;
      state.player.vy = 0;
      state.player.onGround = false;
      state.player.facingRight = true;
      state.player.animationState = 'idle';
      state.player.frameIndex = 0;
      state.player.frameTimer = 0;
      state.player.currentFrame = 0;
      state.camera.x = 0;
      state.gameStatus = 'playing';
    }

    /** One‑time setup: generate sprites, background, and start the first level */
    function init() {
      generatePlayerFrames();
      // Generate background wide enough to cover the largest level
      const maxWidth = Math.max(...levels.map(l => l.width));
      generateBackground(maxWidth);
      loadLevel(0);
      state.lastTime = performance.now();
      requestAnimationFrame(gameLoop);
    }

    // =====================
    // UPDATE LOGIC
    // =====================
    function update(dt) {
      // Handle meta‑actions when the game is not in the 'playing' state
      if (state.gameStatus !== 'playing') {
        if (state.gameStatus === 'gameOver' && keys['KeyR']) {
          restartGame();
        }
        if (state.gameStatus === 'levelComplete' && keys['KeyR']) {
          state.currentLevel++;
          loadLevel(state.currentLevel);
        }
        if (state.gameStatus === 'win' && keys['KeyR']) {
          restartGame();
        }
        return;
      }

      const player = state.player;

      // --- Input ---
      if (keys['ArrowLeft'] || keys['KeyA']) {
        player.vx = -PLAYER_SPEED;
        player.facingRight = false;
      } else if (keys['ArrowRight'] || keys['KeyD']) {
        player.vx = PLAYER_SPEED;
        player.facingRight = true;
      } else {
        player.vx = 0;
      }

      if ((keys['ArrowUp'] || keys['KeyW'] || keys['Space']) && player.onGround) {
        player.vy = JUMP_VELOCITY;
        player.onGround = false;
      }

      // --- Gravity ---
      player.vy += GRAVITY * dt;
      if (player.vy > MAX_FALL_SPEED) player.vy = MAX_FALL_SPEED;

      // --- Horizontal movement & collision ---
      let newX = player.x + player.vx * dt;
      const playerRectX = { x: newX, y: player.y, w: player.width, h: player.height };
      for (const platform of state.platforms) {
        if (rectsOverlap(playerRectX, platform)) {
          // Push out of the platform on the X axis
          if (player.vx > 0) {
            newX = platform.x - player.width;
          } else if (player.vx < 0) {
            newX = platform.x + platform.w;
          }
          player.vx = 0;
        }
      }
      player.x = newX;
      // Clamp to level bounds
      if (player.x < 0) player.x = 0;
      if (player.x + player.width > state.levelWidth) player.x = state.levelWidth - player.width;

      // --- Vertical movement & collision ---
      let newY = player.y + player.vy * dt;
      const playerRectY = { x: player.x, y: newY, w: player.width, h: player.height };
      player.onGround = false;
      for (const platform of state.platforms) {
        if (rectsOverlap(playerRectY, platform)) {
          if (player.vy > 0) {            // falling – land on top
            newY = platform.y - player.height;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {     // jumping – hit bottom of platform
            newY = platform.y + platform.h;
            player.vy = 0;
          }
        }
      }
      player.y = newY;

      // Safety net: re‑check if player is standing exactly on a platform (vy == 0 case)
      if (!player.onGround) {
        for (const platform of state.platforms) {
          if (player.y + player.height >= platform.y &&
              player.y + player.height <= platform.y + 2 &&
              player.x + player.width > platform.x &&
              player.x < platform.x + platform.w) {
            player.onGround = true;
            player.vy = 0;
            player.y = platform.y - player.height;
            break;
          }
        }
      }

      // --- Death by falling ---
      if (player.y > CANVAS.height + 100) {
        killPlayer();
        if (state.gameStatus === 'gameOver') return; // stop updating if game ended
      }

      // --- Level complete ---
      if (state.endFlag) {
        const flagRect = state.endFlag;
        const playerRect = { x: player.x, y: player.y, w: player.width, h: player.height };
        if (rectsOverlap(playerRect, flagRect)) {
          state.gameStatus = 'levelComplete';
          return;
        }
      }

      // --- Animation state ---
      updateAnimation(dt);

      // --- Camera (follow player horizontally) ---
      state.camera.x = player.x - CANVAS.width / 2 + player.width / 2;
      state.camera.x = Math.max(0, Math.min(state.camera.x, state.levelWidth - CANVAS.width));
    }

    /** Handle player death: lose a life, respawn or trigger game over */
    function killPlayer() {
      state.lives--;
      if (state.lives <= 0) {
        state.gameStatus = 'gameOver';
      } else {
        const level = levels[state.currentLevel];
        state.player.x = level.playerStart.x;
        state.player.y = level.playerStart.y;
        state.player.vx = 0;
        state.player.vy = 0;
        state.player.onGround = false;
        state.player.animationState = 'idle';
        state.player.frameIndex = 0;
        state.player.frameTimer = 0;
        state.player.currentFrame = 0;
      }
    }

    /** Cycle animation frames based on the player's state */
    function updateAnimation(dt) {
      const player = state.player;
      // Determine high‑level animation state
      if (!player.onGround) {
        player.animationState = player.vy < 0 ? 'jump' : 'fall';
      } else if (Math.abs(player.vx) > 0) {
        player.animationState = 'run';
      } else {
        player.animationState = 'idle';
      }

      // Map state to an array of frame indices
      let frames;
      switch (player.animationState) {
        case 'idle': frames = [0]; break;
        case 'run':  frames = [1, 2, 3, 4]; break;
        case 'jump': frames = [5]; break;
        case 'fall': frames = [6]; break;
        default:     frames = [0];
      }

      // Reset frame index when the state changes
      if (player.prevAnimationState !== player.animationState) {
        player.frameIndex = 0;
        player.frameTimer = 0;
        player.prevAnimationState = player.animationState;
      }

      // Advance frame timer and index
      player.frameTimer += dt;
      if (player.frameTimer >= 0.08) {      // ~12 fps
        player.frameTimer = 0;
        player.frameIndex = (player.frameIndex + 1) % frames.length;
      }
      player.currentFrame = frames[player.frameIndex];
    }

    // =====================
    // RENDERING
    // =====================
    function render() {
      CTX.clearRect(0, 0, CANVAS.width, CANVAS.height);

      // Sky gradient (static)
      const skyGrad = CTX.createLinearGradient(0, 0, 0, CANVAS.height);
      skyGrad.addColorStop(0, '#87CEEB');
      skyGrad.addColorStop(1, '#E0F6FF');
      CTX.fillStyle = skyGrad;
      CTX.fillRect(0, 0, CANVAS.width, CANVAS.height);

      // Parallax background layers
      for (const layer of bgLayers) {
        const offsetX = state.camera.x * layer.factor;
        CTX.drawImage(
          layer.canvas,
          offsetX, 0, CANVAS.width, CANVAS.height,
          0, 0, CANVAS.width, CANVAS.height
        );
      }

      // Platforms
      for (const p of state.platforms) {
        const sx = p.x - state.camera.x;
        const sy = p.y - state.camera.y;
        if (sx + p.w < 0 || sx > CANVAS.width) continue; // cull off‑screen
        CTX.fillStyle = '#8B5A2B';   // brown body
        CTX.fillRect(sx, sy, p.w, p.h);
        CTX.fillStyle = '#228B22';   // green grass top
        CTX.fillRect(sx, sy, p.w, 4);
      }

      // End‑of‑level flag
      if (state.endFlag) {
        const f = state.endFlag;
        const sx = f.x - state.camera.x;
        const sy = f.y - state.camera.y;
        // Pole
        CTX.fillStyle = '#AAAAAA';
        CTX.fillRect(sx + 10, sy, 10, f.h);
        // Flag triangle
        CTX.fillStyle = '#FF4444';
        CTX.beginPath();
        CTX.moveTo(sx + 20, sy + 10);
        CTX.lineTo(sx + 50, sy + 25);
        CTX.lineTo(sx + 20, sy + 40);
        CTX.fill();
      }

      // Player sprite
      const player = state.player;
      const screenX = player.x - state.camera.x;
      const screenY = player.y - state.camera.y;
      const frameCanvas = playerFrames[player.currentFrame];
      CTX.save();
      if (!player.facingRight) {
        // Flip horizontally
        CTX.translate(screenX + PLAYER_WIDTH, screenY);
        CTX.scale(-1, 1);
        CTX.drawImage(frameCanvas, 0, 0);
      } else {
        CTX.drawImage(frameCanvas, screenX, screenY);
      }
      CTX.restore();

      // UI: lives counter
      CTX.fillStyle = '#FFF';
      CTX.font = '20px Arial';
      CTX.fillText('Lives: ' + state.lives, 20, 40);

      // UI: overlays for special game states
      if (state.gameStatus === 'gameOver') {
        drawOverlay('Game Over', 'Press R to restart');
      } else if (state.gameStatus === 'levelComplete') {
        drawOverlay('Level Complete!', 'Press R to continue');
      } else if (state.gameStatus === 'win') {
        drawOverlay('You Win!', 'Press R to play again');
      }
    }

    /** Helper to draw a centred overlay with a title and subtitle */
    function drawOverlay(title, subtitle) {
      CTX.fillStyle = 'rgba(0, 0, 0, 0.7)';
      CTX.fillRect(0, 0, CANVAS.width, CANVAS.height);
      CTX.fillStyle = '#FFF';
      CTX.textAlign = 'center';
      CTX.font = '40px Arial';
      CTX.fillText(title, CANVAS.width / 2, CANVAS.height / 2 - 20);
      CTX.font = '20px Arial';
      CTX.fillText(subtitle, CANVAS.width / 2, CANVAS.height / 2 + 20);
      CTX.textAlign = 'left';
    }

    // =====================
    // GAME LOOP
    // =====================
    function gameLoop(timestamp) {
      const dt = Math.min((timestamp - state.lastTime) / 1000, 0.05); // cap to ~20 fps minimum
      state.lastTime = timestamp;
      update(dt);
      render();
      requestAnimationFrame(gameLoop);
    }

    // =====================
    // START THE GAME
    // =====================
    init();
  </script>
